--[[
	Midnight Helper — Tiefen-Coach tip bodies (per delve, EN + NL).
	Sources: primarily Icy Veins delve guides; Torment's Rise also Boostmatch/Wowhead.
	Line breaks use |n; bullets use • for readable lists in-game.

	Locale audit: 11 delves × 4 sections = 44 body keys in enUS and nlNL each (88 total).
]]

local _, ns = ...

local function merge(target, patch)
	if not target or not patch then
		return
	end
	for k, v in pairs(patch) do
		target[k] = v
	end
end

merge(ns._mhLocales and ns._mhLocales.enUS, {
	-- Display names (coach title / picker; rosterName stays English for POI matching)
	DELVE_NAME_SHADOW_ENCLAVE = "The Shadow Enclave",
	DELVE_NAME_COLLEGIATE_CALAMITY = "Collegiate Calamity",
	DELVE_NAME_THE_DARKWAY = "The Darkway",
	DELVE_NAME_PARHELION_PLAZA = "Parhelion Plaza",
	DELVE_NAME_ATAL_AMAN = "Atal'Aman",
	DELVE_NAME_TWILIGHT_CRYPTS = "Twilight Crypts",
	DELVE_NAME_GULF_OF_MEMORY = "The Gulf of Memory",
	DELVE_NAME_GRUDGE_PIT = "The Grudge Pit",
	DELVE_NAME_SUNKILLER_SANCTUM = "Sunkiller Sanctum",
	DELVE_NAME_SHADOWGUARD_POINT = "Shadowguard Point",
	DELVE_NAME_TORMENTS_RISE = "Torment's Rise",

	-- The Shadow Enclave
	DELVE_TIP_SHADOW_ENCLAVE_OVERVIEW = "• Southwest Eversong Woods (Ruins of Deatholme).|n• Four variants: Mirror Shine, Shadowy Supplies, Traitor's Due, and Infiltrate and Ameliorate (new in 12.1).|n• Traitor's Due: stop rituals, void orbs, cultists (leveling).|n• Mirror Shine, Shadowy Supplies and Traitor's Due end at Lord Antenorian. Infiltrate and Ameliorate ends at Abominable Blunder.",
	DELVE_TIP_SHADOW_ENCLAVE_ROUTE = "• Mirror Shine: carry mirrors through dark halls; hit Shadow Nexuses to spread light (avoids grues).|n• Shadowy Supplies: loot Twilight's Blade valuables from mobs or the ground.|n• Traitor's Due: chase Antenorian through the delve to the boss room.|n• Infiltrate and Ameliorate: talk to Scout Lok'aemon, then kick 5 Ula'tek Summoners into the abyss.|n• Infiltrate and Ameliorate: sabotage 4 cauldrons by adding odd ingredients. Some ingredients sit up high: use the jumping mushrooms.|n• Infiltrate and Ameliorate: next, kill the Ula'tek Supreme Summoner and watch the summoning. After that comes Abominable Blunder, the final boss.|n• Infiltrate and Ameliorate: pick up {SPELL:@fungal_pharmacon} and throw it on the poison pools to clean them. It also hurts enemies near where it lands.",
	DELVE_TIP_SHADOW_ENCLAVE_TRASH = "• In mirror light, you and enemies are Dazzled (higher crit chance).|n• Interrupt shadow casters.|n• Clear Twilight's Blade during Supplies.|n• Do not stack in hazardous ground; pull carefully in tight corridors.",
	DELVE_TIP_SHADOW_ENCLAVE_BOSS = "• Lord Antenorian: interrupt {SPELL:@shadow_bolt} whenever you can.|n• Lord Antenorian: his teleports leave a damaging puddle. Keep him near the center.|n• Lord Antenorian: {SPELL:@shadowveil_annihilation} is a deadly channel. Destroy the 3 Shadow Orbs: only the orb without a shield takes damage, and each kill removes the next shield.|n• Lord Antenorian: with all orbs dead his shield breaks, the channel stops, and he takes extra damage for a few seconds.|n• Lord Antenorian: save your burst for the orbs. Valeera helps break them.|n• Abominable Blunder (Infiltrate and Ameliorate): Corrosive Bile is his basic poison attack. Heal through it.|n• Abominable Blunder (Infiltrate and Ameliorate): {SPELL:@searing_spew} hurts and slows everyone within 14 yards of him. Move away when he casts it.|n• Abominable Blunder (Infiltrate and Ameliorate): Acid Spray sends waves of acid for a few seconds. Keep sidestepping until it ends.",

	-- Collegiate Calamity
	DELVE_TIP_COLLEGIATE_CALAMITY_OVERVIEW = "• Northwest Silvermoon / Eversong Woods (Thalassian University).|n• Academy Under Siege -> Voidscorned Vagrant.|n• Faculty of Fear -> Infiltrator Garand.|n• Invasive Glow -> Hydrangea.|n• Academic Antitoxin (on the map: An Elementary Antidote): no final boss. A treasure appears instead.",
	DELVE_TIP_COLLEGIATE_CALAMITY_ROUTE = "• Under Siege: close void portals and kill Devouring Host.|n• Faculty of Fear: Eye of Revelation — suspicious students glow yellow through walls.|n• Invasive Glow: Deweeder kills small Lightbloom and damages large ones.|n• Clear Luminibulb patches on the main level.|n• Academic Antitoxin: speak to Sir Finley Mrrgglton, then gather 10 Research Tomes.|n• Academic Antitoxin: then collect ingredients and give the antidote to 7 Envenomed Denizens. Both count at the same time.|n• Academic Antitoxin: the ingredient bar needs 400. Small ingredients give 2, medium ones 20 and big ones 35, so grab the big ones.|n• Academic Antitoxin: {SPELL:@fungal_pharmacon} cleans the poison pools and also hits enemies within 5 yards of where it lands.",
	DELVE_TIP_COLLEGIATE_CALAMITY_TRASH = "• Under Siege: prioritize portal closers.|n• Faculty: reveal disguised students, then kill before they ambush.|n• Glow: channel Deweeder while moving.|n• Do not skip Luminibulb patches or the run drags.",
	DELVE_TIP_COLLEGIATE_CALAMITY_BOSS = "• Hydrangea (Glow): kill {SPELL:@wildroot_weave} roots before {SPELL:@lightbloom_salvo}; dodge light zones.|n• Garand (Faculty): dodge {SPELL:@shadow_laceration} or use a defensive; spread for {SPELL:@twilight_crash} jumps.|n• Voidscorned Vagrant (Siege): sidestep {SPELL:@void_eruption}; always interrupt {SPELL:@terrifying_power}.|n• Academic Antitoxin: there is no final boss. The treasure appears when the last step is done.",

	-- The Darkway
	DELVE_TIP_THE_DARKWAY_OVERVIEW = "• North Silvermoon / Eversong Woods (the Arcway).|n• Focusers Under Pressure, Leyline Technician, Ogre Powered (7 Unstable Aberrations).|n• Focusers, Leyline, Ogre Powered -> Infiltrator Gulkat.|n• Eggsplosive Growth (12.1) -> Replicating Venomborne.",
	DELVE_TIP_THE_DARKWAY_ROUTE = "• Focusers: find ley line focusers and return them to the delve center.|n• Leyline: tap conduits once per line to empower three focus crystals.|n• Ogre Powered: kill 7 Unstable Aberrations in the middle section before Gulkat.",
	DELVE_TIP_THE_DARKWAY_TRASH = "• Interrupt Twilight Seekers and Arcane Deluge on aberrations.|n• Leyline variant: kill Twilight's Blade while routing power.|n• Pull away from corners in narrow Arcway halls.",
	DELVE_TIP_THE_DARKWAY_BOSS = "• Interrupt Twilight Seekers.|n• Dodge {SPELL:@abyssal_burst} (frontal cone).|n• {SPELL:@illusory_deceit}: exploding illusions — keep distance while handling Gulkat.|n• Replicating Venomborne: kill the Lesser Venomborne from {SPELL:@serpentogenesis} at once — alive at his next cast, they heal him; step out of {SPELL:@venom_splash_venomborne} pools (damage + slow); {SPELL:@hydra_strike} leaves a stacking DoT.",

	-- Parhelion Plaza
	DELVE_TIP_PARHELION_PLAZA_OVERVIEW = "• West Isle of Quel'Danas (Sunwell area).|n• Unlocks with March on Quel'Danas (late March 2026).|n• Bombing Run, Holding the Line and March of the Arcane Brigade end at Gladius Slaurna.|n• One of the harder Midnight delves.|n• Caustic Crush (new in 12.1): Slime Shamen of Ula'tek summon slimes and send waves of poison. The last goal is a Ritual Pillar, not Gladius Slaurna.",
	DELVE_TIP_PARHELION_PLAZA_ROUTE = "• Bombing Run: Improvised Arcane Device for void portals (40s carry limit; drop in combat).|n• Holding the Line: Tempest Keep weapons + rebuild barricades.|n• March of the Arcane Brigade: wake the Sentinel machines; they walk to the void pylons. Destroy 3 pylons and kill Devouring Host to fill the bar.|n• Caustic Crush: talk to Vindicator Xayann. Then kill the slimes, 4 Shaman Slimecallers and 6 Ula'tek Wavecallers.|n• Caustic Crush: pick up {SPELL:@fungal_pharmacon} on the way. Throw it on the Ula'tek Poison Pools to clean them. It also hurts enemies near where it lands.|n• Caustic Crush: the goals also ask you to use a burrow. The very last goal is to destroy the Ritual Pillar.",
	DELVE_TIP_PARHELION_PLAZA_TRASH = "• Bombing Run: never leave a portal before you blow it up. It closes for good and you cannot finish the run.|n• Clear Devouring Host waves before Slaurna.|n• Caustic Crush: dodge every poison wave. A hit stuns you and deals heavy Nature damage.",
	DELVE_TIP_PARHELION_PLAZA_BOSS = "• Gladius Slaurna: kill his three Sacrificial Voidcallers fast and interrupt their Void Bolt.|n• Gladius Slaurna: every Voidcaller still alive when {SPELL:@devouring_nova} ends makes him hit harder and take less damage. On high tiers that can wipe you.|n• Gladius Slaurna: step out of the {SPELL:@voidscar_raze} line. It often aims at Valeera, so do not stand between them.|n• Gladius Slaurna: fight near the center, so {SPELL:@devouring_nova} cannot knock you off the platform.",

	-- Atal'Aman
	DELVE_TIP_ATAL_AMAN_OVERVIEW = "• West Zul'Aman (Eversong border).|n• Ritual Interrupted, Toadly Unbecoming, Totem Annihilation.|n• Ritual Interrupted, Toadly Unbecoming and Totem Annihilation end at Spiritflayer Jin'Ma.|n• Season 2, Venomous Vapors: final boss Disciple of Vashnik (also in Shadowguard Point).",
	DELVE_TIP_ATAL_AMAN_ROUTE = "• Ritual: rescue kidnapped Spiritpaw furbolgs across the delve.|n• Toadly: dispel hexed Amani with Vilebranch Hex Stick while killing invaders.|n• Totem: destroy cursed totems to free Akil'zon; use eagles for alternate approaches.|n• Venomous Vapors: open the 2 chests in the first room and pick up Marla's tools: {SPELL:@venomous_fireball}, which you throw into a Toxic Cloud to blow it up (stand clear), and a tool that makes you jump very high. Defeat the 5 Venom Vipers; the Disciple of Vashnik waits at the end.",
	DELVE_TIP_ATAL_AMAN_TRASH = "• Interrupt Vilebranch casts.|n• Totem variant: prioritize totems on the path.|n• Pull beasts away from hexed NPCs you are trying to save.|n• Venomous Vapors: the Venom Vipers are part of the objective, so kill all 5.",
	DELVE_TIP_ATAL_AMAN_BOSS = "• {SPELL:@flaying_knife} splits spirits — each collected spirit gives +10% damage (pick them up deliberately).|n• Dodge {SPELL:@raging_spirits} on the floor.|n• Before {SPELL:@claim_spirits} ends, grab your spirits or Jin'Ma gains their buff.|n• Disciple of Vashnik: always interrupt {SPELL:@malignance}, a 4-second volley of venom globs that stack damage and slow you. Valeera does not kick it every time, so do it yourself.|n• Disciple of Vashnik: {SPELL:@toxic_froth} is heavy poison damage for 8 seconds, and hiding behind a wall no longer helps. Cleanse the poison if your class can, use a defensive, or set Valeera to healer; grab the healing orbs after it.|n• Disciple of Vashnik: {SPELL:@living_venom} knocks you back and calls a slime. Step out of the area around him and kill the slime before it reaches you. On Tier 11 many players call him the hardest boss this season: drop a tier if you keep dying.",

	-- Twilight Crypts
	DELVE_TIP_TWILIGHT_CRYPTS_OVERVIEW = "• Southwest Zul'Aman (Broken Throne).|n• Loosed Loa (avoid Mot'amra), Party Crasher, Trapped!, and new in 12.1: Why'd it have to be snakes?|n• Loosed Loa, Party Crasher and Trapped! end at Blademaster Darza. Why'd it have to be snakes? ends at Replicating Venomborne.",
	DELVE_TIP_TWILIGHT_CRYPTS_ROUTE = "• Loosed Loa: Evasive Elixir to explore; kill Skeleton Charmers and totems — track Mot'amra, do not cross his path.|n• Loosed Loa: since the 10 Sep hotfix, Explorer's League Supplies and an Abandoned Restoration Stone appear in this variant.|n• Party Crasher: kill the 4 Twilight Summoners (they show on your map) and pull 7 Suspicious Levers. Bear traps stun you for about 2 seconds.|n• Trapped: save hostages and find levers through the maze.|n• Why'd it have to be snakes?: help Harrison Jones find the lost relics in the crypts.|n• Why'd it have to be snakes?: stepping on the snakes is part of the goal, but they explode when you step on them.|n• Why'd it have to be snakes?: pick up {SPELL:@fungal_pharmacon} and throw it on poison patches to clean them.",
	DELVE_TIP_TWILIGHT_CRYPTS_TRASH = "• Mot'amra hits hard with knockback if you walk into him.|n• Party Crasher: watch trap tiles.|n• Interrupt Twilight's Blade summoners.",
	DELVE_TIP_TWILIGHT_CRYPTS_BOSS = "• Blademaster Darza: sidestep {SPELL:@shade_cleave}. Fighting close stops her {SPELL:@dark_pursuit} gap-closer.|n• Blademaster Darza: {SPELL:@bask_in_the_twilight} leaves a void zone on the floor.|n• Drag Darza out of it or she gains +30% damage while standing inside.|n• Replicating Venomborne (Why'd it have to be snakes?): kill the Lesser Venomborne from {SPELL:@serpentogenesis} at once. If they are still alive at his next cast, they heal him.|n• Replicating Venomborne (Why'd it have to be snakes?): step out of {SPELL:@venom_splash_venomborne} pools. They hurt and slow you.|n• Replicating Venomborne (Why'd it have to be snakes?): {SPELL:@hydra_strike} leaves poison damage on you that stacks. Watch the stacks and heal through it.",

	-- The Gulf of Memory
	DELVE_TIP_GULF_OF_MEMORY_OVERVIEW = "• West Harandar (Den of Echoes / Har'alnor).|n• Three variants.|n• Bosses: Lumenia (Munchies / Sporasaur) and Mul'tha'ul (Descent of the Haranir).",
	DELVE_TIP_GULF_OF_MEMORY_ROUTE = "• Alnmoth Munchies: extra-action Alnmoth Storm while moving — devour bushes or help vs Rutaani.|n• Descent: light giant candles; more damage taken in dark areas.|n• Sporasaur: kick green-reticle Sporbits into Sporasaurs to remove their shield.",
	DELVE_TIP_GULF_OF_MEMORY_TRASH = "• Stay in lit areas during Descent.|n• Kick Sporbits before they explode.|n• Channel Alnmoth Storm while moving — you can move and cast.",
	DELVE_TIP_GULF_OF_MEMORY_BOSS = "• Lumenia: kill {SPELL:@radiant_command} add before it reaches you (explodes).|n• Dodge {SPELL:@searing_light} patches unless using them on the add.|n• Mul'tha'ul: interrupt or dispel {SPELL:@hopeless_curse}.|n• Kite away from {SPELL:@tear_it_down} tentacles.|n• Keep distance during {SPELL:@unanswered_call} (high damage, slow walk).",

	-- The Grudge Pit
	DELVE_TIP_GRUDGE_PIT_OVERVIEW = "• Southeast Harandar.|n• Lightbloom Invasion -> Brightthorn.|n• Arena Champion -> Gyrospore.|n• Dastardly Rotstalk -> Mycomight.|n• Fungal Pharmacon -> Replicating Venomborne.",
	DELVE_TIP_GRUDGE_PIT_ROUTE = "• Arena Champion: beat up the fighters, kill Bogdamp, Moldrus and 5 Spewing Deathcaps, collect 6 Mold Samples and plant your banner. Then Gyrospore comes.|n• Dastardly Rotstalk: heel role — punt fans, taunt crowd (can move while taunting).|n• Lightbloom Invasion: waves, free fighters to blow up spawn points, build defenses.",
	DELVE_TIP_GRUDGE_PIT_TRASH = "• Arena Champion: use the friendly Sporbits. They deal bonus damage to the arena fighters.|n• Lightbloom Invasion: clear the waves before the boss.|n• Rotstalk: keep crowd control — fans hurt if ignored.",
	DELVE_TIP_GRUDGE_PIT_BOSS = "• Brightthorn: sidestep {SPELL:@solar_charge} (leaves Overbloom zones); interrupt {SPELL:@bloom_thorn}; turn away before {SPELL:@blinding_burst}.|n• Gyrospore: dodge {SPELL:@fungalstorm} zones, then burst during 10s dizzy; step back from {SPELL:@fungsplosion}; sidestep {SPELL:@fungal_charge}.|n• Mycomight: drop {SPELL:@rancid_rain} puddles away from fight area; dodge {SPELL:@fungis_fist} shockwaves; sidestep {SPELL:@fling_chair}.|n• Replicating Venomborne: kill the Lesser Venomborne from {SPELL:@serpentogenesis} at once — alive at his next cast, they heal him; step out of {SPELL:@venom_splash_venomborne} pools (damage + slow); {SPELL:@hydra_strike} leaves a stacking DoT.|n• Gyrospore: DBM and your delve history call this fight Spinshroom, a name Blizzard reused from an old boss. It is the same fight.",

	-- Sunkiller Sanctum
	DELVE_TIP_SUNKILLER_SANCTUM_OVERVIEW = "• East Voidstorm (Voidspire entrance).|n• Core of the Problem and The Gravitational Effect end at Esuritus. Not What I Expected has no boss.|n• Not What I Expected: no boss — ends after 3 Corrupted Umbraroot kills.",
	DELVE_TIP_SUNKILLER_SANCTUM_ROUTE = "• Core of the Problem: portals + stop Domanaar stealing Energized Orbs (orb buff: speed + damage reduction).|n• Not What I Expected: click 7 Lightbloom Crates, use the Sanctum Security Panel and fill the kill bar (Lightbloom and Void enemies both count). Then kill 3 Corrupted Umbraroot.|n• Gravitational Effect: use micro-singularities to navigate and disable boss shields.|n• Not What I Expected: run through a Displacement Portal. A copy of you then fights at your side for about 5 minutes.",
	DELVE_TIP_SUNKILLER_SANCTUM_TRASH = "• Pick up orbs in Core variant for survivability.|n• Not What I Expected: the 3 Corrupted Umbraroot are elites. Pull them one at a time.|n• Not What I Expected: interrupt the Lightbloom Beam of the Corrupted Umbraroot, and sidestep Blooming Bile (a frontal that spawns adds) and Rotting Charge (it leaves a puddle).",
	DELVE_TIP_SUNKILLER_SANCTUM_BOSS = "• Kill all Voidcallers before {SPELL:@gorge} or he gains +damage for 30s per devour.|n• Interrupt {SPELL:@calling_bolt}.|n• When {SPELL:@coalescing_malediction} ends or is dispelled, a Voidcaller spawns. Dispel it only when you are ready to kill that add.|n• Dodge {SPELL:@crushing_rift} (spawns 4 Voidcallers).",

	-- Shadowguard Point
	DELVE_TIP_SHADOWGUARD_POINT_OVERVIEW = "• West Voidstorm (north of Abundant Voidburrow).|n• Four variants. In three you fight the Shadowguard Ethereals; in Basilisk Blitz you help them take the point back.|n• Final boss in three variants: Chief-Arcanist Patram. Basilisk Blitz ends at the Disciple of Vashnik instead.|n• Season 2, Basilisk Blitz: final boss Disciple of Vashnik (also in Atal'Aman).",
	DELVE_TIP_SHADOWGUARD_POINT_ROUTE = "• Calamitous: overload Void Stabilizers with Arcane Charges (speed buff; explosions kill mobs — do not stand in them).|n• Captured Wildlife: free void creatures (their AoE can still hit you).|n• Stolen Mana: pick up the rifle and use Galvanic Blast on the mana containers until the Arcane Barrier drops.|n• Basilisk Blitz: talk to the wounded ethereal at the start. Then reconfigure the Energy Distributor and kill the Ula'tek Basilisk.|n• Basilisk Blitz: use the Waygate to move on. Then reconfigure the 4 Power Generators and kill the 4 Energized Basilisks.|n• Basilisk Blitz: the Disciple of Vashnik only becomes your goal after all 4 Energized Basilisks are dead.",
	DELVE_TIP_SHADOWGUARD_POINT_TRASH = "• Calamitous: plan overloads safely while carrying Arcane Charges.|n• Ethereal packs: interrupt casts.|n• Wildlife variant: give freed creatures space.|n• Basilisk Blitz: while a basilisk's barrier holds, it throws poison bolts at you. Walking into the barrier stuns you for a few seconds.",
	DELVE_TIP_SHADOWGUARD_POINT_BOSS = "• Interrupt {SPELL:@void_bolt_patram}.|n• Kill Void Emissary before {SPELL:@submit_to_the_void} ends (you get Vers + CDR; Patram gets the buff if you fail).|n• Sidestep {SPELL:@discordant_hymn} void zones (slow + damage).|n• Disciple of Vashnik: always interrupt {SPELL:@malignance}, a 4-second volley of venom globs that stack damage and slow you. Valeera does not kick it every time, so do it yourself.|n• Disciple of Vashnik: {SPELL:@toxic_froth} is heavy poison damage for 8 seconds, and hiding behind a wall no longer helps. Cleanse the poison if your class can, use a defensive, or set Valeera to healer; grab the healing orbs after it.|n• Disciple of Vashnik: {SPELL:@living_venom} knocks you back and calls a slime. Step out of the area around him and kill the slime before it reaches you. On Tier 11 many players call him the hardest boss this season: drop a tier if you keep dying.",

	-- Torment's Rise (Nemesis)
	DELVE_TIP_TORMENTS_RISE_OVERVIEW = "• Voidstorm — Season 1 Nemesis Delve (capstone).|n• Tier ? after any T7 with 1+ life; Tier ?? after any T10 with 1+ life.|n• Boss: Nullaeus.|n• Healer Valeera strongly recommended on Tier ??.",
	DELVE_TIP_TORMENTS_RISE_ROUTE = "• Dedicated instance portal (not a rotating world delve).|n• Use Adventure Guide (Shift-J) or TomTom.|n• Weekly bounty: Beacon of Hope can pull Nullaeus into a normal delve at 50% instead.",
	DELVE_TIP_TORMENTS_RISE_TRASH = "• Pactsworn mobs live in regular delves, not inside Torment's Rise.|n• Pace cooldowns — save defensives and interrupts for Nullaeus.",
	DELVE_TIP_TORMENTS_RISE_BOSS = "• Interrupt {SPELL:@devouring_essence} every cast (DoT + feeds {SPELL:@umbral_rage} stacks).|n• {SPELL:@dread_portal}: 100% damage reduction until all adds die — full AoE burst on spawn.|n• {SPELL:@oblivion_shell} phase is a DPS check.|n• {SPELL:@umbral_rage}: +10% damage per stack if adds or DoTs linger — kill adds fast.",

	-- Party chat (short; spell tokens expand to links for the whole group)
	DELVE_CHAT_SHADOW_ENCLAVE_OVERVIEW = "SW Eversong (Deatholme). Mirrors, supplies, traitor: boss Lord Antenorian. Infiltrate and Ameliorate: boss Abominable Blunder.",
	DELVE_CHAT_SHADOW_ENCLAVE_ROUTE = "Mirrors: hit Shadow Nexuses for light. Supplies: loot Twilight valuables. Traitor: stop rituals, chase to boss.",
	DELVE_CHAT_SHADOW_ENCLAVE_TRASH = "Mirror light = Dazzled (more crits). Interrupt shadow casters. Don't stack on bad ground.",
	DELVE_CHAT_SHADOW_ENCLAVE_BOSS = "Kick {SPELL:@shadow_bolt}. Teleport leaves a pool — keep him central. {SPELL:@shadowveil_annihilation}: kill 3 Orbs (only the unshielded orb). Burst orbs.",

	DELVE_CHAT_COLLEGIATE_CALAMITY_OVERVIEW = "NW Silvermoon / Eversong (university). Siege, Faculty and Glow each end in a boss. Academic Antitoxin has no boss, only a chest.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_ROUTE = "Siege: close void portals. Faculty: Eye of Revelation, yellow students through walls. Glow: Deweeder + Luminibulb. Antitoxin: 10 tomes, ingredients, cure 7.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_TRASH = "Siege: portals first. Faculty: reveal then kill students. Glow: channel Deweeder while moving.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_BOSS = "Hydrangea: kill {SPELL:@wildroot_weave} before {SPELL:@lightbloom_salvo}. Garand: dodge {SPELL:@shadow_laceration}, spread {SPELL:@twilight_crash}. Vagrant: kick {SPELL:@terrifying_power}.",

	DELVE_CHAT_THE_DARKWAY_OVERVIEW = "North Silvermoon Arcway. Focusers, Leyline or 7 Aberrations: boss Infiltrator Gulkat. Eggsplosive Growth: boss Replicating Venomborne.",
	DELVE_CHAT_THE_DARKWAY_ROUTE = "Focusers: return ley focusers to center. Leyline: tap conduits for 3 crystals. Ogre: kill 7 Unstable Aberrations mid.",
	DELVE_CHAT_THE_DARKWAY_TRASH = "Interrupt Twilight Seekers and Arcane Deluge. Pull out of tight corners.",
	DELVE_CHAT_THE_DARKWAY_BOSS = "Kick Seekers. Dodge {SPELL:@abyssal_burst}. {SPELL:@illusory_deceit}: stay clear of exploding illusions.",

	DELVE_CHAT_PARHELION_PLAZA_OVERVIEW = "West Isle of Quel'Danas (Sunwell), a harder delve. Bombing Run / Holding the Line / Brigade: boss Gladius Slaurna. Caustic Crush: destroy the Ritual Pillar.",
	DELVE_CHAT_PARHELION_PLAZA_ROUTE = "Bombing Run: arcane device for portals (40s carry). Holding the Line: weapons + barricades. Brigade: sentinels vs pylons. Caustic Crush: kill Slimecallers and Wavecallers.",
	DELVE_CHAT_PARHELION_PLAZA_TRASH = "Kick Voidcaller Void Bolt. Clear Devouring Host waves before boss.",
	DELVE_CHAT_PARHELION_PLAZA_BOSS = "Kill 3 Voidcallers fast (kick Void Bolt). If one lives through {SPELL:@devouring_nova}, Slaurna buffs hard. Dodge {SPELL:@voidscar_raze}, fight center.",

	DELVE_CHAT_ATAL_AMAN_OVERVIEW = "West Zul'Aman. Ritual / Toadly / Totem: boss Spiritflayer Jin'Ma. Venomous Vapors: boss Disciple of Vashnik.",
	DELVE_CHAT_ATAL_AMAN_ROUTE = "Ritual: rescue furbolgs. Toadly: Hex Stick on hexed Amani. Totem: destroy totems, free Akil'zon.",
	DELVE_CHAT_ATAL_AMAN_TRASH = "Interrupt Vilebranch. Totem run: totems on path first.",
	DELVE_CHAT_ATAL_AMAN_BOSS = "{SPELL:@flaying_knife} spirits = +10% dmg each — pick yours up. Dodge {SPELL:@raging_spirits}. Before {SPELL:@claim_spirits}, collect spirits or Jin'Ma buffs.",

	DELVE_CHAT_TWILIGHT_CRYPTS_OVERVIEW = "SW Zul'Aman (Broken Throne). Loa / Party Crasher / Trapped: boss Blademaster Darza. Why'd it have to be snakes?: boss Replicating Venomborne.",
	DELVE_CHAT_TWILIGHT_CRYPTS_ROUTE = "Loa: don't cross Mot'amra's path. Party Crasher: escort, traps, levers. Trapped: hostages + levers.",
	DELVE_CHAT_TWILIGHT_CRYPTS_TRASH = "Mot'amra = big knockback on his path. Interrupt summoners. Watch trap tiles.",
	DELVE_CHAT_TWILIGHT_CRYPTS_BOSS = "Dodge {SPELL:@shade_cleave} (melee range stops {SPELL:@dark_pursuit}). Drag Darza out of {SPELL:@bask_in_the_twilight} (+30% dmg inside).",

	DELVE_CHAT_GULF_OF_MEMORY_OVERVIEW = "West Harandar. Munchies / Descent / Sporasaur. Bosses: Lumenia or Mul'tha'ul.",
	DELVE_CHAT_GULF_OF_MEMORY_ROUTE = "Munchies: Alnmoth Storm on the move. Descent: light candles, avoid dark. Sporasaur: kick Sporbits into shielded mobs.",
	DELVE_CHAT_GULF_OF_MEMORY_TRASH = "Stay lit in Descent. Kick Sporbits early. You can move while channeling storm.",
	DELVE_CHAT_GULF_OF_MEMORY_BOSS = "Lumenia: kill {SPELL:@radiant_command} add before it reaches you. Mul'tha'ul: dispel {SPELL:@hopeless_curse}, kite {SPELL:@tear_it_down}, respect {SPELL:@unanswered_call}.",

	DELVE_CHAT_GRUDGE_PIT_OVERVIEW = "SE Harandar arena delve. Champion / Rotstalk / Invasion / Pharmacon. Bosses: Brightthorn, Gyrospore, Mycomight or Replicating Venomborne.",
	DELVE_CHAT_GRUDGE_PIT_ROUTE = "Champion: wave arena (Sporbits help). Rotstalk: punt fans, taunt crowd. Invasion: free fighters, blow spawn points.",
	DELVE_CHAT_GRUDGE_PIT_TRASH = "Use Sporbits in arena. Clear invasion waves. Don't ignore Rotstalk fans.",
	-- Venomfall Deeps (Season 2 Nemesis). No TRASH line: nobody has written down what
	-- the trash here does, and a share that invents one is worse than a share missing a
	-- third. BuildDelvePartyShareLines skips absent sections since 19 aug.
	DELVE_CHAT_VENOMFALL_DEEPS_OVERVIEW = "Nemesis delve, north island of the Coiled Isle. Azta'rec. Bring 290 ilvl for ?, 309 for ??. Valeera on Healer. No coordinates work in here.",
	DELVE_CHAT_VENOMFALL_DEEPS_BOSS = "Fixed order: Noxious Bile, Void Toxin, Soul Extinction, Venom Storm - kick the third one, always. At 90/60/30% stand in the clear quarter and remember the ORDER; he repeats it unshown. On ?? kill the Echo. One hit = +500% nature.",
	DELVE_CHAT_GRUDGE_PIT_BOSS = "Brightthorn: dodge {SPELL:@solar_charge}, interrupt Bloom Thorn, turn from {SPELL:@blinding_burst}. Gyrospore: dodge {SPELL:@fungalstorm}, burst when dizzy. Mycomight: puddles away from fight.",

	DELVE_CHAT_SUNKILLER_SANCTUM_OVERVIEW = "East Voidstorm. Core / Not Expected / Gravity variants. Boss: Esuritus (or 3 Umbraroot, no boss).",
	DELVE_CHAT_SUNKILLER_SANCTUM_ROUTE = "Core: stop Domanaar stealing orbs (speed + DR buff). Not Expected: 3 Corrupted Umbraroot. Gravity: singularities drop shields.",
	DELVE_CHAT_SUNKILLER_SANCTUM_TRASH = "Pick up orbs in Core. Not What I Expected: pull the 3 Corrupted Umbraroot one at a time.",
	DELVE_CHAT_SUNKILLER_SANCTUM_BOSS = "All Voidcallers dead before {SPELL:@gorge} or +damage stacks. Kick {SPELL:@calling_bolt}. {SPELL:@coalescing_malediction} ends in a Voidcaller. Dodge {SPELL:@crushing_rift} (4 callers).",

	DELVE_CHAT_SHADOWGUARD_POINT_OVERVIEW = "West Voidstorm. Calamitous / Wildlife / Stolen Mana vs ethereals: boss Chief-Arcanist Patram. Basilisk Blitz: boss Disciple of Vashnik.",
	DELVE_CHAT_SHADOWGUARD_POINT_ROUTE = "Calamitous: overload stabilizers with Arcane Charges. Wildlife: free mobs carefully. Mana: Galvanic Blast containers until the Barrier drops. Basilisk Blitz: reconfigure generators, kill 4 Energized Basilisks.",
	DELVE_CHAT_SHADOWGUARD_POINT_TRASH = "Interrupt ethereals. Plan charge carries safely.",
	DELVE_CHAT_SHADOWGUARD_POINT_BOSS = "Kick {SPELL:@void_bolt_patram}. Kill Void Emissary before {SPELL:@submit_to_the_void} or Patram gets the buff. Dodge {SPELL:@discordant_hymn}.",

	DELVE_CHAT_TORMENTS_RISE_OVERVIEW = "Nemesis delve (Voidstorm). Tier ? / ?? rules. Boss Nullaeus — healer Valeera recommended on ??.",
	DELVE_CHAT_TORMENTS_RISE_ROUTE = "Dedicated portal (Shift-J / TomTom). Not a rotating world delve.",
	DELVE_CHAT_TORMENTS_RISE_TRASH = "Save CDs for Nullaeus — no Pactsworn trash inside.",
	DELVE_CHAT_TORMENTS_RISE_BOSS = "Kick every {SPELL:@devouring_essence}. {SPELL:@dread_portal}: AoE adds until dead. {SPELL:@oblivion_shell} = DPS check. Don't stack {SPELL:@umbral_rage}.",
})

merge(ns._mhLocales and ns._mhLocales.itIT, {
	DELVE_NAME_SHADOW_ENCLAVE = "The Shadow Enclave",
	DELVE_NAME_COLLEGIATE_CALAMITY = "Collegiate Calamity",
	DELVE_NAME_THE_DARKWAY = "The Darkway",
	DELVE_NAME_PARHELION_PLAZA = "Parhelion Plaza",
	DELVE_NAME_ATAL_AMAN = "Atal'Aman",
	DELVE_NAME_TWILIGHT_CRYPTS = "Twilight Crypts",
	DELVE_NAME_GULF_OF_MEMORY = "The Gulf of Memory",
	DELVE_NAME_GRUDGE_PIT = "The Grudge Pit",
	DELVE_NAME_SUNKILLER_SANCTUM = "Sunkiller Sanctum",
	DELVE_NAME_SHADOWGUARD_POINT = "Shadowguard Point",
	DELVE_NAME_TORMENTS_RISE = "Torment's Rise",

	-- The Shadow Enclave
	DELVE_TIP_SHADOW_ENCLAVE_OVERVIEW = "• Eversong Woods sud-ovest (Ruins of Deatholme).|n• Quattro varianti: Mirror Shine, Shadowy Supplies, Traitor's Due e Infiltrate and Ameliorate (nuova nella 12.1).|n• Traitor's Due: ferma i rituali, void orb, cultisti (leveling).|n• Mirror Shine, Shadowy Supplies e Traitor's Due finiscono con Lord Antenorian. Infiltrate and Ameliorate finisce con Abominable Blunder.",
	DELVE_TIP_SHADOW_ENCLAVE_ROUTE = "• Mirror Shine: porta gli specchi attraverso le sale buie; colpisci gli Shadow Nexus per diffondere la luce (evita i grue).|n• Shadowy Supplies: saccheggia gli oggetti di valore di Twilight's Blade dai mob o da terra.|n• Traitor's Due: insegui Antenorian attraverso il delve fino alla sala del boss.|n• Infiltrate and Ameliorate: parla con Scout Lok'aemon, poi spingi a calci 5 Ula'tek Summoners nell'abisso.|n• Infiltrate and Ameliorate: sabota 4 calderoni aggiungendo ingredienti strani. Alcuni ingredienti stanno in alto: usa i funghi che fanno saltare.|n• Infiltrate and Ameliorate: poi uccidi l'Ula'tek Supreme Summoner e guarda l'evocazione. Dopo arriva Abominable Blunder, il boss finale.|n• Infiltrate and Ameliorate: raccogli {SPELL:@fungal_pharmacon} e lancialo sulle pozze di veleno per ripulirle. Colpisce anche i nemici vicino al punto d'impatto.",
	DELVE_TIP_SHADOW_ENCLAVE_TRASH = "• Nella luce dello specchio, tu e i nemici siete Dazzled (maggiore probabilità di crit).|n• Interrompi i caster shadow.|n• Elimina Twilight's Blade durante Supplies.|n• Non ammassarti su terreno pericoloso; pulla con cura nei corridoi stretti.",
	DELVE_TIP_SHADOW_ENCLAVE_BOSS = "• Lord Antenorian: interrompi {SPELL:@shadow_bolt} ogni volta che puoi.|n• Lord Antenorian: i suoi teletrasporti lasciano una pozza dannosa. Tienilo vicino al centro.|n• Lord Antenorian: {SPELL:@shadowveil_annihilation} è un channel letale. Distruggi i 3 Shadow Orb: solo l'orb senza scudo subisce danni, e ogni kill toglie lo scudo al successivo.|n• Lord Antenorian: uccisi tutti gli orb, il suo scudo si rompe, il channel si ferma e per qualche secondo subisce danni extra.|n• Lord Antenorian: conserva il burst per gli orb. Valeera aiuta a romperli.|n• Abominable Blunder (Infiltrate and Ameliorate): Corrosive Bile è il suo attacco base di veleno. Reggilo con le cure.|n• Abominable Blunder (Infiltrate and Ameliorate): {SPELL:@searing_spew} danneggia e rallenta chiunque entro 14 yard da lui. Allontanati quando lo lancia.|n• Abominable Blunder (Infiltrate and Ameliorate): Acid Spray manda ondate di acido per qualche secondo. Continua a scansarti finché non finisce.",

	-- Collegiate Calamity
	DELVE_TIP_COLLEGIATE_CALAMITY_OVERVIEW = "• Silvermoon / Eversong Woods nord-ovest (Thalassian University).|n• Academy Under Siege -> Voidscorned Vagrant.|n• Faculty of Fear -> Infiltrator Garand.|n• Invasive Glow -> Hydrangea.|n• Academic Antitoxin (sulla mappa: An Elementary Antidote): nessun boss finale. Al suo posto compare un tesoro.",
	DELVE_TIP_COLLEGIATE_CALAMITY_ROUTE = "• Under Siege: chiudi i void portal e uccidi i Devouring Host.|n• Faculty of Fear: Eye of Revelation — gli studenti sospetti brillano di giallo attraverso i muri.|n• Invasive Glow: il Deweeder uccide i piccoli Lightbloom e danneggia quelli grandi.|n• Elimina le zone di Luminibulb sul livello principale.|n• Academic Antitoxin: parla con Sir Finley Mrrgglton, poi raccogli 10 Research Tomes.|n• Academic Antitoxin: poi raccogli gli ingredienti e dai l'antidoto a 7 Envenomed Denizens. Le due cose contano nello stesso momento.|n• Academic Antitoxin: la barra degli ingredienti richiede 400. Gli ingredienti piccoli danno 2, i medi 20 e i grandi 35, quindi prendi quelli grandi.|n• Academic Antitoxin: {SPELL:@fungal_pharmacon} ripulisce le pozze di veleno e colpisce anche i nemici entro 5 yard dal punto d'impatto.",
	DELVE_TIP_COLLEGIATE_CALAMITY_TRASH = "• Under Siege: dai priorità a chi chiude i portal.|n• Faculty: rivela gli studenti travestiti, poi uccidili prima che ti tendano l'imboscata.|n• Glow: usa il Deweeder mentre ti muovi.|n• Non saltare le zone di Luminibulb o la run va per le lunghe.",
	DELVE_TIP_COLLEGIATE_CALAMITY_BOSS = "• Hydrangea (Glow): uccidi le radici di {SPELL:@wildroot_weave} prima di {SPELL:@lightbloom_salvo}; schiva le zone di luce.|n• Garand (Faculty): schiva {SPELL:@shadow_laceration} o usa una difensiva; sparpagliatevi per i salti di {SPELL:@twilight_crash}.|n• Voidscorned Vagrant (Siege): scansa {SPELL:@void_eruption}; interrompi sempre {SPELL:@terrifying_power}.|n• Academic Antitoxin: non c'è un boss finale. Il tesoro compare quando hai finito l'ultimo passo.",

	-- The Darkway
	DELVE_TIP_THE_DARKWAY_OVERVIEW = "• Silvermoon / Eversong Woods nord (l'Arcway).|n• Focusers Under Pressure, Leyline Technician, Ogre Powered (7 Unstable Aberration).|n• Focusers, Leyline, Ogre Powered -> Infiltrator Gulkat.|n• Eggsplosive Growth (12.1) -> Replicating Venomborne.",
	DELVE_TIP_THE_DARKWAY_ROUTE = "• Focusers: trova i ley line focuser e riportali al centro del delve.|n• Leyline: attiva i conduit una volta per linea per potenziare tre focus crystal.|n• Ogre Powered: uccidi 7 Unstable Aberration nella sezione centrale prima di Gulkat.",
	DELVE_TIP_THE_DARKWAY_TRASH = "• Interrompi i Twilight Seeker e Arcane Deluge sulle aberration.|n• Variante Leyline: uccidi Twilight's Blade mentre instradi il potere.|n• Pulla via dagli angoli nei corridoi stretti dell'Arcway.",
	DELVE_TIP_THE_DARKWAY_BOSS = "• Interrompi i Twilight Seeker.|n• Schiva {SPELL:@abyssal_burst} (cono frontale).|n• {SPELL:@illusory_deceit}: illusioni esplosive — mantieni la distanza mentre gestisci Gulkat.|n• Replicating Venomborne: uccidi subito i Lesser Venomborne di {SPELL:@serpentogenesis} — se sono vivi al suo cast successivo, lo curano; esci dalle pozze di {SPELL:@venom_splash_venomborne} (danni + rallentamento); {SPELL:@hydra_strike} lascia un DoT che si accumula.",

	-- Parhelion Plaza
	DELVE_TIP_PARHELION_PLAZA_OVERVIEW = "• Isle of Quel'Danas ovest (zona Sunwell).|n• Si sblocca con March on Quel'Danas (fine marzo 2026).|n• Bombing Run, Holding the Line e March of the Arcane Brigade finiscono con Gladius Slaurna.|n• Uno dei delve di Midnight più difficili.|n• Caustic Crush (nuova nella 12.1): gli Slime Shamen of Ula'tek evocano slime e mandano ondate di veleno. L'ultimo obiettivo è un Ritual Pillar, non Gladius Slaurna.",
	DELVE_TIP_PARHELION_PLAZA_ROUTE = "• Bombing Run: Improvised Arcane Device per i void portal (limite di trasporto 40s; lo lasci cadere in combat).|n• Holding the Line: armi di Tempest Keep + ricostruisci le barricate.|n• March of the Arcane Brigade: sveglia le macchine Sentinel; camminano verso i void pylon. Distruggi 3 pylon e uccidi il Devouring Host per riempire la barra.|n• Caustic Crush: parla con Vindicator Xayann. Poi uccidi gli slime, 4 Shaman Slimecallers e 6 Ula'tek Wavecallers.|n• Caustic Crush: raccogli {SPELL:@fungal_pharmacon} lungo la strada. Lancialo sulle Ula'tek Poison Pools per ripulirle. Colpisce anche i nemici vicino al punto d'impatto.|n• Caustic Crush: gli obiettivi ti chiedono anche di usare una tana. L'ultimissimo obiettivo è distruggere il Ritual Pillar.",
	DELVE_TIP_PARHELION_PLAZA_TRASH = "• Bombing Run: non lasciare mai un portal prima di averlo fatto saltare. Si chiude per sempre e non puoi finire la run.|n• Elimina le ondate di Devouring Host prima di Slaurna.|n• Caustic Crush: schiva ogni ondata di veleno. Un colpo ti stordisce e fa pesanti danni nature.",
	DELVE_TIP_PARHELION_PLAZA_BOSS = "• Gladius Slaurna: uccidi in fretta i suoi tre Sacrificial Voidcaller e interrompi il loro Void Bolt.|n• Gladius Slaurna: ogni Voidcaller ancora vivo quando finisce {SPELL:@devouring_nova} lo fa colpire più forte e subire meno danni. Ai tier alti può costarti un wipe.|n• Gladius Slaurna: esci dalla linea di {SPELL:@voidscar_raze}. Spesso punta Valeera, quindi non metterti tra loro due.|n• Gladius Slaurna: combatti vicino al centro, così {SPELL:@devouring_nova} non può spingerti giù dalla piattaforma.",

	-- Atal'Aman
	DELVE_TIP_ATAL_AMAN_OVERVIEW = "• Zul'Aman ovest (confine con Eversong).|n• Ritual Interrupted, Toadly Unbecoming, Totem Annihilation.|n• Ritual Interrupted, Toadly Unbecoming e Totem Annihilation finiscono con Spiritflayer Jin'Ma.|n• Season 2, Venomous Vapors: boss finale Disciple of Vashnik (anche a Shadowguard Point).",
	DELVE_TIP_ATAL_AMAN_ROUTE = "• Ritual: salva i furbolg Spiritpaw rapiti per tutto il delve.|n• Toadly: dissolvi gli Amani stregati con il Vilebranch Hex Stick mentre uccidi gli invasori.|n• Totem: distruggi i totem maledetti per liberare Akil'zon; usa le aquile per approcci alternativi.|n• Venomous Vapors: apri i 2 forzieri nella prima stanza e raccogli gli attrezzi di Marla: {SPELL:@venomous_fireball}, da lanciare in una Toxic Cloud per farla esplodere (stai lontano), e un attrezzo che ti fa saltare altissimo. Sconfiggi le 5 Venom Vipers; il Disciple of Vashnik ti aspetta alla fine.",
	DELVE_TIP_ATAL_AMAN_TRASH = "• Interrompi i cast dei Vilebranch.|n• Variante Totem: dai priorità ai totem sul percorso.|n• Allontana le bestie dagli NPC stregati che stai cercando di salvare.|n• Venomous Vapors: le Venom Vipers fanno parte dell'obiettivo, quindi uccidile tutte e 5.",
	DELVE_TIP_ATAL_AMAN_BOSS = "• {SPELL:@flaying_knife} divide gli spiriti — ogni spirito raccolto dà +10% danni (raccoglili di proposito).|n• Schiva {SPELL:@raging_spirits} a terra.|n• Prima che {SPELL:@claim_spirits} finisca, raccogli i tuoi spiriti o Jin'Ma ne ottiene il buff.|n• Disciple of Vashnik: interrompi sempre {SPELL:@malignance}, una raffica di 4 secondi di globi di veleno che accumulano danni e ti rallentano. Valeera non lo interrompe ogni volta, quindi pensaci tu.|n• Disciple of Vashnik: {SPELL:@toxic_froth} fa pesanti danni da veleno per 8 secondi, e nascondersi dietro un muro non serve più. Rimuovi il veleno se la tua classe può, usa un difensivo o imposta Valeera come healer; poi raccogli le sfere di cura.|n• Disciple of Vashnik: {SPELL:@living_venom} ti respinge ed evoca uno slime. Esci dall'area intorno a lui e uccidi lo slime prima che ti raggiunga. Al Tier 11 molti giocatori lo considerano il boss più difficile di questa stagione: scendi di un tier se continui a morire.",

	-- Twilight Crypts
	DELVE_TIP_TWILIGHT_CRYPTS_OVERVIEW = "• Zul'Aman sud-ovest (Broken Throne).|n• Loosed Loa (evita Mot'amra), Party Crasher, Trapped!, e nuova nella 12.1: Why'd it have to be snakes?|n• Loosed Loa, Party Crasher e Trapped! finiscono con Blademaster Darza. Why'd it have to be snakes? finisce con Replicating Venomborne.",
	DELVE_TIP_TWILIGHT_CRYPTS_ROUTE = "• Loosed Loa: Evasive Elixir per esplorare; uccidi gli Skeleton Charmer e i totem — segui Mot'amra, non attraversare il suo cammino.|n• Loosed Loa: dall'hotfix del 10 settembre in questa variante compaiono le Explorer's League Supplies e un'Abandoned Restoration Stone.|n• Party Crasher: uccidi i 4 Twilight Summoners (li vedi sulla mappa) e aziona 7 Suspicious Levers. Le tagliole ti stordiscono per circa 2 secondi.|n• Trapped: salva gli ostaggi e trova le leve nel labirinto.|n• Why'd it have to be snakes?: aiuta Harrison Jones a trovare le reliquie perdute nelle cripte.|n• Why'd it have to be snakes?: calpestare i serpenti fa parte dell'obiettivo, ma esplodono quando li calpesti.|n• Why'd it have to be snakes?: raccogli {SPELL:@fungal_pharmacon} e lancialo sulle chiazze di veleno per ripulirle.",
	DELVE_TIP_TWILIGHT_CRYPTS_TRASH = "• Mot'amra colpisce duro con knockback se gli vai addosso.|n• Party Crasher: attento alle caselle trappola.|n• Interrompi gli evocatori di Twilight's Blade.",
	DELVE_TIP_TWILIGHT_CRYPTS_BOSS = "• Blademaster Darza: scansa {SPELL:@shade_cleave}. Combattere vicino impedisce il suo gap-closer {SPELL:@dark_pursuit}.|n• Blademaster Darza: {SPELL:@bask_in_the_twilight} lascia una void zone a terra.|n• Trascina Darza fuori da essa o ottiene +30% danni finché ci sta dentro.|n• Replicating Venomborne (Why'd it have to be snakes?): uccidi subito i Lesser Venomborne di {SPELL:@serpentogenesis}. Se sono ancora vivi al suo cast successivo, lo curano.|n• Replicating Venomborne (Why'd it have to be snakes?): esci dalle pozze di {SPELL:@venom_splash_venomborne}. Fanno danni e ti rallentano.|n• Replicating Venomborne (Why'd it have to be snakes?): {SPELL:@hydra_strike} ti lascia danni da veleno che si accumulano. Tieni d'occhio gli stack e reggili con le cure.",

	-- The Gulf of Memory
	DELVE_TIP_GULF_OF_MEMORY_OVERVIEW = "• Harandar ovest (Den of Echoes / Har'alnor).|n• Tre varianti.|n• Boss: Lumenia (Munchies / Sporasaur) e Mul'tha'ul (Descent of the Haranir).",
	DELVE_TIP_GULF_OF_MEMORY_ROUTE = "• Alnmoth Munchies: extra-action Alnmoth Storm mentre ti muovi — divora i cespugli o aiuta contro i Rutaani.|n• Descent: accendi le candele giganti; più danni subiti nelle zone buie.|n• Sporasaur: calcia gli Sporbit con il reticolo verde dentro gli Sporasaur per togliere il loro scudo.",
	DELVE_TIP_GULF_OF_MEMORY_TRASH = "• Resta nelle zone illuminate durante Descent.|n• Calcia gli Sporbit prima che esplodano.|n• Usa Alnmoth Storm mentre ti muovi — puoi muoverti e castare.",
	DELVE_TIP_GULF_OF_MEMORY_BOSS = "• Lumenia: uccidi l'add di {SPELL:@radiant_command} prima che ti raggiunga (esplode).|n• Schiva le zone di {SPELL:@searing_light} a meno di non usarle sull'add.|n• Mul'tha'ul: interrompi o dissolvi {SPELL:@hopeless_curse}.|n• Kita via dai tentacoli di {SPELL:@tear_it_down}.|n• Mantieni la distanza durante {SPELL:@unanswered_call} (danni alti, camminata lenta).",

	-- The Grudge Pit
	DELVE_TIP_GRUDGE_PIT_OVERVIEW = "• Harandar sud-est.|n• Lightbloom Invasion -> Brightthorn.|n• Arena Champion -> Gyrospore.|n• Dastardly Rotstalk -> Mycomight.|n• Fungal Pharmacon -> Replicating Venomborne.",
	DELVE_TIP_GRUDGE_PIT_ROUTE = "• Arena Champion: batti i combattenti, uccidi Bogdamp, Moldrus e 5 Spewing Deathcaps, raccogli 6 Mold Samples e pianta il tuo stendardo. Poi arriva Gyrospore.|n• Dastardly Rotstalk: ruolo da cattivo — calcia i fan, provoca la folla (puoi muoverti mentre provochi).|n• Lightbloom Invasion: ondate, libera i combattenti per far saltare gli spawn point, costruisci le difese.",
	DELVE_TIP_GRUDGE_PIT_TRASH = "• Arena Champion: usa gli Sporbit amici. Fanno danni bonus ai combattenti dell'arena.|n• Lightbloom Invasion: elimina le ondate prima del boss.|n• Rotstalk: tieni la folla sotto controllo — i fan fanno male se ignorati.",
	DELVE_TIP_GRUDGE_PIT_BOSS = "• Brightthorn: scansa {SPELL:@solar_charge} (lascia zone di Overbloom); interrompi {SPELL:@bloom_thorn}; girati prima di {SPELL:@blinding_burst}.|n• Gyrospore: schiva le zone di {SPELL:@fungalstorm}, poi burst durante i 10s di stordimento; arretra da {SPELL:@fungsplosion}; scansa {SPELL:@fungal_charge}.|n• Mycomight: lascia cadere le pozze di {SPELL:@rancid_rain} lontano dall'area di combattimento; schiva le onde d'urto di {SPELL:@fungis_fist}; scansa {SPELL:@fling_chair}.|n• Replicating Venomborne: uccidi subito i Lesser Venomborne di {SPELL:@serpentogenesis} — se sono vivi al suo cast successivo, lo curano; esci dalle pozze di {SPELL:@venom_splash_venomborne} (danni + rallentamento); {SPELL:@hydra_strike} lascia un DoT che si accumula.|n• Gyrospore: DBM e la tua cronologia dei delve chiamano questo scontro Spinshroom, un nome che Blizzard ha riusato da un vecchio boss. È lo stesso scontro.",

	-- Sunkiller Sanctum
	DELVE_TIP_SUNKILLER_SANCTUM_OVERVIEW = "• Voidstorm est (ingresso Voidspire).|n• Core of the Problem e The Gravitational Effect finiscono con Esuritus. Not What I Expected non ha boss.|n• Not What I Expected: nessun boss — finisce dopo 3 kill di Corrupted Umbraroot.",
	DELVE_TIP_SUNKILLER_SANCTUM_ROUTE = "• Core of the Problem: portal + impedisci ai Domanaar di rubare gli Energized Orb (buff dell'orb: velocità + riduzione danni).|n• Not What I Expected: clicca 7 Lightbloom Crates, usa il Sanctum Security Panel e riempi la barra delle uccisioni (contano sia i nemici Lightbloom sia quelli Void). Poi uccidi 3 Corrupted Umbraroot.|n• Gravitational Effect: usa le micro-singolarità per muoverti e disattivare gli scudi del boss.|n• Not What I Expected: attraversa un Displacement Portal. Poi una tua copia combatte al tuo fianco per circa 5 minuti.",
	DELVE_TIP_SUNKILLER_SANCTUM_TRASH = "• Raccogli gli orb nella variante Core per la sopravvivenza.|n• Not What I Expected: i 3 Corrupted Umbraroot sono elite. Pullali uno alla volta.|n• Not What I Expected: interrompi il Lightbloom Beam dei Corrupted Umbraroot, e scansa Blooming Bile (un frontale che genera add) e Rotting Charge (lascia una pozza).",
	DELVE_TIP_SUNKILLER_SANCTUM_BOSS = "• Uccidi tutti i Voidcaller prima di {SPELL:@gorge} o ottiene +danni per 30s per ogni divorata.|n• Interrompi {SPELL:@calling_bolt}.|n• Quando {SPELL:@coalescing_malediction} finisce o viene dissolto, compare un Voidcaller. Dissolvilo solo quando sei pronto a uccidere quell'add.|n• Schiva {SPELL:@crushing_rift} (genera 4 Voidcaller).",

	-- Shadowguard Point
	DELVE_TIP_SHADOWGUARD_POINT_OVERVIEW = "• Voidstorm ovest (a nord di Abundant Voidburrow).|n• Quattro varianti. In tre combatti contro gli Shadowguard Ethereal; in Basilisk Blitz li aiuti a riprendersi il punto.|n• Boss finale in tre varianti: Chief-Arcanist Patram. Basilisk Blitz invece finisce con il Disciple of Vashnik.|n• Season 2, Basilisk Blitz: boss finale Disciple of Vashnik (anche ad Atal'Aman).",
	DELVE_TIP_SHADOWGUARD_POINT_ROUTE = "• Calamitous: sovraccarica i Void Stabilizer con gli Arcane Charge (buff velocità; le esplosioni uccidono i mob — non restarci dentro).|n• Captured Wildlife: libera le void creature (la loro AoE può comunque colpirti).|n• Stolen Mana: prendi il fucile e usa Galvanic Blast sui contenitori di mana finché l'Arcane Barrier non cade.|n• Basilisk Blitz: all'inizio parla con l'ethereal ferito. Poi riconfigura l'Energy Distributor e uccidi l'Ula'tek Basilisk.|n• Basilisk Blitz: usa il Waygate per proseguire. Poi riconfigura i 4 Power Generators e uccidi i 4 Energized Basilisks.|n• Basilisk Blitz: il Disciple of Vashnik diventa il tuo obiettivo solo dopo che tutti e 4 gli Energized Basilisks sono morti.",
	DELVE_TIP_SHADOWGUARD_POINT_TRASH = "• Calamitous: pianifica i sovraccarichi in sicurezza mentre porti gli Arcane Charge.|n• Pack di ethereal: interrompi i cast.|n• Variante Wildlife: dai spazio alle creature liberate.|n• Basilisk Blitz: finché la barriera di un basilisco regge, ti lancia dardi di veleno. Entrare nella barriera ti stordisce per qualche secondo.",
	DELVE_TIP_SHADOWGUARD_POINT_BOSS = "• Interrompi {SPELL:@void_bolt_patram}.|n• Uccidi il Void Emissary prima che {SPELL:@submit_to_the_void} finisca (ottieni Vers + CDR; se fallisci il buff va a Patram).|n• Scansa le void zone di {SPELL:@discordant_hymn} (slow + danni).|n• Disciple of Vashnik: interrompi sempre {SPELL:@malignance}, una raffica di 4 secondi di globi di veleno che accumulano danni e ti rallentano. Valeera non lo interrompe ogni volta, quindi pensaci tu.|n• Disciple of Vashnik: {SPELL:@toxic_froth} fa pesanti danni da veleno per 8 secondi, e nascondersi dietro un muro non serve più. Rimuovi il veleno se la tua classe può, usa un difensivo o imposta Valeera come healer; poi raccogli le sfere di cura.|n• Disciple of Vashnik: {SPELL:@living_venom} ti respinge ed evoca uno slime. Esci dall'area intorno a lui e uccidi lo slime prima che ti raggiunga. Al Tier 11 molti giocatori lo considerano il boss più difficile di questa stagione: scendi di un tier se continui a morire.",

	-- Torment's Rise (Nemesis)
	DELVE_TIP_TORMENTS_RISE_OVERVIEW = "• Voidstorm — Nemesis Delve della Season 1 (capstone).|n• Tier ? dopo un qualsiasi T7 con 1+ vita; Tier ?? dopo un qualsiasi T10 con 1+ vita.|n• Boss: Nullaeus.|n• Valeera healer fortemente consigliata al Tier ??.",
	DELVE_TIP_TORMENTS_RISE_ROUTE = "• Portale dell'istanza dedicato (non un world delve a rotazione).|n• Usa l'Adventure Guide (Shift-J) o TomTom.|n• Weekly bounty: Beacon of Hope può portare Nullaeus al 50% in un delve normale.",
	DELVE_TIP_TORMENTS_RISE_TRASH = "• I mob Pactsworn vivono nei delve normali, non dentro Torment's Rise.|n• Dosa i cooldown — conserva difensive e interrupt per Nullaeus.",
	DELVE_TIP_TORMENTS_RISE_BOSS = "• Interrompi {SPELL:@devouring_essence} ogni cast (DoT + alimenta gli stack di {SPELL:@umbral_rage}).|n• {SPELL:@dread_portal}: 100% riduzione danni finché tutti gli add non muoiono — burst AoE pieno allo spawn.|n• La fase {SPELL:@oblivion_shell} è un DPS check.|n• {SPELL:@umbral_rage}: +10% danni per stack se add o DoT persistono — uccidi gli add in fretta.",

	-- Party chat
	DELVE_CHAT_SHADOW_ENCLAVE_OVERVIEW = "Eversong SO (Deatholme). Specchi, supplies, traitor: boss Lord Antenorian. Infiltrate and Ameliorate: boss Abominable Blunder.",
	DELVE_CHAT_SHADOW_ENCLAVE_ROUTE = "Specchi: colpisci gli Shadow Nexus per la luce. Supplies: saccheggia gli oggetti Twilight. Traitor: ferma i rituali, insegui fino al boss.",
	DELVE_CHAT_SHADOW_ENCLAVE_TRASH = "Luce dello specchio = Dazzled (più crit). Interrompi i caster shadow. Non ammassarti su terreno pericoloso.",
	DELVE_CHAT_SHADOW_ENCLAVE_BOSS = "Kicka {SPELL:@shadow_bolt}. Il teletrasporto lascia una pozza — tienilo centrale. {SPELL:@shadowveil_annihilation}: uccidi 3 Orb (solo quello senza scudo). Burst sugli orb.",

	DELVE_CHAT_COLLEGIATE_CALAMITY_OVERVIEW = "Silvermoon / Eversong NO (università). Siege, Faculty e Glow finiscono ognuna con un boss. Academic Antitoxin non ha boss, solo un forziere.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_ROUTE = "Siege: chiudi i void portal. Faculty: Eye of Revelation, studenti gialli attraverso i muri. Glow: Deweeder + Luminibulb. Antitoxin: 10 tomi, ingredienti, cura 7.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_TRASH = "Siege: prima i portal. Faculty: rivela poi uccidi gli studenti. Glow: usa il Deweeder mentre ti muovi.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_BOSS = "Hydrangea: uccidi {SPELL:@wildroot_weave} prima di {SPELL:@lightbloom_salvo}. Garand: schiva {SPELL:@shadow_laceration}, sparpagliati per {SPELL:@twilight_crash}. Vagrant: kicka {SPELL:@terrifying_power}.",

	DELVE_CHAT_THE_DARKWAY_OVERVIEW = "Arcway di Silvermoon nord. Focusers, Leyline o 7 Aberration: boss Infiltrator Gulkat. Eggsplosive Growth: boss Replicating Venomborne.",
	DELVE_CHAT_THE_DARKWAY_ROUTE = "Focusers: riporta i ley focuser al centro. Leyline: attiva i conduit per 3 crystal. Ogre: uccidi 7 Unstable Aberration al centro.",
	DELVE_CHAT_THE_DARKWAY_TRASH = "Interrompi i Twilight Seeker e Arcane Deluge. Pulla via dagli angoli stretti.",
	DELVE_CHAT_THE_DARKWAY_BOSS = "Kicka i Seeker. Schiva {SPELL:@abyssal_burst}. {SPELL:@illusory_deceit}: stai lontano dalle illusioni esplosive.",

	DELVE_CHAT_PARHELION_PLAZA_OVERVIEW = "Isle of Quel'Danas ovest (Sunwell), un delve più difficile. Bombing Run / Holding the Line / Brigade: boss Gladius Slaurna. Caustic Crush: distruggi il Ritual Pillar.",
	DELVE_CHAT_PARHELION_PLAZA_ROUTE = "Bombing Run: arcane device per i portal (trasporto 40s). Holding the Line: armi + barricate. Brigade: sentinel contro i pylon. Caustic Crush: uccidi Slimecaller e Wavecaller.",
	DELVE_CHAT_PARHELION_PLAZA_TRASH = "Kicka il Void Bolt del Voidcaller. Elimina le ondate di Devouring Host prima del boss.",
	DELVE_CHAT_PARHELION_PLAZA_BOSS = "Uccidi 3 Voidcaller in fretta (kicka Void Bolt). Se uno sopravvive a {SPELL:@devouring_nova}, Slaurna si potenzia tanto. Schiva {SPELL:@voidscar_raze}, combatti al centro.",

	DELVE_CHAT_ATAL_AMAN_OVERVIEW = "Zul'Aman ovest. Ritual / Toadly / Totem: boss Spiritflayer Jin'Ma. Venomous Vapors: boss Disciple of Vashnik.",
	DELVE_CHAT_ATAL_AMAN_ROUTE = "Ritual: salva i furbolg. Toadly: Hex Stick sugli Amani stregati. Totem: distruggi i totem, libera Akil'zon.",
	DELVE_CHAT_ATAL_AMAN_TRASH = "Interrompi i Vilebranch. Run Totem: prima i totem sul percorso.",
	DELVE_CHAT_ATAL_AMAN_BOSS = "Spiriti di {SPELL:@flaying_knife} = +10% danni ognuno — raccogli i tuoi. Schiva {SPELL:@raging_spirits}. Prima di {SPELL:@claim_spirits}, raccogli gli spiriti o Jin'Ma si buffa.",

	DELVE_CHAT_TWILIGHT_CRYPTS_OVERVIEW = "Zul'Aman SO (Broken Throne). Loa / Party Crasher / Trapped: boss Blademaster Darza. Why'd it have to be snakes?: boss Replicating Venomborne.",
	DELVE_CHAT_TWILIGHT_CRYPTS_ROUTE = "Loa: non attraversare il cammino di Mot'amra. Party Crasher: scorta, trappole, leve. Trapped: ostaggi + leve.",
	DELVE_CHAT_TWILIGHT_CRYPTS_TRASH = "Mot'amra = grosso knockback sul suo cammino. Interrompi gli evocatori. Attento alle caselle trappola.",
	DELVE_CHAT_TWILIGHT_CRYPTS_BOSS = "Schiva {SPELL:@shade_cleave} (in mischia blocca {SPELL:@dark_pursuit}). Trascina Darza fuori da {SPELL:@bask_in_the_twilight} (+30% danni dentro).",

	DELVE_CHAT_GULF_OF_MEMORY_OVERVIEW = "Harandar ovest. Munchies / Descent / Sporasaur. Boss: Lumenia o Mul'tha'ul.",
	DELVE_CHAT_GULF_OF_MEMORY_ROUTE = "Munchies: Alnmoth Storm in movimento. Descent: accendi le candele, evita il buio. Sporasaur: calcia gli Sporbit nei mob con scudo.",
	DELVE_CHAT_GULF_OF_MEMORY_TRASH = "Resta illuminato in Descent. Calcia presto gli Sporbit. Puoi muoverti mentre usi lo storm.",
	DELVE_CHAT_GULF_OF_MEMORY_BOSS = "Lumenia: uccidi l'add di {SPELL:@radiant_command} prima che ti raggiunga. Mul'tha'ul: dissolvi {SPELL:@hopeless_curse}, kita {SPELL:@tear_it_down}, rispetta {SPELL:@unanswered_call}.",

	DELVE_CHAT_GRUDGE_PIT_OVERVIEW = "Delve ad arena Harandar SE. Champion / Rotstalk / Invasion / Pharmacon. Boss: Brightthorn, Gyrospore, Mycomight o Replicating Venomborne.",
	DELVE_CHAT_GRUDGE_PIT_ROUTE = "Champion: arena a ondate (gli Sporbit aiutano). Rotstalk: calcia i fan, provoca la folla. Invasion: libera i combattenti, fai saltare gli spawn point.",
	DELVE_CHAT_GRUDGE_PIT_TRASH = "Usa gli Sporbit nell'arena. Elimina le ondate dell'invasion. Non ignorare i fan di Rotstalk.",
	DELVE_CHAT_GRUDGE_PIT_BOSS = "Brightthorn: schiva {SPELL:@solar_charge}, interrompi Bloom Thorn, girati da {SPELL:@blinding_burst}. Gyrospore: schiva {SPELL:@fungalstorm}, burst quando è stordito. Mycomight: pozze lontano dal combat.",

	DELVE_CHAT_SUNKILLER_SANCTUM_OVERVIEW = "Voidstorm est. Varianti Core / Not Expected / Gravity. Boss: Esuritus (o 3 Umbraroot, nessun boss).",
	DELVE_CHAT_SUNKILLER_SANCTUM_ROUTE = "Core: impedisci ai Domanaar di rubare gli orb (velocità + buff DR). Not Expected: 3 Corrupted Umbraroot. Gravity: le singolarità abbattono gli scudi.",
	DELVE_CHAT_SUNKILLER_SANCTUM_TRASH = "Raccogli gli orb in Core. Not What I Expected: pulla i 3 Corrupted Umbraroot uno alla volta.",
	DELVE_CHAT_SUNKILLER_SANCTUM_BOSS = "Tutti i Voidcaller morti prima di {SPELL:@gorge} o accumula +danni. Kicka {SPELL:@calling_bolt}. {SPELL:@coalescing_malediction} finisce in un Voidcaller. Schiva {SPELL:@crushing_rift} (4 caller).",

	DELVE_CHAT_SHADOWGUARD_POINT_OVERVIEW = "Voidstorm ovest. Calamitous / Wildlife / Stolen Mana contro ethereal: boss Chief-Arcanist Patram. Basilisk Blitz: boss Disciple of Vashnik.",
	DELVE_CHAT_SHADOWGUARD_POINT_ROUTE = "Calamitous: sovraccarica gli stabilizer con Arcane Charge. Wildlife: libera i mob con cura. Mana: Galvanic Blast sui contenitori finché la Barrier non cade. Basilisk Blitz: riconfigura i generatori, uccidi 4 Energized Basilisks.",
	DELVE_CHAT_SHADOWGUARD_POINT_TRASH = "Interrompi gli ethereal. Pianifica il trasporto delle charge in sicurezza.",
	DELVE_CHAT_SHADOWGUARD_POINT_BOSS = "Kicka {SPELL:@void_bolt_patram}. Uccidi il Void Emissary prima di {SPELL:@submit_to_the_void} o il buff va a Patram. Schiva {SPELL:@discordant_hymn}.",

	DELVE_CHAT_TORMENTS_RISE_OVERVIEW = "Nemesis delve (Voidstorm). Regole Tier ? / ??. Boss Nullaeus — Valeera healer consigliata al ??.",
	DELVE_CHAT_TORMENTS_RISE_ROUTE = "Portale dedicato (Shift-J / TomTom). Non è un world delve a rotazione.",
	DELVE_CHAT_TORMENTS_RISE_TRASH = "Conserva i CD per Nullaeus — niente trash Pactsworn dentro.",
	DELVE_CHAT_TORMENTS_RISE_BOSS = "Kicka ogni {SPELL:@devouring_essence}. {SPELL:@dread_portal}: AoE sugli add finché non muoiono. {SPELL:@oblivion_shell} = DPS check. Non accumulare {SPELL:@umbral_rage}.",
})

merge(ns._mhLocales and ns._mhLocales.nlNL, {
	DELVE_NAME_SHADOW_ENCLAVE = "The Shadow Enclave",
	DELVE_NAME_COLLEGIATE_CALAMITY = "Collegiate Calamity",
	DELVE_NAME_THE_DARKWAY = "The Darkway",
	DELVE_NAME_PARHELION_PLAZA = "Parhelion Plaza",
	DELVE_NAME_ATAL_AMAN = "Atal'Aman",
	DELVE_NAME_TWILIGHT_CRYPTS = "Twilight Crypts",
	DELVE_NAME_GULF_OF_MEMORY = "The Gulf of Memory",
	DELVE_NAME_GRUDGE_PIT = "The Grudge Pit",
	DELVE_NAME_SUNKILLER_SANCTUM = "Sunkiller Sanctum",
	DELVE_NAME_SHADOWGUARD_POINT = "Shadowguard Point",
	DELVE_NAME_TORMENTS_RISE = "Torment's Rise",

	-- The Shadow Enclave
	DELVE_TIP_SHADOW_ENCLAVE_OVERVIEW = "• Zuidwest Eversong Woods (bij Ruins of Deatholme).|n• Vier varianten: Mirror Shine, Shadowy Supplies, Traitor's Due en Infiltrate and Ameliorate (nieuw in 12.1).|n• Traitor's Due: stop rituals, void orbs en cultists (leveling).|n• Mirror Shine, Shadowy Supplies en Traitor's Due eindigen bij Lord Antenorian. Infiltrate and Ameliorate eindigt bij Abominable Blunder.",
	DELVE_TIP_SHADOW_ENCLAVE_ROUTE = "• Mirror Shine: draag spiegels door donkere gangen; raak Shadow Nexuses om licht te verspreiden (voorkomt grues).|n• Shadowy Supplies: pak buit van Twilight's Blade of van de grond.|n• Traitor's Due: achtervolg Antenorian door de delve tot de baaskamer.|n• Infiltrate and Ameliorate: praat met Scout Lok'aemon en schop daarna 5 Ula'tek Summoners de afgrond in.|n• Infiltrate and Ameliorate: saboteer 4 ketels door er vreemde ingrediënten in te doen. Sommige ingrediënten liggen hoog: gebruik de springpaddenstoelen.|n• Infiltrate and Ameliorate: kill daarna de Ula'tek Supreme Summoner en kijk naar het oproepen. Daarna komt Abominable Blunder, de eindbaas.|n• Infiltrate and Ameliorate: pak {SPELL:@fungal_pharmacon} op en gooi hem op de poison pools om ze schoon te maken. Hij raakt ook vijanden vlak bij waar hij landt.",
	DELVE_TIP_SHADOW_ENCLAVE_TRASH = "• In spiegellicht zijn jij en vijanden Dazzled (hogere kans op crits).|n• Onderbreek shadow-casters.|n• Ruim Twilight's Blade op tijdens Supplies.|n• Sta niet gestapeld op gevaarlijke grond; pull rustig in smalle gangen.",
	DELVE_TIP_SHADOW_ENCLAVE_BOSS = "• Lord Antenorian: onderbreek {SPELL:@shadow_bolt} zo vaak als je kunt.|n• Lord Antenorian: zijn teleports laten een plas achter die schade doet. Houd hem bij het midden.|n• Lord Antenorian: {SPELL:@shadowveil_annihilation} is een dodelijke channel. Vernietig de 3 Shadow Orbs: alleen de orb zonder schild krijgt schade, en elke kill haalt het volgende schild weg.|n• Lord Antenorian: zijn alle orbs dood, dan breekt zijn schild, stopt de channel en neemt hij een paar seconden extra schade.|n• Lord Antenorian: bewaar je burst voor de orbs. Valeera helpt ze te breken.|n• Abominable Blunder (Infiltrate and Ameliorate): Corrosive Bile is zijn gewone gifaanval. Heal er doorheen.|n• Abominable Blunder (Infiltrate and Ameliorate): {SPELL:@searing_spew} doet schade en vertraagt iedereen binnen 14 yards van hem. Loop weg als hij hem cast.|n• Abominable Blunder (Infiltrate and Ameliorate): Acid Spray stuurt een paar seconden lang golven zuur. Blijf opzij stappen tot het stopt.",

	-- Collegiate Calamity
	DELVE_TIP_COLLEGIATE_CALAMITY_OVERVIEW = "• Noordwest Silvermoon / Eversong Woods (Thalassian University).|n• Academy Under Siege -> Voidscorned Vagrant.|n• Faculty of Fear -> Infiltrator Garand.|n• Invasive Glow -> Hydrangea.|n• Academic Antitoxin (op de kaart: An Elementary Antidote): geen eindbaas. In plaats daarvan verschijnt er een treasure.",
	DELVE_TIP_COLLEGIATE_CALAMITY_ROUTE = "• Under Siege: sluit void-portals en kill Devouring Host.|n• Faculty of Fear: Eye of Revelation — verdachte studenten gloeien geel door muren.|n• Invasive Glow: Deweeder voor kleine Lightbloom, schade aan grote.|n• Verwijder Luminibulb-patches op het hoofdniveau.|n• Academic Antitoxin: praat met Sir Finley Mrrgglton en verzamel daarna 10 Research Tomes.|n• Academic Antitoxin: verzamel daarna ingrediënten en geef het tegengif aan 7 Envenomed Denizens. Beide tellen tegelijk.|n• Academic Antitoxin: de ingrediëntenbalk moet naar 400. Kleine ingrediënten geven 2, middelgrote 20 en grote 35, dus pak de grote.|n• Academic Antitoxin: {SPELL:@fungal_pharmacon} maakt de poison pools schoon en raakt ook vijanden binnen 5 yards van waar hij landt.",
	DELVE_TIP_COLLEGIATE_CALAMITY_TRASH = "• Under Siege: prioriteit op portals sluiten.|n• Faculty: eerst onthullen, dan studenten killen vóór de ambush.|n• Glow: Deweeder kan je tijdens lopen channelen.|n• Haal Luminibulb-patches niet over.",
	DELVE_TIP_COLLEGIATE_CALAMITY_BOSS = "• Hydrangea (Glow): kap {SPELL:@wildroot_weave}-roots vóór {SPELL:@lightbloom_salvo}; ontwijk lichtzones.|n• Garand (Faculty): ontwijk {SPELL:@shadow_laceration} of gebruik defensive; spreid voor {SPELL:@twilight_crash}.|n• Voidscorned Vagrant (Siege): ontwijk {SPELL:@void_eruption}; onderbreek {SPELL:@terrifying_power} altijd.|n• Academic Antitoxin: er is geen eindbaas. De treasure verschijnt als de laatste stap klaar is.",

	-- The Darkway
	DELVE_TIP_THE_DARKWAY_OVERVIEW = "• Noord Silvermoon / Eversong Woods (de Arcway).|n• Focusers Under Pressure, Leyline Technician, Ogre Powered (7 Unstable Aberrations).|n• Focusers, Leyline, Ogre Powered -> Infiltrator Gulkat.|n• Eggsplosive Growth (12.1) -> Replicating Venomborne.",
	DELVE_TIP_THE_DARKWAY_ROUTE = "• Focusers: zoek ley focusers en breng ze terug naar het centrum.|n• Leyline: tap conduits per lijn om drie focus crystals te laden.|n• Ogre Powered: kill 7 Unstable Aberrations in het midden vóór Gulkat.",
	DELVE_TIP_THE_DARKWAY_TRASH = "• Onderbreek Twilight Seekers en Arcane Deluge op aberrations.|n• Leyline: kill Twilight's Blade tijdens het routen.|n• Pull uit hoeken in smalle Arcway-gangen.",
	DELVE_TIP_THE_DARKWAY_BOSS = "• Onderbreek Twilight Seekers.|n• Ontwijk {SPELL:@abyssal_burst} (frontale cone).|n• {SPELL:@illusory_deceit}: illusies exploderen — houd afstand tijdens andere mechanics.|n• Replicating Venomborne: sla de Lesser Venomborne van {SPELL:@serpentogenesis} meteen dood — leven ze bij zijn volgende cast nog, dan healen ze hem; stap uit de plassen van {SPELL:@venom_splash_venomborne} (schade + vertraging); {SPELL:@hydra_strike} laat een stapelende DoT achter.",

	-- Parhelion Plaza
	DELVE_TIP_PARHELION_PLAZA_OVERVIEW = "• West Isle of Quel'Danas (Sunwell-gebied).|n• Ontgrendelt met March on Quel'Danas (eind maart 2026).|n• Bombing Run, Holding the Line en March of the Arcane Brigade eindigen bij Gladius Slaurna.|n• Een van de zwaardere Midnight-delves.|n• Caustic Crush (nieuw in 12.1): Slime Shamen of Ula'tek roepen slimes op en sturen golven gif. Het laatste doel is een Ritual Pillar, niet Gladius Slaurna.",
	DELVE_TIP_PARHELION_PLAZA_ROUTE = "• Bombing Run: Improvised Arcane Device voor void-portals (max. 40s dragen; laat vallen in combat).|n• Holding the Line: Tempest Keep-wapens + barricades herstellen.|n• March of the Arcane Brigade: maak de Sentinel-machines wakker; ze lopen naar de void-pylons. Vernietig 3 pylons en kill Devouring Host om de balk te vullen.|n• Caustic Crush: praat met Vindicator Xayann. Kill daarna de slimes, 4 Shaman Slimecallers en 6 Ula'tek Wavecallers.|n• Caustic Crush: pak onderweg {SPELL:@fungal_pharmacon} op. Gooi hem op de Ula'tek Poison Pools om ze schoon te maken. Hij raakt ook vijanden vlak bij waar hij landt.|n• Caustic Crush: de doelen vragen ook dat je een burrow gebruikt. Het allerlaatste doel is de Ritual Pillar vernietigen.",
	DELVE_TIP_PARHELION_PLAZA_TRASH = "• Bombing Run: verlaat nooit een portal voordat je hem opblaast. Hij sluit dan voorgoed en je kunt de run niet afmaken.|n• Clear Devouring Host vóór Slaurna.|n• Caustic Crush: ontwijk elke gifgolf. Een treffer stunt je en doet zware Nature-schade.",
	DELVE_TIP_PARHELION_PLAZA_BOSS = "• Gladius Slaurna: kill zijn drie Sacrificial Voidcallers snel en onderbreek hun Void Bolt.|n• Gladius Slaurna: elke Voidcaller die nog leeft als {SPELL:@devouring_nova} eindigt, laat hem harder slaan en minder schade nemen. Op hoge tiers kan dat een wipe betekenen.|n• Gladius Slaurna: stap uit de lijn van {SPELL:@voidscar_raze}. Hij mikt vaak op Valeera, dus ga niet tussen hen in staan.|n• Gladius Slaurna: vecht bij het midden, zodat {SPELL:@devouring_nova} je niet van het platform kan duwen.",

	-- Atal'Aman
	DELVE_TIP_ATAL_AMAN_OVERVIEW = "• West Zul'Aman (grens Eversong).|n• Ritual Interrupted, Toadly Unbecoming, Totem Annihilation.|n• Ritual Interrupted, Toadly Unbecoming en Totem Annihilation eindigen bij Spiritflayer Jin'Ma.|n• Seizoen 2, Venomous Vapors: eindbaas Disciple of Vashnik (ook in Shadowguard Point).",
	DELVE_TIP_ATAL_AMAN_ROUTE = "• Ritual: red ontvoerde Spiritpaw furbolgs.|n• Toadly: ontwerp hex met Vilebranch Hex Stick en kill invaders.|n• Totem: vernietig cursed totems; gebruik eagles voor andere routes.|n• Venomous Vapors: open de 2 kisten in de eerste kamer en pak Marla's gereedschap: {SPELL:@venomous_fireball}, die je in een Toxic Cloud gooit om hem op te blazen (blijf uit de buurt), en iets waarmee je heel hoog springt. Versla de 5 Venom Vipers; de Disciple of Vashnik wacht aan het eind.",
	DELVE_TIP_ATAL_AMAN_TRASH = "• Onderbreek Vilebranch-casts.|n• Totem-variant: totems op je pad eerst.|n• Beasts weg van NPCs die je redt.|n• Venomous Vapors: de Venom Vipers horen bij de opdracht, dus kill ze alle 5.",
	DELVE_TIP_ATAL_AMAN_BOSS = "• {SPELL:@flaying_knife} splitst spirits — elk opgepakt spirit geeft +10% damage.|n• Ontwijk {SPELL:@raging_spirits} op de grond.|n• Vóór {SPELL:@claim_spirits}: pak jouw spirits, anders bufft Jin'Ma.|n• Disciple of Vashnik: onderbreek {SPELL:@malignance} altijd, een volley van 4 seconden met gifbollen die damage stacken en je slowen. Valeera kickt hem niet elke keer, dus doe het zelf.|n• Disciple of Vashnik: {SPELL:@toxic_froth} doet 8 seconden lang zware poison damage, en achter een muur verstoppen helpt niet meer. Cleanse het gif als je class dat kan, gebruik een defensive of zet Valeera op healer; pak daarna de healing orbs.|n• Disciple of Vashnik: {SPELL:@living_venom} knockt je terug en roept een slime op. Ga uit het gebied rond hem en kill de slime voordat hij je bereikt. Op Tier 11 noemen veel spelers hem de zwaarste baas van dit seizoen: ga een tier omlaag als je blijft doodgaan.",

	-- Twilight Crypts
	DELVE_TIP_TWILIGHT_CRYPTS_OVERVIEW = "• Zuidwest Zul'Aman (Broken Throne).|n• Loosed Loa (ontwijk Mot'amra), Party Crasher, Trapped! en nieuw in 12.1: Why'd it have to be snakes?|n• Loosed Loa, Party Crasher en Trapped! eindigen bij Blademaster Darza. Why'd it have to be snakes? eindigt bij Replicating Venomborne.",
	DELVE_TIP_TWILIGHT_CRYPTS_ROUTE = "• Loosed Loa: Evasive Elixir om te verkennen; kill Skeleton Charmers en totems — volg Mot'amra, loop niet door zijn pad.|n• Loosed Loa: sinds de hotfix van 10 sep liggen in deze variant Explorer's League Supplies en een Abandoned Restoration Stone.|n• Party Crasher: kill de 4 Twilight Summoners (ze staan op je kaart) en trek aan 7 Suspicious Levers. Berenvallen stunnen je zo'n 2 seconden.|n• Trapped: red gijzelaars, levers door het doolhof.|n• Why'd it have to be snakes?: help Harrison Jones de verloren relics in de crypten te vinden.|n• Why'd it have to be snakes?: op de slangen stappen hoort bij de opdracht, maar ze ontploffen als je erop stapt.|n• Why'd it have to be snakes?: pak {SPELL:@fungal_pharmacon} op en gooi hem op gifplekken om ze schoon te maken.",
	DELVE_TIP_TWILIGHT_CRYPTS_TRASH = "• Mot'amra doet zware schade + knockback op zijn pad.|n• Party Crasher: let op vallen.|n• Onderbreek Twilight's Blade summoners.",
	DELVE_TIP_TWILIGHT_CRYPTS_BOSS = "• Blademaster Darza: stap opzij voor {SPELL:@shade_cleave}. Dichtbij vechten stopt haar gap-closer {SPELL:@dark_pursuit}.|n• Blademaster Darza: {SPELL:@bask_in_the_twilight} laat een void-zone op de vloer achter.|n• Trek Darza eruit of +30% damage zolang ze erin staat.|n• Replicating Venomborne (Why'd it have to be snakes?): kill de Lesser Venomborne van {SPELL:@serpentogenesis} meteen. Leven ze bij zijn volgende cast nog, dan healen ze hem.|n• Replicating Venomborne (Why'd it have to be snakes?): stap uit de plassen van {SPELL:@venom_splash_venomborne}. Ze doen schade en vertragen je.|n• Replicating Venomborne (Why'd it have to be snakes?): {SPELL:@hydra_strike} laat gifschade op je achter die stapelt. Let op de stacks en heal er doorheen.",

	-- The Gulf of Memory
	DELVE_TIP_GULF_OF_MEMORY_OVERVIEW = "• West Harandar (Den of Echoes / Har'alnor).|n• Drie varianten.|n• Bazen: Lumenia (Munchies / Sporasaur) en Mul'tha'ul (Descent of the Haranir).",
	DELVE_TIP_GULF_OF_MEMORY_ROUTE = "• Alnmoth Munchies: extra-action Alnmoth Storm tijdens lopen — bushes of Rutaani.|n• Descent: steek grote kaarsen aan; meer schade in donkere zones.|n• Sporasaur: schop Sporbits (groen reticle) tegen Sporasaurs om schild te breken.",
	DELVE_TIP_GULF_OF_MEMORY_TRASH = "• Blijf in verlichte zones tijdens Descent.|n• Schop Sporbits vóór ze exploderen.|n• Je kunt tijdens Alnmoth Storm bewegen en casten.",
	DELVE_TIP_GULF_OF_MEMORY_BOSS = "• Lumenia: kill {SPELL:@radiant_command}-add vóór hij je bereikt (explodeert).|n• Ontwijk {SPELL:@searing_light}, tenzij je de add daarmee killt.|n• Mul'tha'ul: onderbreek of dispel {SPELL:@hopeless_curse}.|n• Kit weg van {SPELL:@tear_it_down}-tentakels.|n• Afstand tijdens {SPELL:@unanswered_call}.",

	-- The Grudge Pit
	DELVE_TIP_GRUDGE_PIT_OVERVIEW = "• Zuidoost Harandar.|n• Lightbloom Invasion -> Brightthorn.|n• Arena Champion -> Gyrospore.|n• Dastardly Rotstalk -> Mycomight.|n• Fungal Pharmacon -> Replicating Venomborne.",
	DELVE_TIP_GRUDGE_PIT_ROUTE = "• Arena Champion: versla de fighters, kill Bogdamp, Moldrus en 5 Spewing Deathcaps, verzamel 6 Mold Samples en plant je banier. Dan komt Gyrospore.|n• Dastardly Rotstalk: heel-rol — schop fans, taunt crowd (bewegen tijdens taunt kan).|n• Lightbloom Invasion: golven, bevrijd fighters voor spawn-points, bouw verdediging.",
	DELVE_TIP_GRUDGE_PIT_TRASH = "• Arena Champion: gebruik de vriendelijke Sporbits. Ze doen extra schade aan de arena-fighters.|n• Lightbloom Invasion: clear de golven vóór de baas.|n• Rotstalk: crowd niet negeren.",
	DELVE_TIP_GRUDGE_PIT_BOSS = "• Brightthorn: ontwijk {SPELL:@solar_charge} (laat Overbloom-zones achter); onderbreek {SPELL:@bloom_thorn}; draai weg vóór {SPELL:@blinding_burst}.|n• Gyrospore: ontwijk {SPELL:@fungalstorm}, burst tijdens 10s dizzy; stap terug voor {SPELL:@fungsplosion}; ontwijk {SPELL:@fungal_charge}.|n• Mycomight: {SPELL:@rancid_rain} weg van fight-zone; ontwijk {SPELL:@fungis_fist}; ontwijk {SPELL:@fling_chair}.|n• Replicating Venomborne: sla de Lesser Venomborne van {SPELL:@serpentogenesis} meteen dood — leven ze bij zijn volgende cast nog, dan healen ze hem; stap uit de plassen van {SPELL:@venom_splash_venomborne} (schade + vertraging); {SPELL:@hydra_strike} laat een stapelende DoT achter.|n• Gyrospore: DBM en je delve-geschiedenis noemen dit gevecht Spinshroom, een naam die Blizzard van een oude baas hergebruikte. Het is hetzelfde gevecht.",

	-- Sunkiller Sanctum
	DELVE_TIP_SUNKILLER_SANCTUM_OVERVIEW = "• Oost Voidstorm (Voidspire-ingang).|n• Core of the Problem en The Gravitational Effect eindigen bij Esuritus. Not What I Expected heeft geen baas.|n• Not What I Expected: geen baas — eindigt na 3 Corrupted Umbraroot.",
	DELVE_TIP_SUNKILLER_SANCTUM_ROUTE = "• Core of the Problem: portals + stop Domanaar met Energized Orbs (buff: snelheid + minder schade).|n• Not What I Expected: klik 7 Lightbloom Crates, gebruik het Sanctum Security Panel en vul de kill-balk (Lightbloom- en Void-vijanden tellen allebei). Kill daarna 3 Corrupted Umbraroot.|n• Gravitational Effect: micro-singularities om schilden van de baas uit te schakelen.|n• Not What I Expected: loop door een Displacement Portal. Er vecht dan zo'n 5 minuten een kopie van jou naast je.",
	DELVE_TIP_SUNKILLER_SANCTUM_TRASH = "• Pak orbs in Core-variant voor overleving.|n• Not What I Expected: de 3 Corrupted Umbraroot zijn elites. Pull ze één voor één.|n• Not What I Expected: onderbreek de Lightbloom Beam van de Corrupted Umbraroot, en stap opzij voor Blooming Bile (een frontale die adds oproept) en Rotting Charge (die laat een plas achter).",
	DELVE_TIP_SUNKILLER_SANCTUM_BOSS = "• Kill alle Voidcallers vóór {SPELL:@gorge} of hij krijgt +damage per devour (30s).|n• Onderbreek {SPELL:@calling_bolt}.|n• Als {SPELL:@coalescing_malediction} afloopt of gedispeld wordt, verschijnt er een Voidcaller. Dispel hem pas als je klaar bent om die add te killen.|n• Ontwijk {SPELL:@crushing_rift} (spawnt 4 Voidcallers).",

	-- Shadowguard Point
	DELVE_TIP_SHADOWGUARD_POINT_OVERVIEW = "• West Voidstorm (noord van Abundant Voidburrow).|n• Vier varianten. In drie vecht je tegen de Shadowguard Ethereals; in Basilisk Blitz help je ze het punt terug te veroveren.|n• Eindbaas in drie varianten: Chief-Arcanist Patram. Basilisk Blitz eindigt in plaats daarvan bij de Disciple of Vashnik.|n• Seizoen 2, Basilisk Blitz: eindbaas Disciple of Vashnik (ook in Atal'Aman).",
	DELVE_TIP_SHADOWGUARD_POINT_ROUTE = "• Calamitous: overload Void Stabilizers met Arcane Charges (sneller lopen; explosies killen mobs — sta er niet in).|n• Captured Wildlife: bevrijd creatures (hun AoE kan jou raken).|n• Stolen Mana: pak het geweer en gebruik Galvanic Blast op de mana-containers tot de Arcane Barrier valt.|n• Basilisk Blitz: praat aan het begin met de gewonde ethereal. Stel daarna de Energy Distributor opnieuw in en kill de Ula'tek Basilisk.|n• Basilisk Blitz: gebruik de Waygate om verder te gaan. Stel daarna de 4 Power Generators opnieuw in en kill de 4 Energized Basilisks.|n• Basilisk Blitz: de Disciple of Vashnik wordt pas je doel als alle 4 Energized Basilisks dood zijn.",
	DELVE_TIP_SHADOWGUARD_POINT_TRASH = "• Calamitous: plan overloads veilig met Arcane Charges.|n• Onderbreek ethereals.|n• Wildlife: ruimte voor bevrijde creatures.|n• Basilisk Blitz: zolang de barrière van een basilisk staat, gooit hij gifschichten naar je. Loop je de barrière in, dan word je een paar seconden gestund.",
	DELVE_TIP_SHADOWGUARD_POINT_BOSS = "• Onderbreek {SPELL:@void_bolt_patram}.|n• Kill Void Emissary vóór {SPELL:@submit_to_the_void} (jij krijgt Vers + CDR; anders bufft Patram).|n• Ontwijk {SPELL:@discordant_hymn} (slow + schade).|n• Disciple of Vashnik: onderbreek {SPELL:@malignance} altijd, een volley van 4 seconden met gifbollen die damage stacken en je slowen. Valeera kickt hem niet elke keer, dus doe het zelf.|n• Disciple of Vashnik: {SPELL:@toxic_froth} doet 8 seconden lang zware poison damage, en achter een muur verstoppen helpt niet meer. Cleanse het gif als je class dat kan, gebruik een defensive of zet Valeera op healer; pak daarna de healing orbs.|n• Disciple of Vashnik: {SPELL:@living_venom} knockt je terug en roept een slime op. Ga uit het gebied rond hem en kill de slime voordat hij je bereikt. Op Tier 11 noemen veel spelers hem de zwaarste baas van dit seizoen: ga een tier omlaag als je blijft doodgaan.",

	-- Torment's Rise (Nemesis)
	DELVE_TIP_TORMENTS_RISE_OVERVIEW = "• Voidstorm — Nemesis Delve seizoen 1.|n• Tier ? na elke T7 met 1+ leven; Tier ?? na elke T10 met 1+ leven.|n• Baas: Nullaeus.|n• Healer-Valeera sterk aanbevolen op Tier ??.",
	DELVE_TIP_TORMENTS_RISE_ROUTE = "• Eigen instance-portal (geen roterende world-delve).|n• Adventure Guide (Shift-J) of TomTom.|n• Weekly bounty: Beacon of Hope kan Nullaeus op 50% in een normale delve trekken.",
	DELVE_TIP_TORMENTS_RISE_TRASH = "• Pactsworn zit in normale delves, niet in Torment's Rise.|n• Verdeel cooldowns voor Nullaeus.",
	DELVE_TIP_TORMENTS_RISE_BOSS = "• Onderbreek {SPELL:@devouring_essence} elke cast (DoT + {SPELL:@umbral_rage}-stacks).|n• {SPELL:@dread_portal}: baas 100% damage reduction tot alle adds dood — volle AoE op spawn.|n• {SPELL:@oblivion_shell}: DPS-check.|n• {SPELL:@umbral_rage}: +10% damage per stack — kill adds snel.",

	DELVE_CHAT_SHADOW_ENCLAVE_OVERVIEW = "ZW Eversong (Deatholme). Spiegels, supplies, traitor: baas Lord Antenorian. Infiltrate and Ameliorate: baas Abominable Blunder.",
	DELVE_CHAT_SHADOW_ENCLAVE_ROUTE = "Spiegels: Shadow Nexuses voor licht. Supplies: buit looten. Traitor: rituals stoppen, achtervolg naar baas.",
	DELVE_CHAT_SHADOW_ENCLAVE_TRASH = "Spiegellicht = Dazzled (meer crits). Onderbreek casters. Niet stapelen op vuil.",
	DELVE_CHAT_SHADOW_ENCLAVE_BOSS = "Kick {SPELL:@shadow_bolt}. Teleport = plas — houd hem centraal. {SPELL:@shadowveil_annihilation}: 3 Orbs (alleen onbeschermde). Burst orbs.",

	DELVE_CHAT_COLLEGIATE_CALAMITY_OVERVIEW = "NW Silvermoon / Eversong (universiteit). Siege, Faculty en Glow eindigen elk bij een baas. Academic Antitoxin heeft geen baas, alleen een kist.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_ROUTE = "Siege: sluit void-portals. Faculty: Eye of Revelation, gele studenten door muren. Glow: Deweeder + Luminibulb. Antitoxin: 10 tomes, ingrediënten, genees er 7.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_TRASH = "Siege: portals eerst. Faculty: onthul, kill studenten. Glow: Deweeder tijdens lopen.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_BOSS = "Hydrangea: kill {SPELL:@wildroot_weave} vóór {SPELL:@lightbloom_salvo}. Garand: ontwijk {SPELL:@shadow_laceration}, spreid {SPELL:@twilight_crash}. Vagrant: kick {SPELL:@terrifying_power}.",

	DELVE_CHAT_THE_DARKWAY_OVERVIEW = "Noord Silvermoon Arcway. Focusers, Leyline of 7 Aberrations: baas Infiltrator Gulkat. Eggsplosive Growth: baas Replicating Venomborne.",
	DELVE_CHAT_THE_DARKWAY_ROUTE = "Focusers: ley focusers naar centrum. Leyline: conduits voor 3 crystals. Ogre: 7 Aberrations mid.",
	DELVE_CHAT_THE_DARKWAY_TRASH = "Onderbreek Seekers en Arcane Deluge. Pull uit hoeken.",
	DELVE_CHAT_THE_DARKWAY_BOSS = "Kick Seekers. Ontwijk {SPELL:@abyssal_burst}. {SPELL:@illusory_deceit}: weg van exploderende illusies.",

	DELVE_CHAT_PARHELION_PLAZA_OVERVIEW = "West Isle of Quel'Danas (Sunwell), een zwaardere delve. Bombing Run / Holding the Line / Brigade: baas Gladius Slaurna. Caustic Crush: vernietig de Ritual Pillar.",
	DELVE_CHAT_PARHELION_PLAZA_ROUTE = "Bombing Run: arcane device voor portals (40s dragen). Holding the Line: wapens + barricades. Brigade: sentinels vs pylons. Caustic Crush: kill Slimecallers en Wavecallers.",
	DELVE_CHAT_PARHELION_PLAZA_TRASH = "Kick Voidcaller Void Bolt. Clear Devouring Host vóór baas.",
	DELVE_CHAT_PARHELION_PLAZA_BOSS = "Kill 3 Voidcallers snel. Overleeft er één {SPELL:@devouring_nova}, Slaurna bufft hard. Ontwijk {SPELL:@voidscar_raze}, vecht centraal.",

	DELVE_CHAT_ATAL_AMAN_OVERVIEW = "West Zul'Aman. Ritual / Toadly / Totem: baas Spiritflayer Jin'Ma. Venomous Vapors: baas Disciple of Vashnik.",
	DELVE_CHAT_ATAL_AMAN_ROUTE = "Ritual: red furbolgs. Toadly: Hex Stick. Totem: vernietig totems, Akil'zon.",
	DELVE_CHAT_ATAL_AMAN_TRASH = "Onderbreek Vilebranch. Totem: totems op pad eerst.",
	DELVE_CHAT_ATAL_AMAN_BOSS = "{SPELL:@flaying_knife} spirits = +10% dmg — pak de jouwe. Ontwijk {SPELL:@raging_spirits}. Vóór {SPELL:@claim_spirits}: spirits ophalen.",

	DELVE_CHAT_TWILIGHT_CRYPTS_OVERVIEW = "ZW Zul'Aman (Broken Throne). Loa / Party Crasher / Trapped: baas Blademaster Darza. Why'd it have to be snakes?: baas Replicating Venomborne.",
	DELVE_CHAT_TWILIGHT_CRYPTS_ROUTE = "Loa: niet door Mot'amra's pad. Party Crasher: escort, vallen. Trapped: gijzelaars + levers.",
	DELVE_CHAT_TWILIGHT_CRYPTS_TRASH = "Mot'amra = knockback op zijn pad. Onderbreek summoners. Let op vallen.",
	DELVE_CHAT_TWILIGHT_CRYPTS_BOSS = "Ontwijk {SPELL:@shade_cleave} (dichtbij = geen {SPELL:@dark_pursuit}). Trek Darza uit {SPELL:@bask_in_the_twilight} (+30% dmg erin).",

	DELVE_CHAT_GULF_OF_MEMORY_OVERVIEW = "West Harandar. Munchies / Descent / Sporasaur. Bazen: Lumenia of Mul'tha'ul.",
	DELVE_CHAT_GULF_OF_MEMORY_ROUTE = "Munchies: Alnmoth Storm onderweg. Descent: kaarsen, uit duisternis. Sporasaur: schop Sporbits in schild.",
	DELVE_CHAT_GULF_OF_MEMORY_TRASH = "Blijf in licht (Descent). Schop Sporbits vroeg. Storm = bewegen mag.",
	DELVE_CHAT_GULF_OF_MEMORY_BOSS = "Lumenia: kill {SPELL:@radiant_command}-add vóór explode. Mul'tha'ul: dispel {SPELL:@hopeless_curse}, kit {SPELL:@tear_it_down}, {SPELL:@unanswered_call}.",

	DELVE_CHAT_GRUDGE_PIT_OVERVIEW = "ZO Harandar, arena-delve. Champion / Rotstalk / Invasion / Pharmacon. Bazen: Brightthorn, Gyrospore, Mycomight of Replicating Venomborne.",
	DELVE_CHAT_GRUDGE_PIT_ROUTE = "Champion: golven (Sporbits). Rotstalk: fans schoppen, taunt crowd. Invasion: fighters vrij, spawn points.",
	DELVE_CHAT_GRUDGE_PIT_TRASH = "Sporbits in arena. Clear invasion-golven. Rotstalk-fans niet negeren.",
	DELVE_CHAT_GRUDGE_PIT_BOSS = "Brightthorn: ontwijk {SPELL:@solar_charge}, interrupt Bloom Thorn, weg van {SPELL:@blinding_burst}. Gyrospore: ontwijk {SPELL:@fungalstorm}, burst dizzy. Mycomight: plassen weg.",

	DELVE_CHAT_VENOMFALL_DEEPS_OVERVIEW = "Nemesis-delve, noordelijke eiland Coiled Isle. Azta'rec. Kom met 290 ilvl voor ?, 309 voor ??. Valeera op Healer. Coördinaten werken hier niet.",
	DELVE_CHAT_VENOMFALL_DEEPS_BOSS = "Vaste volgorde: Noxious Bile, Void Toxin, Soul Extinction, Venom Storm - kick altijd de derde. Op 90/60/30%: sta in het vrije kwart, onthoud de VOLGORDE; hij herhaalt hem onzichtbaar. Op ??: kill de Echo. Eén treffer = +500% nature.",

	DELVE_CHAT_SUNKILLER_SANCTUM_OVERVIEW = "Oost Voidstorm. Core / Not Expected / Gravity. Baas Esuritus (of 3 Umbraroot, geen baas).",
	DELVE_CHAT_SUNKILLER_SANCTUM_ROUTE = "Core: stop Domanaar met orbs (snelheid + DR). Not Expected: 3 Umbraroot. Gravity: singularities voor schilden.",
	DELVE_CHAT_SUNKILLER_SANCTUM_TRASH = "Pak orbs in Core. Not What I Expected: pull de 3 Corrupted Umbraroot één voor één.",
	DELVE_CHAT_SUNKILLER_SANCTUM_BOSS = "Alle Voidcallers dood vóór {SPELL:@gorge}, anders +damage stacks. Kick {SPELL:@calling_bolt}. {SPELL:@coalescing_malediction} eindigt in een Voidcaller. Ontwijk {SPELL:@crushing_rift} (4 callers).",

	DELVE_CHAT_SHADOWGUARD_POINT_OVERVIEW = "West Voidstorm. Calamitous / Wildlife / Stolen Mana vs ethereals: baas Chief-Arcanist Patram. Basilisk Blitz: baas Disciple of Vashnik.",
	DELVE_CHAT_SHADOWGUARD_POINT_ROUTE = "Calamitous: overload stabilizers met Arcane Charges. Wildlife: mobs voorzichtig vrijlaten. Mana: Galvanic Blast op containers tot de Barrier valt. Basilisk Blitz: generators opnieuw instellen, kill 4 Energized Basilisks.",
	DELVE_CHAT_SHADOWGUARD_POINT_TRASH = "Onderbreek ethereals. Charges veilig dragen.",
	DELVE_CHAT_SHADOWGUARD_POINT_BOSS = "Kick {SPELL:@void_bolt_patram}. Kill Void Emissary vóór {SPELL:@submit_to_the_void}. Ontwijk {SPELL:@discordant_hymn}.",

	DELVE_CHAT_TORMENTS_RISE_OVERVIEW = "Nemesis-delve (Voidstorm). Tier ? / ?? regels. Baas Nullaeus — healer Valeera op ??.",
	DELVE_CHAT_TORMENTS_RISE_ROUTE = "Eigen portal (Shift-J / TomTom). Geen roterende world-delve.",
	DELVE_CHAT_TORMENTS_RISE_TRASH = "Bewaar CDs voor Nullaeus — geen Pactsworn binnen.",
	DELVE_CHAT_TORMENTS_RISE_BOSS = "Kick elke {SPELL:@devouring_essence}. {SPELL:@dread_portal}: AoE adds tot dood. {SPELL:@oblivion_shell} = DPS-check. Geen {SPELL:@umbral_rage}-stacks.",
})

merge(ns._mhLocales and ns._mhLocales.deDE, {
	["DELVE_NAME_SHADOW_ENCLAVE"] = "Die Schattenenklave",
	["DELVE_NAME_COLLEGIATE_CALAMITY"] = "College-Katastrophe",
	["DELVE_NAME_THE_DARKWAY"] = "Der dunkle Weg",
	["DELVE_NAME_PARHELION_PLAZA"] = "Parhelion Plaza",
	["DELVE_NAME_ATAL_AMAN"] = "Atal'Aman",
	["DELVE_NAME_TWILIGHT_CRYPTS"] = "Zwielichtgruften",
	["DELVE_NAME_GULF_OF_MEMORY"] = "Der Golf der Erinnerung",
	["DELVE_NAME_GRUDGE_PIT"] = "Die Grollgrube",
	["DELVE_NAME_SUNKILLER_SANCTUM"] = "Sunkiller-Heiligtum",
	["DELVE_NAME_SHADOWGUARD_POINT"] = "Schattenwächterpunkt",
	["DELVE_NAME_TORMENTS_RISE"] = "Aufstieg der Torment",
	["DELVE_TIP_SHADOW_ENCLAVE_OVERVIEW"] = "• Südwesten von Eversong Woods (Ruins of Deatholme).|n• Vier Varianten: Mirror Shine, Shadowy Supplies, Traitor's Due und Infiltrate and Ameliorate (neu in 12.1).|n• Traitor's Due: Rituale stoppen, Leerenkugeln, Kultisten (gut zum Leveln).|n• Mirror Shine, Shadowy Supplies und Traitor's Due enden bei Lord Antenorian. Infiltrate and Ameliorate endet bei Abominable Blunder.",
	["DELVE_TIP_SHADOW_ENCLAVE_ROUTE"] = "• Mirror Shine: Trag die Spiegel durch die dunklen Hallen; triff die Shadow Nexuses, um Licht zu verbreiten (hält Grues fern).|n• Shadowy Supplies: Sammel die Wertsachen von Twilight's Blade ein – von Mobs oder vom Boden.|n• Traitor's Due: Jag Antenorian durch den Delve bis zum Bossraum.|n• Infiltrate and Ameliorate: Sprich mit Scout Lok'aemon und stoß dann 5 Ula'tek Summoners in den Abgrund.|n• Infiltrate and Ameliorate: Sabotier 4 Kessel, indem du seltsame Zutaten hineinwirfst. Manche Zutaten liegen weit oben: Nutz die Sprungpilze.|n• Infiltrate and Ameliorate: Töte als Nächstes den Ula'tek Supreme Summoner und sieh dir die Beschwörung an. Danach kommt Abominable Blunder, der Endboss.|n• Infiltrate and Ameliorate: Nimm {SPELL:@fungal_pharmacon} auf und wirf es auf die Giftpfützen, um sie zu reinigen. Es schadet auch Gegnern nahe der Einschlagstelle.",
	["DELVE_TIP_SHADOW_ENCLAVE_TRASH"] = "• Im Spiegellicht bekommt ihr beide Dazzled, du und die Gegner (höhere Crit-Chance).|n• Unterbrich die Schattenzauberer.|n• Räum bei Shadowy Supplies die Twilight's Blade ab.|n• Stell dich nicht in gefährliche Flächen; pulle in engen Gängen vorsichtig.",
	["DELVE_TIP_SHADOW_ENCLAVE_BOSS"] = "• Lord Antenorian: Unterbrich {SPELL:@shadow_bolt}, wann immer du kannst.|n• Lord Antenorian: Seine Teleports hinterlassen eine schädliche Pfütze. Halt ihn nahe der Mitte.|n• Lord Antenorian: {SPELL:@shadowveil_annihilation} ist ein tödlicher Kanalzauber. Zerstör die 3 Shadow Orbs: Nur die Kugel ohne Schild nimmt Schaden, und jeder Kill nimmt der nächsten den Schild.|n• Lord Antenorian: Sind alle Kugeln tot, bricht sein Schild, der Kanalzauber stoppt und er nimmt ein paar Sekunden lang mehr Schaden.|n• Lord Antenorian: Heb deinen Burst für die Kugeln auf. Valeera hilft, sie zu zerstören.|n• Abominable Blunder (Infiltrate and Ameliorate): Corrosive Bile ist sein normaler Giftangriff. Heil den Schaden einfach weg.|n• Abominable Blunder (Infiltrate and Ameliorate): {SPELL:@searing_spew} schadet allen im Umkreis von 14 Metern um ihn und verlangsamt sie. Geh weg, wenn er es wirkt.|n• Abominable Blunder (Infiltrate and Ameliorate): Acid Spray schickt ein paar Sekunden lang Säurewellen los. Weich weiter seitlich aus, bis es vorbei ist.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_OVERVIEW"] = "• Nordwesten von Silvermoon / Eversong Woods (Thalassian University).|n• Academy Under Siege -> Voidscorned Vagrant.|n• Faculty of Fear -> Infiltrator Garand.|n• Invasive Glow -> Hydrangea.|n• Academic Antitoxin (auf der Karte: An Elementary Antidote): kein Endboss. Stattdessen erscheint ein Schatz.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_ROUTE"] = "• Under Siege: Schließ die Leerenportale und töte Devouring Host.|n• Faculty of Fear: Eye of Revelation – verdächtige Studenten leuchten gelb durch Wände.|n• Invasive Glow: Der Deweeder tötet kleine Lightbloom und schadet großen.|n• Räum die Luminibulb-Felder auf der Hauptebene ab.|n• Academic Antitoxin: Sprich mit Sir Finley Mrrgglton und sammel dann 10 Research Tomes.|n• Academic Antitoxin: Sammel danach Zutaten und gib 7 Envenomed Denizens das Gegenmittel. Beides zählt gleichzeitig.|n• Academic Antitoxin: Die Zutatenleiste braucht 400. Kleine Zutaten geben 2, mittlere 20 und große 35 – nimm also die großen.|n• Academic Antitoxin: {SPELL:@fungal_pharmacon} reinigt die Giftpfützen und trifft auch Gegner im Umkreis von 5 Metern um die Einschlagstelle.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_TRASH"] = "• Under Siege: Portale schließen hat Vorrang.|n• Faculty: Enttarn die verkleideten Studenten und töte sie, bevor sie dich überfallen.|n• Glow: Kanalisier den Deweeder in Bewegung.|n• Überspring keine Luminibulb-Felder, sonst zieht sich der Run.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_BOSS"] = "• Hydrangea (Glow): Töte die Wurzeln von {SPELL:@wildroot_weave} vor {SPELL:@lightbloom_salvo}; weich den Lichtzonen aus.|n• Garand (Faculty): Weich {SPELL:@shadow_laceration} aus oder nutz einen Defensiv-CD; geh bei den Sprüngen von {SPELL:@twilight_crash} auf Abstand.|n• Voidscorned Vagrant (Siege): Tritt bei {SPELL:@void_eruption} zur Seite; unterbrich {SPELL:@terrifying_power} immer.|n• Academic Antitoxin: Es gibt keinen Endboss. Der Schatz erscheint, wenn der letzte Schritt erledigt ist.",
	["DELVE_TIP_THE_DARKWAY_OVERVIEW"] = "• Norden von Silvermoon / Eversong Woods (Arcway).|n• Focusers Under Pressure, Leyline Technician, Ogre Powered (7 Unstable Aberrations).|n• Focusers, Leyline, Ogre Powered -> Infiltrator Gulkat.|n• Eggsplosive Growth (12.1) -> Replicating Venomborne.",
	["DELVE_TIP_THE_DARKWAY_ROUTE"] = "• Focusers: Find die Leylinien-Fokussierer und bring sie zurück in die Mitte des Delves.|n• Leyline: Zapf pro Linie einmal die Leitungen an, um drei Fokuskristalle aufzuladen.|n• Ogre Powered: Töte im Mittelteil 7 Unstable Aberrations, bevor du zu Gulkat gehst.",
	["DELVE_TIP_THE_DARKWAY_TRASH"] = "• Unterbrich Twilight Seekers und Arcane Deluge bei den Aberrations.|n• Leyline-Variante: Töte Twilight's Blade, während du die Energie umleitest.|n• Pulle in den engen Arcway-Hallen weg von den Ecken.",
	["DELVE_TIP_THE_DARKWAY_BOSS"] = "• Unterbrich die Twilight Seekers.|n• Weich {SPELL:@abyssal_burst} aus (Frontalkegel).|n• {SPELL:@illusory_deceit}: explodierende Illusionen – halt Abstand, während du dich um Gulkat kümmerst.|n• Replicating Venomborne: Töte die Lesser Venomborne aus {SPELL:@serpentogenesis} sofort – leben sie bei seinem nächsten Wirken noch, heilen sie ihn; verlass die Pfützen von {SPELL:@venom_splash_venomborne} (Schaden + Verlangsamung); {SPELL:@hydra_strike} hinterlässt einen stapelnden DoT.",
	["DELVE_TIP_PARHELION_PLAZA_OVERVIEW"] = "• Westen der Isle of Quel'Danas (Sunwell-Gebiet).|n• Wird mit March on Quel'Danas freigeschaltet (Ende März 2026).|n• Bombing Run, Holding the Line und March of the Arcane Brigade enden bei Gladius Slaurna.|n• Einer der schwereren Midnight-Delves.|n• Caustic Crush (neu in 12.1): Die Slime Shamen of Ula'tek beschwören Schleime und schicken Giftwellen los. Das letzte Ziel ist eine Ritual Pillar, nicht Gladius Slaurna.",
	["DELVE_TIP_PARHELION_PLAZA_ROUTE"] = "• Bombing Run: Improvised Arcane Device gegen die Leerenportale (40 Sek. Tragezeit; im Kampf lässt du es fallen).|n• Holding the Line: Waffen aus Tempest Keep + Barrikaden wieder aufbauen.|n• March of the Arcane Brigade: Weck die Sentinel-Maschinen; sie laufen zu den Leerenpylonen. Zerstör 3 Pylone und töte Devouring Host, um die Leiste zu füllen.|n• Caustic Crush: Sprich mit Vindicator Xayann. Töte dann die Schleime, 4 Shaman Slimecallers und 6 Ula'tek Wavecallers.|n• Caustic Crush: Nimm unterwegs {SPELL:@fungal_pharmacon} auf. Wirf es auf die Ula'tek Poison Pools, um sie zu reinigen. Es schadet auch Gegnern nahe der Einschlagstelle.|n• Caustic Crush: Die Ziele verlangen auch, dass du einen Bau benutzt. Das allerletzte Ziel ist, die Ritual Pillar zu zerstören.",
	["DELVE_TIP_PARHELION_PLAZA_TRASH"] = "• Bombing Run: Verlass nie ein Portal, bevor du es gesprengt hast. Es schließt sich endgültig, und du kannst den Lauf nicht beenden.|n• Räum die Wellen von Devouring Host ab, bevor du zu Slaurna gehst.|n• Caustic Crush: Weich jeder Giftwelle aus. Ein Treffer betäubt dich und verursacht schweren Naturschaden.",
	["DELVE_TIP_PARHELION_PLAZA_BOSS"] = "• Gladius Slaurna: Töte seine drei Sacrificial Voidcaller schnell und unterbrich ihren Void Bolt.|n• Gladius Slaurna: Jeder Voidcaller, der am Ende von {SPELL:@devouring_nova} noch lebt, lässt ihn härter zuschlagen und weniger Schaden nehmen. Auf hohen Tiers kann das einen Wipe bedeuten.|n• Gladius Slaurna: Tritt aus der Linie von {SPELL:@voidscar_raze}. Sie zielt oft auf Valeera, also stell dich nicht zwischen die beiden.|n• Gladius Slaurna: Kämpf nahe der Mitte, damit dich {SPELL:@devouring_nova} nicht von der Plattform stoßen kann.",
	["DELVE_TIP_ATAL_AMAN_OVERVIEW"] = "• Westen von Zul'Aman (Grenze zu Eversong).|n• Ritual Interrupted, Toadly Unbecoming, Totem Annihilation.|n• Ritual Interrupted, Toadly Unbecoming und Totem Annihilation enden bei Spiritflayer Jin'Ma.|n• Season 2, Venomous Vapors: Endboss Disciple of Vashnik (auch in Shadowguard Point).",
	["DELVE_TIP_ATAL_AMAN_ROUTE"] = "• Ritual: Befrei die entführten Spiritpaw-Furbolgs überall im Delve.|n• Toadly: Banne den Hex von den Amani mit dem Vilebranch Hex Stick, während du die Eindringlinge tötest.|n• Totem: Zerstör die verfluchten Totems, um Akil'zon zu befreien; über die Adler kommst du auf anderen Wegen ran.|n• Venomous Vapors: Öffne die 2 Truhen im ersten Raum und nimm Marlas Werkzeuge: {SPELL:@venomous_fireball}, den du in eine Toxic Cloud wirfst, um sie zu sprengen (halte Abstand), und ein Werkzeug, mit dem du sehr hoch springst. Besiege die 5 Venom Vipers; der Disciple of Vashnik wartet am Ende.",
	["DELVE_TIP_ATAL_AMAN_TRASH"] = "• Unterbrich die Zauber der Vilebranch.|n• Totem-Variante: Nimm zuerst die Totems auf dem Weg mit.|n• Zieh die Bestien von den verhexten NPCs weg, die du retten willst.|n• Venomous Vapors: Die Venom Vipers gehören zum Ziel, also töte alle 5.",
	["DELVE_TIP_ATAL_AMAN_BOSS"] = "• {SPELL:@flaying_knife} spaltet Geister ab – jeder eingesammelte Geist gibt +10 % Schaden (sammel sie gezielt ein).|n• Weich {SPELL:@raging_spirits} am Boden aus.|n• Sammel deine Geister ein, bevor {SPELL:@claim_spirits} endet – sonst bekommt Jin'Ma den Buff.|n• Disciple of Vashnik: Unterbrich immer {SPELL:@malignance}, eine 4 Sekunden lange Salve aus Giftkugeln, deren Schaden sich stapelt und die dich verlangsamen. Valeera unterbricht ihn nicht jedes Mal, also mach es selbst.|n• Disciple of Vashnik: {SPELL:@toxic_froth} verursacht 8 Sekunden lang schweren Giftschaden, und hinter einer Wand verstecken hilft nicht mehr. Reinige das Gift, wenn deine Klasse das kann, nutz einen Defensiv-Cooldown oder stell Valeera auf Heilerin; sammel danach die Heilkugeln ein.|n• Disciple of Vashnik: {SPELL:@living_venom} stößt dich zurück und ruft einen Schleim herbei. Geh aus dem Bereich um ihn heraus und töte den Schleim, bevor er dich erreicht. Auf Tier 11 halten ihn viele Spieler für den schwersten Boss dieser Season: Geh eine Stufe runter, wenn du immer wieder stirbst.",
	["DELVE_TIP_TWILIGHT_CRYPTS_OVERVIEW"] = "• Südwesten von Zul'Aman (Broken Throne).|n• Loosed Loa (meid Mot'amra), Party Crasher, Trapped! und neu in 12.1: Why'd it have to be snakes?|n• Loosed Loa, Party Crasher und Trapped! enden bei Blademaster Darza. Why'd it have to be snakes? endet bei Replicating Venomborne.",
	["DELVE_TIP_TWILIGHT_CRYPTS_ROUTE"] = "• Loosed Loa: Mit dem Evasive Elixir kommst du überall hin; töte Skeleton Charmers und Totems – behalt Mot'amra im Blick und kreuz seinen Weg nicht.|n• Loosed Loa: Seit dem Hotfix vom 10. September gibt es in dieser Variante Explorer's League Supplies und einen Abandoned Restoration Stone.|n• Party Crasher: Töte die 4 Twilight Summoners (sie stehen auf deiner Karte) und betätige 7 Suspicious Levers. Bärenfallen betäuben dich für etwa 2 Sekunden.|n• Trapped: Befrei die Geiseln und finde die Hebel im Labyrinth.|n• Why'd it have to be snakes?: Hilf Harrison Jones, die verlorenen Relikte in den Gruften zu finden.|n• Why'd it have to be snakes?: Auf die Schlangen zu treten gehört zum Ziel, aber sie explodieren, wenn du auf sie trittst.|n• Why'd it have to be snakes?: Nimm {SPELL:@fungal_pharmacon} auf und wirf es auf Giftflächen, um sie zu reinigen.",
	["DELVE_TIP_TWILIGHT_CRYPTS_TRASH"] = "• Mot'amra haut hart zu und stößt dich weg, wenn du in ihn hineinläufst.|n• Party Crasher: Achte auf die Fallenplatten.|n• Unterbrich die Beschwörer von Twilight's Blade.",
	["DELVE_TIP_TWILIGHT_CRYPTS_BOSS"] = "• Blademaster Darza: Tritt bei {SPELL:@shade_cleave} zur Seite. Kämpfst du nah dran, verhinderst du ihren Ansturm {SPELL:@dark_pursuit}.|n• Blademaster Darza: {SPELL:@bask_in_the_twilight} hinterlässt eine Leerenzone am Boden.|n• Zieh Darza da heraus, sonst macht sie darin +30 % Schaden.|n• Replicating Venomborne (Why'd it have to be snakes?): Töte die Lesser Venomborne aus {SPELL:@serpentogenesis} sofort. Leben sie bei seinem nächsten Wirken noch, heilen sie ihn.|n• Replicating Venomborne (Why'd it have to be snakes?): Tritt aus den Pfützen von {SPELL:@venom_splash_venomborne}. Sie schaden dir und verlangsamen dich.|n• Replicating Venomborne (Why'd it have to be snakes?): {SPELL:@hydra_strike} hinterlässt stapelnden Giftschaden auf dir. Behalt die Stacks im Auge und heil den Schaden weg.",
	["DELVE_TIP_GULF_OF_MEMORY_OVERVIEW"] = "• Westen von Harandar (Den of Echoes / Har'alnor).|n• Drei Varianten.|n• Bosse: Lumenia (Munchies / Sporasaur) und Mul'tha'ul (Descent of the Haranir).",
	["DELVE_TIP_GULF_OF_MEMORY_ROUTE"] = "• Alnmoth Munchies: Alnmoth Storm liegt auf der Extraaktionstaste und läuft auch in Bewegung – verschling Büsche oder setz ihn gegen die Rutaani ein.|n• Descent: Zünd die riesigen Kerzen an; in dunklen Bereichen nimmst du mehr Schaden.|n• Sporasaur: Kick Sporbits mit grünem Fadenkreuz in die Sporasaurs, um deren Schild zu entfernen.",
	["DELVE_TIP_GULF_OF_MEMORY_TRASH"] = "• Bleib bei Descent in beleuchteten Bereichen.|n• Kick die Sporbits, bevor sie explodieren.|n• Kanalisier Alnmoth Storm in Bewegung – laufen und wirken geht gleichzeitig.",
	["DELVE_TIP_GULF_OF_MEMORY_BOSS"] = "• Lumenia: Töte das Add aus {SPELL:@radiant_command}, bevor es dich erreicht (es explodiert).|n• Weich den Flächen von {SPELL:@searing_light} aus, außer du nutzt sie gegen das Add.|n• Mul'tha'ul: Unterbrich oder banne {SPELL:@hopeless_curse}.|n• Kite weg von den Tentakeln aus {SPELL:@tear_it_down}.|n• Halt bei {SPELL:@unanswered_call} Abstand (hoher Schaden, langsame Bewegung).",
	["DELVE_TIP_GRUDGE_PIT_OVERVIEW"] = "• Südosten von Harandar.|n• Lightbloom Invasion -> Brightthorn.|n• Arena Champion -> Gyrospore.|n• Dastardly Rotstalk -> Mycomight.|n• Fungal Pharmacon -> Replicating Venomborne.",
	["DELVE_TIP_GRUDGE_PIT_ROUTE"] = "• Arena Champion: Verprügel die Kämpfer, töte Bogdamp, Moldrus und 5 Spewing Deathcaps, sammel 6 Mold Samples und stell dein Banner auf. Dann kommt Gyrospore.|n• Dastardly Rotstalk: Du spielst den Bösewicht – kick die Fans weg, verspotte das Publikum (Verspotten geht auch in Bewegung).|n• Lightbloom Invasion: Wellen abwehren, Kämpfer befreien, Spawnpunkte sprengen, Verteidigungen bauen.",
	["DELVE_TIP_GRUDGE_PIT_TRASH"] = "• Arena Champion: Nutz die freundlichen Sporbits. Sie machen zusätzlichen Schaden gegen die Arenakämpfer.|n• Lightbloom Invasion: Räum die Wellen ab, bevor der Boss kommt.|n• Rotstalk: Behalt das Publikum unter Kontrolle – ignorierte Fans tun weh.",
	["DELVE_TIP_GRUDGE_PIT_BOSS"] = "• Brightthorn: Tritt bei {SPELL:@solar_charge} zur Seite (hinterlässt Overbloom-Zonen); unterbrich {SPELL:@bloom_thorn}; dreh dich vor {SPELL:@blinding_burst} weg.|n• Gyrospore: Weich den {SPELL:@fungalstorm}-Zonen aus und burste dann während der 10 Sek. Benommenheit; geh bei {SPELL:@fungsplosion} zurück; tritt bei {SPELL:@fungal_charge} zur Seite.|n• Mycomight: Setz die Pfützen von {SPELL:@rancid_rain} abseits der Kampffläche ab; weich den Schockwellen von {SPELL:@fungis_fist} aus; tritt bei {SPELL:@fling_chair} zur Seite.|n• Replicating Venomborne: Töte die Lesser Venomborne aus {SPELL:@serpentogenesis} sofort – leben sie bei seinem nächsten Wirken noch, heilen sie ihn; verlass die Pfützen von {SPELL:@venom_splash_venomborne} (Schaden + Verlangsamung); {SPELL:@hydra_strike} hinterlässt einen stapelnden DoT.|n• Gyrospore: DBM und dein Delve-Verlauf nennen diesen Kampf Spinshroom – ein Name, den Blizzard von einem alten Boss wiederverwendet hat. Es ist derselbe Kampf.",
	["DELVE_TIP_SUNKILLER_SANCTUM_OVERVIEW"] = "• Osten von Voidstorm (Eingang Voidspire).|n• Core of the Problem und The Gravitational Effect enden bei Esuritus. Not What I Expected hat keinen Boss.|n• Not What I Expected: kein Boss – endet nach 3 getöteten Corrupted Umbraroot.",
	["DELVE_TIP_SUNKILLER_SANCTUM_ROUTE"] = "• Core of the Problem: Portale schließen + verhindern, dass die Domanaar Energized Orbs stehlen (Kugel-Buff: Tempo + Schadensreduktion).|n• Not What I Expected: Klick 7 Lightbloom Crates an, benutz das Sanctum Security Panel und füll die Kill-Leiste (Lightbloom- und Leerengegner zählen beide). Töte dann 3 Corrupted Umbraroot.|n• Gravitational Effect: Nutz die Mikrosingularitäten zum Vorankommen und um die Bossschilde abzuschalten.|n• Not What I Expected: Lauf durch ein Displacement Portal. Dann kämpft etwa 5 Minuten lang eine Kopie von dir an deiner Seite.",
	["DELVE_TIP_SUNKILLER_SANCTUM_TRASH"] = "• Sammel in der Core-Variante die Kugeln ein, das hält dich am Leben.|n• Not What I Expected: Die 3 Corrupted Umbraroot sind Elites. Pull sie einzeln.|n• Not What I Expected: Unterbrich den Lightbloom Beam der Corrupted Umbraroot und weich Blooming Bile (ein Frontalangriff, der Adds erschafft) und Rotting Charge (hinterlässt eine Pfütze) seitlich aus.",
	["DELVE_TIP_SUNKILLER_SANCTUM_BOSS"] = "• Töte alle Voidcaller vor {SPELL:@gorge}, sonst bekommt er pro Verschlungenem 30 Sek. lang mehr Schaden.|n• Unterbrich {SPELL:@calling_bolt}.|n• Wenn {SPELL:@coalescing_malediction} endet oder gebannt wird, erscheint ein Voidcaller. Bann es erst, wenn du bereit bist, dieses Add zu töten.|n• Weich {SPELL:@crushing_rift} aus (beschwört 4 Voidcaller).",
	["DELVE_TIP_SHADOWGUARD_POINT_OVERVIEW"] = "• Westen von Voidstorm (nördlich von Abundant Voidburrow).|n• Vier Varianten. In dreien kämpfst du gegen die Shadowguard Ethereals; in Basilisk Blitz hilfst du ihnen, den Punkt zurückzuerobern.|n• Endboss in drei Varianten: Chief-Arcanist Patram. Basilisk Blitz endet stattdessen beim Disciple of Vashnik.|n• Season 2, Basilisk Blitz: Endboss Disciple of Vashnik (auch in Atal'Aman).",
	["DELVE_TIP_SHADOWGUARD_POINT_ROUTE"] = "• Calamitous: Überlade die Void Stabilizers mit Arcane Charges (Tempo-Buff; die Explosionen töten Mobs – stell dich nicht hinein).|n• Captured Wildlife: Befrei die Leerenkreaturen (ihr AoE trifft dich trotzdem).|n• Stolen Mana: Nimm das Gewehr auf und setz Galvanic Blast auf die Manabehälter ein, bis die Arcane Barrier fällt.|n• Basilisk Blitz: Sprich am Anfang mit dem verwundeten Ätherischen. Konfigurier dann den Energy Distributor neu und töte den Ula'tek Basilisk.|n• Basilisk Blitz: Nimm das Waygate, um weiterzukommen. Konfigurier dann die 4 Power Generators neu und töte die 4 Energized Basilisks.|n• Basilisk Blitz: Der Disciple of Vashnik wird erst zu deinem Ziel, wenn alle 4 Energized Basilisks tot sind.",
	["DELVE_TIP_SHADOWGUARD_POINT_TRASH"] = "• Calamitous: Plan die Überladungen sicher, solange du Arcane Charges trägst.|n• Ethereal-Gruppen: Unterbrich ihre Zauber.|n• Wildlife-Variante: Lass den befreiten Kreaturen Platz.|n• Basilisk Blitz: Solange die Barriere eines Basilisken hält, wirft er Giftblitze auf dich. Läufst du in die Barriere, wirst du ein paar Sekunden betäubt.",
	["DELVE_TIP_SHADOWGUARD_POINT_BOSS"] = "• Unterbrich {SPELL:@void_bolt_patram}.|n• Töte den Void Emissary, bevor {SPELL:@submit_to_the_void} endet (du bekommst Vielseitigkeit + CDR; schaffst du es nicht, bekommt Patram den Buff).|n• Tritt aus den Leerenzonen von {SPELL:@discordant_hymn} heraus (Verlangsamung + Schaden).|n• Disciple of Vashnik: Unterbrich immer {SPELL:@malignance}, eine 4 Sekunden lange Salve aus Giftkugeln, deren Schaden sich stapelt und die dich verlangsamen. Valeera unterbricht ihn nicht jedes Mal, also mach es selbst.|n• Disciple of Vashnik: {SPELL:@toxic_froth} verursacht 8 Sekunden lang schweren Giftschaden, und hinter einer Wand verstecken hilft nicht mehr. Reinige das Gift, wenn deine Klasse das kann, nutz einen Defensiv-Cooldown oder stell Valeera auf Heilerin; sammel danach die Heilkugeln ein.|n• Disciple of Vashnik: {SPELL:@living_venom} stößt dich zurück und ruft einen Schleim herbei. Geh aus dem Bereich um ihn heraus und töte den Schleim, bevor er dich erreicht. Auf Tier 11 halten ihn viele Spieler für den schwersten Boss dieser Season: Geh eine Stufe runter, wenn du immer wieder stirbst.",
	["DELVE_TIP_TORMENTS_RISE_OVERVIEW"] = "• Voidstorm – Nemesis-Delve der Season 1 (Abschluss).|n• Tier ? nach jedem T7 mit mindestens 1 Leben; Tier ?? nach jedem T10 mit mindestens 1 Leben.|n• Boss: Nullaeus.|n• Auf Tier ?? ist Valeera als Heilerin dringend zu empfehlen.",
	["DELVE_TIP_TORMENTS_RISE_ROUTE"] = "• Eigenes Instanzportal (kein rotierender Welt-Delve).|n• Nutz den Abenteuerführer (Umschalt-J) oder TomTom.|n• Wöchentliches Kopfgeld: Beacon of Hope kann Nullaeus stattdessen bei 50 % in einen normalen Delve holen.",
	["DELVE_TIP_TORMENTS_RISE_TRASH"] = "• Pactsworn-Mobs findest du in normalen Delves, nicht in Torment's Rise.|n• Teil dir die Cooldowns ein – heb Defensives und Interrupts für Nullaeus auf.",
	["DELVE_TIP_TORMENTS_RISE_BOSS"] = "• Unterbrich {SPELL:@devouring_essence} bei jedem Cast (DoT + füttert die Stacks von {SPELL:@umbral_rage}).|n• {SPELL:@dread_portal}: 100 % Schadensreduktion, bis alle Adds tot sind – beim Spawn voller AoE-Burst.|n• Die Phase mit {SPELL:@oblivion_shell} ist ein DPS-Check.|n• {SPELL:@umbral_rage}: +10 % Schaden pro Stack, wenn Adds oder DoTs stehen bleiben – töte die Adds schnell.",
	["DELVE_CHAT_SHADOW_ENCLAVE_OVERVIEW"] = "SW-Eversong (Deatholme). Spiegel, Vorräte, Verräter: Boss Lord Antenorian. Infiltrate and Ameliorate: Boss Abominable Blunder.",
	["DELVE_CHAT_SHADOW_ENCLAVE_ROUTE"] = "Spiegel: Triff die Shadow Nexuses für Licht. Vorräte: Plünder die Twilight-Wertsachen. Verräter: Rituale stoppen, bis zum Boss verfolgen.",
	["DELVE_CHAT_SHADOW_ENCLAVE_TRASH"] = "Spiegellicht = Dazzled (mehr Crits). Unterbrich die Schattenzauberer. Stell dich nicht auf schlechten Boden.",
	["DELVE_CHAT_SHADOW_ENCLAVE_BOSS"] = "Kick {SPELL:@shadow_bolt}. Der Teleport hinterlässt eine Pfütze – halt ihn mittig. {SPELL:@shadowveil_annihilation}: Töte 3 Kugeln (nur die ohne Schild). Burst auf die Kugeln.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_OVERVIEW"] = "NW-Silvermoon / Eversong (Universität). Siege, Faculty und Glow enden je mit einem Boss. Academic Antitoxin hat keinen Boss, nur eine Truhe.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_ROUTE"] = "Siege: Schließ die Leerenportale. Faculty: Eye of Revelation, gelbe Studenten durch Wände. Glow: Deweeder + Luminibulb. Antitoxin: 10 Tomes, Zutaten, 7 heilen.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_TRASH"] = "Siege: erst die Portale. Faculty: Studenten enttarnen, dann töten. Glow: Deweeder in Bewegung kanalisieren.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_BOSS"] = "Hydrangea: Töte {SPELL:@wildroot_weave} vor {SPELL:@lightbloom_salvo}. Garand: Weich {SPELL:@shadow_laceration} aus, bei {SPELL:@twilight_crash} auf Abstand. Vagrant: Kick {SPELL:@terrifying_power}.",
	["DELVE_CHAT_THE_DARKWAY_OVERVIEW"] = "Arcway im Norden von Silvermoon. Focusers, Leyline oder 7 Aberrations: Boss Infiltrator Gulkat. Eggsplosive Growth: Boss Replicating Venomborne.",
	["DELVE_CHAT_THE_DARKWAY_ROUTE"] = "Focusers: Bring die Leylinien-Fokussierer zur Mitte. Leyline: Leitungen anzapfen für 3 Kristalle. Ogre: Töte im Mittelteil 7 Unstable Aberrations.",
	["DELVE_CHAT_THE_DARKWAY_TRASH"] = "Unterbrich Twilight Seekers und Arcane Deluge. Pulle raus aus engen Ecken.",
	["DELVE_CHAT_THE_DARKWAY_BOSS"] = "Kick die Seekers. Weich {SPELL:@abyssal_burst} aus. {SPELL:@illusory_deceit}: Bleib weg von den explodierenden Illusionen.",
	["DELVE_CHAT_PARHELION_PLAZA_OVERVIEW"] = "Westen der Isle of Quel'Danas (Sunwell), ein schwererer Delve. Bombing Run / Holding the Line / Brigade: Boss Gladius Slaurna. Caustic Crush: Zerstör die Ritual Pillar.",
	["DELVE_CHAT_PARHELION_PLAZA_ROUTE"] = "Bombing Run: arkanes Gerät für die Portale (40 Sek. Tragezeit). Holding the Line: Waffen + Barrikaden. Brigade: Sentinels gegen Pylone. Caustic Crush: Töte Slimecallers und Wavecallers.",
	["DELVE_CHAT_PARHELION_PLAZA_TRASH"] = "Kick den Void Bolt der Voidcaller. Räum die Wellen von Devouring Host vor dem Boss ab.",
	["DELVE_CHAT_PARHELION_PLAZA_BOSS"] = "Töte 3 Voidcaller schnell (Void Bolt kicken). Überlebt einer {SPELL:@devouring_nova}, bufft sich Slaurna heftig. Weich {SPELL:@voidscar_raze} aus, kämpf in der Mitte.",
	["DELVE_CHAT_ATAL_AMAN_OVERVIEW"] = "Westen von Zul'Aman. Ritual / Toadly / Totem: Boss Spiritflayer Jin'Ma. Venomous Vapors: Boss Disciple of Vashnik.",
	["DELVE_CHAT_ATAL_AMAN_ROUTE"] = "Ritual: Befrei die Furbolgs. Toadly: Hex Stick auf die verhexten Amani. Totem: Totems zerstören, Akil'zon befreien.",
	["DELVE_CHAT_ATAL_AMAN_TRASH"] = "Unterbrich die Vilebranch. Totem-Run: zuerst die Totems auf dem Weg.",
	["DELVE_CHAT_ATAL_AMAN_BOSS"] = "Geister aus {SPELL:@flaying_knife} = je +10 % Schaden – sammel deine ein. Weich {SPELL:@raging_spirits} aus. Sammel vor {SPELL:@claim_spirits} alle ein, sonst bufft sich Jin'Ma.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_OVERVIEW"] = "SW-Zul'Aman (Broken Throne). Loa / Party Crasher / Trapped: Boss Blademaster Darza. Why'd it have to be snakes?: Boss Replicating Venomborne.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_ROUTE"] = "Loa: Kreuz nicht Mot'amras Weg. Party Crasher: Eskorte, Fallen, Hebel. Trapped: Geiseln + Hebel.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_TRASH"] = "Mot'amra = heftiger Rückstoß auf seinem Weg. Unterbrich die Beschwörer. Achte auf die Fallenplatten.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_BOSS"] = "Weich {SPELL:@shade_cleave} aus (im Nahkampf entfällt {SPELL:@dark_pursuit}). Zieh Darza aus {SPELL:@bask_in_the_twilight} heraus (+30 % Schaden darin).",
	["DELVE_CHAT_GULF_OF_MEMORY_OVERVIEW"] = "Westen von Harandar. Munchies / Descent / Sporasaur. Bosse: Lumenia oder Mul'tha'ul.",
	["DELVE_CHAT_GULF_OF_MEMORY_ROUTE"] = "Munchies: Alnmoth Storm in Bewegung. Descent: Kerzen anzünden, Dunkelheit meiden. Sporasaur: Kick Sporbits in die abgeschirmten Mobs.",
	["DELVE_CHAT_GULF_OF_MEMORY_TRASH"] = "Bleib bei Descent im Licht. Kick die Sporbits früh. Beim Kanalisieren des Storms kannst du laufen.",
	["DELVE_CHAT_GULF_OF_MEMORY_BOSS"] = "Lumenia: Töte das Add aus {SPELL:@radiant_command}, bevor es dich erreicht. Mul'tha'ul: Banne {SPELL:@hopeless_curse}, kite {SPELL:@tear_it_down}, halt bei {SPELL:@unanswered_call} Abstand.",
	["DELVE_CHAT_GRUDGE_PIT_OVERVIEW"] = "Arena-Delve im Südosten von Harandar. Champion / Rotstalk / Invasion / Pharmacon. Bosse: Brightthorn, Gyrospore, Mycomight oder Replicating Venomborne.",
	["DELVE_CHAT_GRUDGE_PIT_ROUTE"] = "Champion: Arena in Wellen (Sporbits helfen). Rotstalk: Fans wegkicken, Publikum verspotten. Invasion: Kämpfer befreien, Spawnpunkte sprengen.",
	["DELVE_CHAT_GRUDGE_PIT_TRASH"] = "Nutz die Sporbits in der Arena. Räum die Invasionswellen ab. Ignorier die Fans bei Rotstalk nicht.",
	["DELVE_CHAT_GRUDGE_PIT_BOSS"] = "Brightthorn: Weich {SPELL:@solar_charge} aus, unterbrich Bloom Thorn, dreh dich von {SPELL:@blinding_burst} weg. Gyrospore: Weich {SPELL:@fungalstorm} aus, burste bei Benommenheit. Mycomight: Pfützen abseits des Kampfes ablegen.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_OVERVIEW"] = "Osten von Voidstorm. Varianten Core / Not Expected / Gravity. Boss: Esuritus (oder 3 Umbraroot, kein Boss).",
	["DELVE_CHAT_SUNKILLER_SANCTUM_ROUTE"] = "Core: Hindere die Domanaar am Kugelklau (Tempo- + DR-Buff). Not Expected: 3 Corrupted Umbraroot. Gravity: Singularitäten nehmen die Schilde runter.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_TRASH"] = "Sammel in Core die Kugeln ein. Not What I Expected: Pull die 3 Corrupted Umbraroot einzeln.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_BOSS"] = "Alle Voidcaller tot vor {SPELL:@gorge}, sonst stapelt sich +Schaden. Kick {SPELL:@calling_bolt}. {SPELL:@coalescing_malediction} endet in einem Voidcaller. Weich {SPELL:@crushing_rift} aus (4 Caller).",
	["DELVE_CHAT_SHADOWGUARD_POINT_OVERVIEW"] = "Westen von Voidstorm. Calamitous / Wildlife / Stolen Mana gegen Ethereals: Boss Chief-Arcanist Patram. Basilisk Blitz: Boss Disciple of Vashnik.",
	["DELVE_CHAT_SHADOWGUARD_POINT_ROUTE"] = "Calamitous: Stabilisatoren mit Arcane Charges überladen. Wildlife: Mobs vorsichtig befreien. Mana: Galvanic Blast auf Behälter, bis die Barrier fällt. Basilisk Blitz: Generatoren umstellen, 4 Energized Basilisks töten.",
	["DELVE_CHAT_SHADOWGUARD_POINT_TRASH"] = "Unterbrich die Ethereals. Plan die Wege mit den Charges sicher.",
	["DELVE_CHAT_SHADOWGUARD_POINT_BOSS"] = "Kick {SPELL:@void_bolt_patram}. Töte den Void Emissary vor {SPELL:@submit_to_the_void}, sonst bekommt Patram den Buff. Weich {SPELL:@discordant_hymn} aus.",
	["DELVE_CHAT_TORMENTS_RISE_OVERVIEW"] = "Nemesis-Delve (Voidstorm). Regeln für Tier ? / ??. Boss Nullaeus – auf ?? Valeera als Heilerin empfohlen.",
	["DELVE_CHAT_TORMENTS_RISE_ROUTE"] = "Eigenes Portal (Umschalt-J / TomTom). Kein rotierender Welt-Delve.",
	["DELVE_CHAT_TORMENTS_RISE_TRASH"] = "Heb die CDs für Nullaeus auf – drinnen gibt es keinen Pactsworn-Trash.",
	["DELVE_CHAT_TORMENTS_RISE_BOSS"] = "Kick jeden {SPELL:@devouring_essence}. {SPELL:@dread_portal}: Adds mit AoE runterhauen. {SPELL:@oblivion_shell} = DPS-Check. Lass {SPELL:@umbral_rage} nicht stapeln.",
})

merge(ns._mhLocales and ns._mhLocales.frFR, {
	["DELVE_NAME_SHADOW_ENCLAVE"] = "L'Enclave de l'Ombre",
	["DELVE_NAME_COLLEGIATE_CALAMITY"] = "Calamité collégiale",
	["DELVE_NAME_THE_DARKWAY"] = "La Voie Obscure",
	["DELVE_NAME_PARHELION_PLAZA"] = "Place du Parhélie",
	["DELVE_NAME_ATAL_AMAN"] = "Atal'Aman",
	["DELVE_NAME_TWILIGHT_CRYPTS"] = "Cryptes du crépuscule",
	["DELVE_NAME_GULF_OF_MEMORY"] = "Le golfe de la mémoire",
	["DELVE_NAME_GRUDGE_PIT"] = "Le puits de rancune",
	["DELVE_NAME_SUNKILLER_SANCTUM"] = "Sanctuaire Tue-Soleil",
	["DELVE_NAME_SHADOWGUARD_POINT"] = "Point de la Garde de l'Ombre",
	["DELVE_NAME_TORMENTS_RISE"] = "La montée du tourment",
	["DELVE_TIP_SHADOW_ENCLAVE_OVERVIEW"] = "• Sud-ouest d'Eversong Woods (Ruins of Deatholme).|n• Quatre variantes : Mirror Shine, Shadowy Supplies, Traitor's Due et Infiltrate and Ameliorate (nouveau en 12.1).|n• Traitor's Due : arrête les rituels, les orbes du Vide, les cultistes (variante de leveling).|n• Mirror Shine, Shadowy Supplies et Traitor's Due finissent sur Lord Antenorian. Infiltrate and Ameliorate finit sur Abominable Blunder.",
	["DELVE_TIP_SHADOW_ENCLAVE_ROUTE"] = "• Mirror Shine : porte les miroirs dans les couloirs sombres ; frappe les Shadow Nexuses pour répandre la lumière (sinon l'obscurité te dévore).|n• Shadowy Supplies : ramasse les objets de valeur des Twilight's Blade, sur les mobs ou au sol.|n• Traitor's Due : poursuis Antenorian à travers le delve jusqu'à la salle du boss.|n• Infiltrate and Ameliorate : parle à Scout Lok'aemon, puis fais tomber 5 Ula'tek Summoners dans l'abîme d'un coup de pied.|n• Infiltrate and Ameliorate : sabote 4 chaudrons en y ajoutant des ingrédients bizarres. Certains ingrédients sont en hauteur : utilise les champignons sauteurs.|n• Infiltrate and Ameliorate : ensuite, tue l'Ula'tek Supreme Summoner et regarde l'invocation. Après ça vient Abominable Blunder, le boss final.|n• Infiltrate and Ameliorate : ramasse {SPELL:@fungal_pharmacon} et lance-le sur les flaques de poison pour les nettoyer. Il blesse aussi les ennemis près de son point de chute.",
	["DELVE_TIP_SHADOW_ENCLAVE_TRASH"] = "• Dans la lumière du miroir, toi et tes ennemis êtes Dazzled (plus de chances de critique).|n• Interromps les casters d'ombre.|n• Nettoie les Twilight's Blade pendant Shadowy Supplies.|n• Ne reste pas sur les zones au sol dangereuses ; pull prudemment dans les couloirs étroits.",
	["DELVE_TIP_SHADOW_ENCLAVE_BOSS"] = "• Lord Antenorian : interromps {SPELL:@shadow_bolt} dès que tu peux.|n• Lord Antenorian : ses téléportations laissent une flaque qui inflige des dégâts. Garde-le près du centre.|n• Lord Antenorian : {SPELL:@shadowveil_annihilation} est une canalisation mortelle. Détruis les 3 Shadow Orbs : seul l'orbe sans bouclier prend des dégâts, et chaque orbe tué retire le bouclier du suivant.|n• Lord Antenorian : une fois tous les orbes morts, son bouclier se brise, la canalisation s'arrête et il prend des dégâts accrus pendant quelques secondes.|n• Lord Antenorian : garde ton burst pour les orbes. Valeera aide à les casser.|n• Abominable Blunder (Infiltrate and Ameliorate) : Corrosive Bile est son attaque de poison de base. Soigne pour tenir le coup.|n• Abominable Blunder (Infiltrate and Ameliorate) : {SPELL:@searing_spew} blesse et ralentit tout le monde dans un rayon de 14 mètres autour de lui. Éloigne-toi quand il le lance.|n• Abominable Blunder (Infiltrate and Ameliorate) : Acid Spray envoie des vagues d'acide pendant quelques secondes. Continue à te décaler jusqu'à la fin.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_OVERVIEW"] = "• Nord-ouest de Silvermoon / Eversong Woods (Thalassian University).|n• Academy Under Siege -> Voidscorned Vagrant.|n• Faculty of Fear -> Infiltrator Garand.|n• Invasive Glow -> Hydrangea.|n• Academic Antitoxin (sur la carte : An Elementary Antidote) : pas de boss final. Un trésor apparaît à la place.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_ROUTE"] = "• Under Siege : ferme les portails du Vide et tue les Devouring Host.|n• Faculty of Fear : Eye of Revelation — les étudiants suspects s'illuminent en jaune à travers les murs.|n• Invasive Glow : le Deweeder tue les petits Lightbloom et blesse les grands.|n• Nettoie les zones de Luminibulb au niveau principal.|n• Academic Antitoxin : parle à Sir Finley Mrrgglton, puis réunis 10 Research Tomes.|n• Academic Antitoxin : ensuite, récolte les ingrédients et donne l'antidote à 7 Envenomed Denizens. Les deux comptent en même temps.|n• Academic Antitoxin : la barre d'ingrédients demande 400. Les petits ingrédients donnent 2, les moyens 20 et les gros 35 : prends donc les gros.|n• Academic Antitoxin : {SPELL:@fungal_pharmacon} nettoie les flaques de poison et touche aussi les ennemis dans un rayon de 5 mètres autour de son point de chute.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_TRASH"] = "• Under Siege : donne la priorité à la fermeture des portails.|n• Faculty : révèle les étudiants déguisés, puis tue-les avant qu'ils ne t'embusquent.|n• Glow : canalise le Deweeder en te déplaçant.|n• Ne saute pas les zones de Luminibulb, sinon le run traîne en longueur.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_BOSS"] = "• Hydrangea (Glow) : tue les racines de {SPELL:@wildroot_weave} avant {SPELL:@lightbloom_salvo} ; esquive les zones de lumière.|n• Garand (Faculty) : esquive {SPELL:@shadow_laceration} ou passe une défensive ; écarte-toi pour les sauts de {SPELL:@twilight_crash}.|n• Voidscorned Vagrant (Siege) : décale-toi de {SPELL:@void_eruption} ; interromps toujours {SPELL:@terrifying_power}.|n• Academic Antitoxin : il n'y a pas de boss final. Le trésor apparaît quand la dernière étape est faite.",
	["DELVE_TIP_THE_DARKWAY_OVERVIEW"] = "• Nord de Silvermoon / Eversong Woods (the Arcway).|n• Focusers Under Pressure, Leyline Technician, Ogre Powered (7 Unstable Aberrations).|n• Focusers, Leyline, Ogre Powered -> Infiltrator Gulkat.|n• Eggsplosive Growth (12.1) -> Replicating Venomborne.",
	["DELVE_TIP_THE_DARKWAY_ROUTE"] = "• Focusers : trouve les focuseurs de lignes telluriques et ramène-les au centre du delve.|n• Leyline : active les conduits une fois par ligne pour charger trois cristaux de focalisation.|n• Ogre Powered : tue 7 Unstable Aberrations dans la section centrale avant Gulkat.",
	["DELVE_TIP_THE_DARKWAY_TRASH"] = "• Interromps les Twilight Seekers et l'Arcane Deluge des aberrations.|n• Variante Leyline : tue les Twilight's Blade pendant que tu achemines l'énergie.|n• Dans les couloirs étroits de l'Arcway, pull loin des coins.",
	["DELVE_TIP_THE_DARKWAY_BOSS"] = "• Interromps les Twilight Seekers.|n• Esquive {SPELL:@abyssal_burst} (cône frontal).|n• {SPELL:@illusory_deceit} : illusions explosives — garde tes distances pendant que tu gères Gulkat.|n• Replicating Venomborne : tue tout de suite les Lesser Venomborne de {SPELL:@serpentogenesis} — encore en vie à son incantation suivante, ils le soignent ; sors des flaques de {SPELL:@venom_splash_venomborne} (dégâts + ralentissement) ; {SPELL:@hydra_strike} laisse un DoT qui se cumule.",
	["DELVE_TIP_PARHELION_PLAZA_OVERVIEW"] = "• Ouest de l'Isle of Quel'Danas (zone du Sunwell).|n• Se débloque avec March on Quel'Danas (fin mars 2026).|n• Bombing Run, Holding the Line et March of the Arcane Brigade finissent sur Gladius Slaurna.|n• L'un des delves les plus difficiles de Midnight.|n• Caustic Crush (nouveau en 12.1) : les Slime Shamen of Ula'tek invoquent des gelées et envoient des vagues de poison. Le dernier objectif est un Ritual Pillar, pas Gladius Slaurna.",
	["DELVE_TIP_PARHELION_PLAZA_ROUTE"] = "• Bombing Run : Improvised Arcane Device pour les portails du Vide (40 s de portage max ; tu le lâches en combat).|n• Holding the Line : armes de Tempest Keep + rebâtis les barricades.|n• March of the Arcane Brigade : réveille les machines Sentinel ; elles marchent vers les pylônes du Vide. Détruis 3 pylônes et tue Devouring Host pour remplir la barre.|n• Caustic Crush : parle à Vindicator Xayann. Ensuite, tue les gelées, 4 Shaman Slimecallers et 6 Ula'tek Wavecallers.|n• Caustic Crush : ramasse {SPELL:@fungal_pharmacon} en chemin. Lance-le sur les Ula'tek Poison Pools pour les nettoyer. Il blesse aussi les ennemis près de son point de chute.|n• Caustic Crush : les objectifs te demandent aussi d'utiliser un terrier. Le tout dernier objectif est de détruire le Ritual Pillar.",
	["DELVE_TIP_PARHELION_PLAZA_TRASH"] = "• Bombing Run : ne quitte jamais un portail avant de l'avoir fait sauter. Il se ferme pour de bon et tu ne peux plus finir le run.|n• Nettoie les vagues de Devouring Host avant Slaurna.|n• Caustic Crush : esquive chaque vague de poison. Un coup t'étourdit et inflige de lourds dégâts de Nature.",
	["DELVE_TIP_PARHELION_PLAZA_BOSS"] = "• Gladius Slaurna : tue vite ses trois Sacrificial Voidcallers et interromps leur Void Bolt.|n• Gladius Slaurna : chaque Voidcaller encore en vie à la fin de {SPELL:@devouring_nova} le fait frapper plus fort et subir moins de dégâts. En Tier élevé, ça peut te faire wipe.|n• Gladius Slaurna : sors de la ligne de {SPELL:@voidscar_raze}. Elle vise souvent Valeera, alors ne te mets pas entre eux.|n• Gladius Slaurna : combats près du centre, pour que {SPELL:@devouring_nova} ne puisse pas te projeter hors de la plateforme.",
	["DELVE_TIP_ATAL_AMAN_OVERVIEW"] = "• Ouest de Zul'Aman (frontière d'Eversong).|n• Ritual Interrupted, Toadly Unbecoming, Totem Annihilation.|n• Ritual Interrupted, Toadly Unbecoming et Totem Annihilation finissent sur Spiritflayer Jin'Ma.|n• Saison 2, Venomous Vapors: boss final Disciple of Vashnik (aussi à Shadowguard Point).",
	["DELVE_TIP_ATAL_AMAN_ROUTE"] = "• Ritual : libère les furbolgs Spiritpaw enlevés, un peu partout dans le delve.|n• Toadly : dissipe l'envoûtement des Amani avec le Vilebranch Hex Stick tout en tuant les envahisseurs.|n• Totem : détruis les totems maudits pour libérer Akil'zon ; utilise les aigles pour des approches alternatives.|n• Venomous Vapors : ouvre les 2 coffres de la première salle et ramasse les outils de Marla : {SPELL:@venomous_fireball}, à lancer dans une Toxic Cloud pour la faire exploser (reste à l'écart), et un outil qui te fait sauter très haut. Vaincs les 5 Venom Vipers ; le Disciple of Vashnik t'attend à la fin.",
	["DELVE_TIP_ATAL_AMAN_TRASH"] = "• Interromps les sorts des Vilebranch.|n• Variante Totem : traite en priorité les totems qui sont sur ton chemin.|n• Éloigne les bêtes des PNJ envoûtés que tu essaies de sauver.|n• Venomous Vapors: les Venom Vipers font partie de l'objectif, alors tue les 5.",
	["DELVE_TIP_ATAL_AMAN_BOSS"] = "• {SPELL:@flaying_knife} libère des esprits — chaque esprit récupéré donne +10 % de dégâts (ramasse-les volontairement).|n• Esquive {SPELL:@raging_spirits} au sol.|n• Avant la fin de {SPELL:@claim_spirits}, récupère tes esprits, sinon c'est Jin'Ma qui prend leur buff.|n• Disciple of Vashnik: interromps toujours {SPELL:@malignance}, une salve de 4 secondes de globes de venin dont les dégâts se cumulent et qui te ralentissent. Valeera ne l'interrompt pas à chaque fois, alors fais-le toi-même.|n• Disciple of Vashnik: {SPELL:@toxic_froth} inflige de lourds dégâts de poison pendant 8 secondes, et se cacher derrière un mur ne sert plus à rien. Dissipe le poison si ta classe le peut, utilise un défensif ou passe Valeera en Healer ; ramasse ensuite les orbes de soin.|n• Disciple of Vashnik: {SPELL:@living_venom} te repousse et appelle une gelée. Sors de la zone autour de lui et tue la gelée avant qu'elle ne t'atteigne. En Tier 11, beaucoup de joueurs le considèrent comme le boss le plus difficile de la saison : baisse d'un tier si tu meurs sans arrêt.",
	["DELVE_TIP_TWILIGHT_CRYPTS_OVERVIEW"] = "• Sud-ouest de Zul'Aman (Broken Throne).|n• Loosed Loa (évite Mot'amra), Party Crasher, Trapped!, et nouveau en 12.1 : Why'd it have to be snakes?|n• Loosed Loa, Party Crasher et Trapped! finissent sur Blademaster Darza. Why'd it have to be snakes? finit sur Replicating Venomborne.",
	["DELVE_TIP_TWILIGHT_CRYPTS_ROUTE"] = "• Loosed Loa : Evasive Elixir pour explorer ; tue les Skeleton Charmers et les totems — surveille Mot'amra et ne croise jamais son chemin.|n• Loosed Loa : depuis le correctif du 10 septembre, cette variante contient des Explorer's League Supplies et une Abandoned Restoration Stone.|n• Party Crasher : tue les 4 Twilight Summoners (ils apparaissent sur ta carte) et actionne 7 Suspicious Levers. Les pièges à ours t'étourdissent environ 2 secondes.|n• Trapped : sauve les otages et trouve les leviers dans le labyrinthe.|n• Why'd it have to be snakes? : aide Harrison Jones à retrouver les reliques perdues dans les cryptes.|n• Why'd it have to be snakes? : marcher sur les serpents fait partie de l'objectif, mais ils explosent quand tu marches dessus.|n• Why'd it have to be snakes? : ramasse {SPELL:@fungal_pharmacon} et lance-le sur les zones de poison pour les nettoyer.",
	["DELVE_TIP_TWILIGHT_CRYPTS_TRASH"] = "• Mot'amra frappe très fort et te projette au loin si tu lui rentres dedans.|n• Party Crasher : surveille les dalles piégées.|n• Interromps les invocateurs Twilight's Blade.",
	["DELVE_TIP_TWILIGHT_CRYPTS_BOSS"] = "• Blademaster Darza : décale-toi de {SPELL:@shade_cleave}. Rester au corps à corps l'empêche de combler la distance avec {SPELL:@dark_pursuit}.|n• Blademaster Darza : {SPELL:@bask_in_the_twilight} laisse une zone du Vide au sol.|n• Sors Darza de cette zone, sinon elle gagne +30 % de dégâts tant qu'elle reste dedans.|n• Replicating Venomborne (Why'd it have to be snakes?) : tue tout de suite les Lesser Venomborne de {SPELL:@serpentogenesis}. S'ils sont encore en vie à son incantation suivante, ils le soignent.|n• Replicating Venomborne (Why'd it have to be snakes?) : sors des flaques de {SPELL:@venom_splash_venomborne}. Elles blessent et ralentissent.|n• Replicating Venomborne (Why'd it have to be snakes?) : {SPELL:@hydra_strike} laisse sur toi des dégâts de poison qui se cumulent. Surveille les cumuls et soigne pour tenir le coup.",
	["DELVE_TIP_GULF_OF_MEMORY_OVERVIEW"] = "• Ouest d'Harandar (Den of Echoes / Har'alnor).|n• Trois variantes.|n• Boss : Lumenia (Munchies / Sporasaur) et Mul'tha'ul (Descent of the Haranir).",
	["DELVE_TIP_GULF_OF_MEMORY_ROUTE"] = "• Alnmoth Munchies : Alnmoth Storm en action supplémentaire, canalise-le en marchant — dévore les buissons ou aide contre les Rutaani.|n• Descent : allume les bougies géantes ; tu prends plus de dégâts dans le noir.|n• Sporasaur : envoie d'un coup de pied les Sporbits au réticule vert dans les Sporasaurs pour faire tomber leur bouclier.",
	["DELVE_TIP_GULF_OF_MEMORY_TRASH"] = "• Reste dans les zones éclairées pendant Descent.|n• Dégage les Sporbits d'un coup de pied avant qu'ils n'explosent.|n• Canalise Alnmoth Storm en te déplaçant — tu peux bouger et incanter en même temps.",
	["DELVE_TIP_GULF_OF_MEMORY_BOSS"] = "• Lumenia : tue l'add de {SPELL:@radiant_command} avant qu'il ne t'atteigne (il explose).|n• Esquive les zones de {SPELL:@searing_light}, sauf si tu t'en sers contre l'add.|n• Mul'tha'ul : interromps ou dissipe {SPELL:@hopeless_curse}.|n• Kite loin des tentacules de {SPELL:@tear_it_down}.|n• Garde tes distances pendant {SPELL:@unanswered_call} (gros dégâts, déplacement lent).",
	["DELVE_TIP_GRUDGE_PIT_OVERVIEW"] = "• Sud-est d'Harandar.|n• Lightbloom Invasion -> Brightthorn.|n• Arena Champion -> Gyrospore.|n• Dastardly Rotstalk -> Mycomight.|n• Fungal Pharmacon -> Replicating Venomborne.",
	["DELVE_TIP_GRUDGE_PIT_ROUTE"] = "• Arena Champion : bats les combattants, tue Bogdamp, Moldrus et 5 Spewing Deathcaps, récupère 6 Mold Samples et plante ta bannière. Ensuite arrive Gyrospore.|n• Dastardly Rotstalk : joue le méchant — dégage les fans à coups de pied, provoque la foule (tu peux te déplacer en provoquant).|n• Lightbloom Invasion : des vagues, libère des combattants pour faire sauter les points d'apparition, monte les défenses.",
	["DELVE_TIP_GRUDGE_PIT_TRASH"] = "• Arena Champion : sers-toi des Sporbits amicaux. Ils infligent des dégâts bonus aux combattants de l'arène.|n• Lightbloom Invasion : nettoie les vagues avant le boss.|n• Rotstalk : garde le contrôle de la foule — les fans font mal si tu les ignores.",
	["DELVE_TIP_GRUDGE_PIT_BOSS"] = "• Brightthorn : décale-toi de {SPELL:@solar_charge} (laisse des zones d'Overbloom) ; interromps {SPELL:@bloom_thorn} ; détourne-toi avant {SPELL:@blinding_burst}.|n• Gyrospore : esquive les zones de {SPELL:@fungalstorm}, puis burst pendant les 10 s d'étourdissement ; recule devant {SPELL:@fungsplosion} ; décale-toi de {SPELL:@fungal_charge}.|n• Mycomight : dépose les flaques de {SPELL:@rancid_rain} loin de la zone de combat ; esquive les ondes de choc de {SPELL:@fungis_fist} ; décale-toi de {SPELL:@fling_chair}.|n• Replicating Venomborne : tue tout de suite les Lesser Venomborne de {SPELL:@serpentogenesis} — encore en vie à son incantation suivante, ils le soignent ; sors des flaques de {SPELL:@venom_splash_venomborne} (dégâts + ralentissement) ; {SPELL:@hydra_strike} laisse un DoT qui se cumule.|n• Gyrospore : DBM et ton historique de delves appellent ce combat Spinshroom, un nom que Blizzard a repris d'un ancien boss. C'est le même combat.",
	["DELVE_TIP_SUNKILLER_SANCTUM_OVERVIEW"] = "• Est de Voidstorm (entrée du Voidspire).|n• Core of the Problem et The Gravitational Effect finissent sur Esuritus. Not What I Expected n'a pas de boss.|n• Not What I Expected : pas de boss — ça se termine après 3 Corrupted Umbraroot tués.",
	["DELVE_TIP_SUNKILLER_SANCTUM_ROUTE"] = "• Core of the Problem : les portails + empêche les Domanaar de voler les Energized Orbs (buff de l'orbe : vitesse + réduction des dégâts).|n• Not What I Expected : clique sur 7 Lightbloom Crates, utilise le Sanctum Security Panel et remplis la barre de kills (les ennemis Lightbloom et du Vide comptent tous les deux). Ensuite, tue 3 Corrupted Umbraroot.|n• Gravitational Effect : sers-toi des micro-singularités pour te déplacer et pour désactiver les boucliers du boss.|n• Not What I Expected : traverse un Displacement Portal. Une copie de toi combat ensuite à tes côtés pendant environ 5 minutes.",
	["DELVE_TIP_SUNKILLER_SANCTUM_TRASH"] = "• Ramasse les orbes dans la variante Core pour survivre plus facilement.|n• Not What I Expected : les 3 Corrupted Umbraroot sont des élites. Pull-les un par un.|n• Not What I Expected : interromps le Lightbloom Beam des Corrupted Umbraroot, et décale-toi de Blooming Bile (un frontal qui fait apparaître des adds) et de Rotting Charge (elle laisse une flaque).",
	["DELVE_TIP_SUNKILLER_SANCTUM_BOSS"] = "• Tue tous les Voidcallers avant {SPELL:@gorge}, sinon il gagne des dégâts en plus pendant 30 s par dévoration.|n• Interromps {SPELL:@calling_bolt}.|n• Quand {SPELL:@coalescing_malediction} se termine ou est dissipé, un Voidcaller apparaît. Ne le dissipe que quand tu es prêt à tuer cet add.|n• Esquive {SPELL:@crushing_rift} (fait apparaître 4 Voidcallers).",
	["DELVE_TIP_SHADOWGUARD_POINT_OVERVIEW"] = "• Ouest de Voidstorm (au nord d'Abundant Voidburrow).|n• Quatre variantes. Dans trois d'entre elles, tu combats les Shadowguard Ethereals ; dans Basilisk Blitz, tu les aides à reprendre le point.|n• Boss final dans trois variantes : Chief-Arcanist Patram. Basilisk Blitz finit plutôt sur le Disciple of Vashnik.|n• Saison 2, Basilisk Blitz: boss final Disciple of Vashnik (aussi à Atal'Aman).",
	["DELVE_TIP_SHADOWGUARD_POINT_ROUTE"] = "• Calamitous : surcharge les Void Stabilizers avec des Arcane Charges (buff de vitesse ; les explosions tuent les mobs — ne reste pas dedans).|n• Captured Wildlife : libère les créatures du Vide (leur AoE peut quand même te toucher).|n• Stolen Mana : récupère le fusil et lance Galvanic Blast sur les conteneurs de mana jusqu'à ce que l'Arcane Barrier tombe.|n• Basilisk Blitz : parle à l'éthéréen blessé au départ. Ensuite, reconfigure l'Energy Distributor et tue l'Ula'tek Basilisk.|n• Basilisk Blitz : prends le Waygate pour avancer. Ensuite, reconfigure les 4 Power Generators et tue les 4 Energized Basilisks.|n• Basilisk Blitz : le Disciple of Vashnik ne devient ton objectif qu'une fois les 4 Energized Basilisks morts.",
	["DELVE_TIP_SHADOWGUARD_POINT_TRASH"] = "• Calamitous : prépare tes surcharges à l'avance pendant que tu portes les Arcane Charges.|n• Packs d'Ethereals : interromps leurs sorts.|n• Variante Wildlife : laisse de la place aux créatures libérées.|n• Basilisk Blitz : tant que la barrière d'un basilic tient, il te lance des traits de poison. Entrer dans la barrière t'étourdit pendant quelques secondes.",
	["DELVE_TIP_SHADOWGUARD_POINT_BOSS"] = "• Interromps {SPELL:@void_bolt_patram}.|n• Tue le Void Emissary avant la fin de {SPELL:@submit_to_the_void} (tu gagnes Polyvalence + réduction de temps de recharge ; si tu échoues, c'est Patram qui prend le buff).|n• Décale-toi des zones du Vide de {SPELL:@discordant_hymn} (ralentissement + dégâts).|n• Disciple of Vashnik: interromps toujours {SPELL:@malignance}, une salve de 4 secondes de globes de venin dont les dégâts se cumulent et qui te ralentissent. Valeera ne l'interrompt pas à chaque fois, alors fais-le toi-même.|n• Disciple of Vashnik: {SPELL:@toxic_froth} inflige de lourds dégâts de poison pendant 8 secondes, et se cacher derrière un mur ne sert plus à rien. Dissipe le poison si ta classe le peut, utilise un défensif ou passe Valeera en Healer ; ramasse ensuite les orbes de soin.|n• Disciple of Vashnik: {SPELL:@living_venom} te repousse et appelle une gelée. Sors de la zone autour de lui et tue la gelée avant qu'elle ne t'atteigne. En Tier 11, beaucoup de joueurs le considèrent comme le boss le plus difficile de la saison : baisse d'un tier si tu meurs sans arrêt.",
	["DELVE_TIP_TORMENTS_RISE_OVERVIEW"] = "• Voidstorm — le Nemesis Delve de la saison 1 (l'épreuve finale).|n• Tier ? après n'importe quel T7 fini avec au moins 1 vie ; Tier ?? après n'importe quel T10 fini avec au moins 1 vie.|n• Boss : Nullaeus.|n• Valeera en Healer très fortement conseillée en Tier ??.",
	["DELVE_TIP_TORMENTS_RISE_ROUTE"] = "• Portail d'instance dédié (ce n'est pas un delve de monde en rotation).|n• Passe par l'Adventure Guide (Maj-J) ou TomTom.|n• Contrat hebdomadaire : Beacon of Hope peut à la place attirer Nullaeus dans un delve normal, à 50 %.",
	["DELVE_TIP_TORMENTS_RISE_TRASH"] = "• Les mobs Pactsworn se trouvent dans les delves normaux, pas à l'intérieur de Torment's Rise.|n• Gère le rythme de tes cooldowns — garde tes défensives et tes interruptions pour Nullaeus.",
	["DELVE_TIP_TORMENTS_RISE_BOSS"] = "• Interromps {SPELL:@devouring_essence} à chaque incantation (DoT + alimente les cumuls d'{SPELL:@umbral_rage}).|n• {SPELL:@dread_portal} : 100 % de réduction des dégâts tant que tous les adds ne sont pas morts — lâche tout ton burst AoE dès qu'ils apparaissent.|n• La phase {SPELL:@oblivion_shell} est un DPS check.|n• {SPELL:@umbral_rage} : +10 % de dégâts par cumul si des adds ou des DoT traînent — tue les adds vite.",
	["DELVE_CHAT_SHADOW_ENCLAVE_OVERVIEW"] = "SO Eversong (Deatholme). Miroirs, ravitaillement, traître : boss Lord Antenorian. Infiltrate and Ameliorate : boss Abominable Blunder.",
	["DELVE_CHAT_SHADOW_ENCLAVE_ROUTE"] = "Miroirs : frappe les Shadow Nexuses pour avoir de la lumière. Supplies : ramasse les objets de valeur Twilight. Traître : arrête les rituels, poursuis-le jusqu'au boss.",
	["DELVE_CHAT_SHADOW_ENCLAVE_TRASH"] = "Lumière du miroir = Dazzled (plus de crit). Interromps les casters d'ombre. Ne reste pas sur les zones au sol dangereuses.",
	["DELVE_CHAT_SHADOW_ENCLAVE_BOSS"] = "Kick {SPELL:@shadow_bolt}. La téléportation laisse une flaque — garde-le au centre. {SPELL:@shadowveil_annihilation} : tue 3 orbes (seulement celui sans bouclier). Burst les orbes.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_OVERVIEW"] = "NO Silvermoon / Eversong (l'université). Siege, Faculty et Glow finissent chacun sur un boss. Academic Antitoxin n'a pas de boss, seulement un coffre.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_ROUTE"] = "Siege : ferme les portails du Vide. Faculty : Eye of Revelation, étudiants jaunes à travers les murs. Glow : Deweeder + Luminibulb. Antitoxin : 10 tomes, ingrédients, soigne-en 7.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_TRASH"] = "Siege : les portails d'abord. Faculty : révèle puis tue les étudiants. Glow : canalise le Deweeder en te déplaçant.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_BOSS"] = "Hydrangea : tue {SPELL:@wildroot_weave} avant {SPELL:@lightbloom_salvo}. Garand : esquive {SPELL:@shadow_laceration}, écarte-toi pour {SPELL:@twilight_crash}. Vagrant : kick {SPELL:@terrifying_power}.",
	["DELVE_CHAT_THE_DARKWAY_OVERVIEW"] = "Arcway au nord de Silvermoon. Focusers, Leyline ou 7 Aberrations : boss Infiltrator Gulkat. Eggsplosive Growth : boss Replicating Venomborne.",
	["DELVE_CHAT_THE_DARKWAY_ROUTE"] = "Focusers : ramène les focuseurs telluriques au centre. Leyline : active les conduits pour 3 cristaux. Ogre : tue 7 Unstable Aberrations au milieu.",
	["DELVE_CHAT_THE_DARKWAY_TRASH"] = "Interromps les Twilight Seekers et l'Arcane Deluge. Pull loin des coins étroits.",
	["DELVE_CHAT_THE_DARKWAY_BOSS"] = "Kick les Seekers. Esquive {SPELL:@abyssal_burst}. {SPELL:@illusory_deceit} : reste loin des illusions qui explosent.",
	["DELVE_CHAT_PARHELION_PLAZA_OVERVIEW"] = "Ouest de l'Isle of Quel'Danas (Sunwell), un delve plus difficile. Bombing Run / Holding the Line / Brigade : boss Gladius Slaurna. Caustic Crush : détruis le Ritual Pillar.",
	["DELVE_CHAT_PARHELION_PLAZA_ROUTE"] = "Bombing Run : device arcanique pour les portails (40s de portage). Holding the Line : armes + barricades. Brigade : sentinelles contre pylônes. Caustic Crush : tue les Slimecallers et les Wavecallers.",
	["DELVE_CHAT_PARHELION_PLAZA_TRASH"] = "Kick le Void Bolt des Voidcallers. Nettoie les vagues de Devouring Host avant le boss.",
	["DELVE_CHAT_PARHELION_PLAZA_BOSS"] = "Tue vite 3 Voidcallers (kick Void Bolt). S'il en survit un à {SPELL:@devouring_nova}, Slaurna devient très dangereuse. Esquive {SPELL:@voidscar_raze}, combats au centre.",
	["DELVE_CHAT_ATAL_AMAN_OVERVIEW"] = "Ouest de Zul'Aman. Ritual / Toadly / Totem : boss Spiritflayer Jin'Ma. Venomous Vapors : boss Disciple of Vashnik.",
	["DELVE_CHAT_ATAL_AMAN_ROUTE"] = "Ritual : sauve les furbolgs. Toadly : Hex Stick sur les Amani envoûtés. Totem : détruis les totems, libère Akil'zon.",
	["DELVE_CHAT_ATAL_AMAN_TRASH"] = "Interromps les Vilebranch. Run Totem : d'abord les totems sur ton chemin.",
	["DELVE_CHAT_ATAL_AMAN_BOSS"] = "Les esprits de {SPELL:@flaying_knife} = +10 % de dégâts chacun — ramasse les tiens. Esquive {SPELL:@raging_spirits}. Avant {SPELL:@claim_spirits}, récupère les esprits, sinon c'est Jin'Ma qui prend le buff.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_OVERVIEW"] = "SO Zul'Aman (Broken Throne). Loa / Party Crasher / Trapped : boss Blademaster Darza. Why'd it have to be snakes? : boss Replicating Venomborne.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_ROUTE"] = "Loa : ne croise pas le chemin de Mot'amra. Party Crasher : escorte, pièges, leviers. Trapped : otages + leviers.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_TRASH"] = "Mot'amra = gros repoussement sur son chemin. Interromps les invocateurs. Surveille les dalles piégées.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_BOSS"] = "Esquive {SPELL:@shade_cleave} (au corps à corps, {SPELL:@dark_pursuit} ne part pas). Sors Darza de {SPELL:@bask_in_the_twilight} (+30 % de dégâts dedans).",
	["DELVE_CHAT_GULF_OF_MEMORY_OVERVIEW"] = "Ouest d'Harandar. Munchies / Descent / Sporasaur. Boss : Lumenia ou Mul'tha'ul.",
	["DELVE_CHAT_GULF_OF_MEMORY_ROUTE"] = "Munchies : Alnmoth Storm en marchant. Descent : allume les bougies, évite le noir. Sporasaur : envoie les Sporbits dans les mobs à bouclier.",
	["DELVE_CHAT_GULF_OF_MEMORY_TRASH"] = "Reste dans la lumière pendant Descent. Dégage les Sporbits tôt. Tu peux te déplacer en canalisant Alnmoth Storm.",
	["DELVE_CHAT_GULF_OF_MEMORY_BOSS"] = "Lumenia : tue l'add de {SPELL:@radiant_command} avant qu'il ne t'atteigne. Mul'tha'ul : dissipe {SPELL:@hopeless_curse}, kite {SPELL:@tear_it_down}, méfie-toi d'{SPELL:@unanswered_call}.",
	["DELVE_CHAT_GRUDGE_PIT_OVERVIEW"] = "Delve arène au SE d'Harandar. Champion / Rotstalk / Invasion / Pharmacon. Boss : Brightthorn, Gyrospore, Mycomight ou Replicating Venomborne.",
	["DELVE_CHAT_GRUDGE_PIT_ROUTE"] = "Champion : arène par vagues (les Sporbits aident). Rotstalk : dégage les fans, provoque la foule. Invasion : libère des combattants, fais sauter les points d'apparition.",
	["DELVE_CHAT_GRUDGE_PIT_TRASH"] = "Sers-toi des Sporbits dans l'arène. Nettoie les vagues d'invasion. N'ignore pas les fans de Rotstalk.",
	["DELVE_CHAT_GRUDGE_PIT_BOSS"] = "Brightthorn : esquive {SPELL:@solar_charge}, interromps Bloom Thorn, détourne-toi de {SPELL:@blinding_burst}. Gyrospore : esquive {SPELL:@fungalstorm}, burst quand il est étourdi. Mycomight : les flaques loin du combat.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_OVERVIEW"] = "Est de Voidstorm. Variantes Core / Not Expected / Gravity. Boss : Esuritus (ou 3 Umbraroot, sans boss).",
	["DELVE_CHAT_SUNKILLER_SANCTUM_ROUTE"] = "Core : empêche les Domanaar de voler les orbes (buff vitesse + réduction de dégâts). Not Expected : 3 Corrupted Umbraroot. Gravity : les singularités font tomber les boucliers.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_TRASH"] = "Ramasse les orbes en Core. Not What I Expected : pull les 3 Corrupted Umbraroot un par un.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_BOSS"] = "Tous les Voidcallers morts avant {SPELL:@gorge}, sinon les cumuls de dégâts montent. Kick {SPELL:@calling_bolt}. {SPELL:@coalescing_malediction} finit en Voidcaller. Esquive {SPELL:@crushing_rift} (4 Voidcallers).",
	["DELVE_CHAT_SHADOWGUARD_POINT_OVERVIEW"] = "Ouest de Voidstorm. Calamitous / Wildlife / Stolen Mana contre les ethereals : boss Chief-Arcanist Patram. Basilisk Blitz : boss Disciple of Vashnik.",
	["DELVE_CHAT_SHADOWGUARD_POINT_ROUTE"] = "Calamitous: surcharge les stabilisateurs (Arcane Charges). Wildlife: libère les mobs avec soin. Mana: Galvanic Blast aux conteneurs tant que la Barrier tient. Basilisk Blitz: reconfigure les générateurs, tue 4 Energized Basilisks.",
	["DELVE_CHAT_SHADOWGUARD_POINT_TRASH"] = "Interromps les ethereals. Prévois ton trajet avant de porter une charge.",
	["DELVE_CHAT_SHADOWGUARD_POINT_BOSS"] = "Kick {SPELL:@void_bolt_patram}. Tue le Void Emissary avant {SPELL:@submit_to_the_void}, sinon c'est Patram qui prend le buff. Esquive {SPELL:@discordant_hymn}.",
	["DELVE_CHAT_TORMENTS_RISE_OVERVIEW"] = "Nemesis delve (Voidstorm). Règles de Tier ? / ??. Boss Nullaeus — Valeera en Healer conseillée en ??.",
	["DELVE_CHAT_TORMENTS_RISE_ROUTE"] = "Portail dédié (Maj-J / TomTom). Ce n'est pas un delve de monde en rotation.",
	["DELVE_CHAT_TORMENTS_RISE_TRASH"] = "Garde tes cooldowns pour Nullaeus — pas de trash Pactsworn à l'intérieur.",
	["DELVE_CHAT_TORMENTS_RISE_BOSS"] = "Kick chaque {SPELL:@devouring_essence}. {SPELL:@dread_portal} : AoE sur les adds jusqu'à ce qu'ils meurent. {SPELL:@oblivion_shell} = DPS check. Ne laisse pas {SPELL:@umbral_rage} monter.",
})

merge(ns._mhLocales and ns._mhLocales.esES, {
	["DELVE_CHAT_ATAL_AMAN_BOSS"] = "{SPELL:@flaying_knife} deja espíritus = +10% de daño cada uno, recoge los tuyos. Esquiva {SPELL:@raging_spirits}. Antes de {SPELL:@claim_spirits}, recoge los espíritus o se los queda Jin'Ma.",
	["DELVE_CHAT_ATAL_AMAN_OVERVIEW"] = "Oeste de Zul'Aman. Ritual / Toadly / Totem: jefe Spiritflayer Jin'Ma. Venomous Vapors: jefe Disciple of Vashnik.",
	["DELVE_CHAT_ATAL_AMAN_ROUTE"] = "Ritual: rescata a los fúrbolgs. Toadly: Hex Stick sobre los Amani hechizados. Totem: destruye tótems y libera a Akil'zon.",
	["DELVE_CHAT_ATAL_AMAN_TRASH"] = "Interrumpe a los Vilebranch. Variante Totem: primero los tótems del camino.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_BOSS"] = "Hydrangea: mata {SPELL:@wildroot_weave} antes de {SPELL:@lightbloom_salvo}. Garand: esquiva {SPELL:@shadow_laceration}, sepárate en {SPELL:@twilight_crash}. Vagrant: corta {SPELL:@terrifying_power}.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_OVERVIEW"] = "NO de Lunargenta / Canción Eterna (la universidad). Siege, Faculty y Glow acaban cada una en un jefe. Academic Antitoxin no tiene jefe, solo un cofre.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_ROUTE"] = "Siege: cierra los portales del Vacío. Faculty: Eye of Revelation, estudiantes amarillos a través de las paredes. Glow: Deweeder + Luminibulb. Antitoxin: 10 tomos, ingredientes, cura a 7.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_TRASH"] = "Siege: primero los portales. Faculty: revela y luego mata a los estudiantes. Glow: canaliza el Deweeder en movimiento.",
	["DELVE_CHAT_GRUDGE_PIT_BOSS"] = "Brightthorn: esquiva {SPELL:@solar_charge}, interrumpe Bloom Thorn, date la vuelta en {SPELL:@blinding_burst}. Gyrospore: esquiva {SPELL:@fungalstorm}, burst cuando esté mareado. Mycomight: deja los charcos lejos de la pelea.",
	["DELVE_CHAT_GRUDGE_PIT_OVERVIEW"] = "Delve de arena en el SE de Harandar. Champion / Rotstalk / Invasion / Pharmacon. Jefes: Brightthorn, Gyrospore, Mycomight o Replicating Venomborne.",
	["DELVE_CHAT_GRUDGE_PIT_ROUTE"] = "Champion: arena por oleadas (los Sporbits ayudan). Rotstalk: patea a los fans y provoca al público. Invasion: libera luchadores y vuela los puntos de aparición.",
	["DELVE_CHAT_GRUDGE_PIT_TRASH"] = "Usa los Sporbits en la arena. Elimina las oleadas de la invasión. No ignores a los fans de Rotstalk.",
	["DELVE_CHAT_GULF_OF_MEMORY_BOSS"] = "Lumenia: mata el add de {SPELL:@radiant_command} antes de que te alcance. Mul'tha'ul: disipa {SPELL:@hopeless_curse}, kitea {SPELL:@tear_it_down}, respeta {SPELL:@unanswered_call}.",
	["DELVE_CHAT_GULF_OF_MEMORY_OVERVIEW"] = "Oeste de Harandar. Munchies / Descent / Sporasaur. Jefes: Lumenia o Mul'tha'ul.",
	["DELVE_CHAT_GULF_OF_MEMORY_ROUTE"] = "Munchies: Alnmoth Storm en movimiento. Descent: enciende velas, evita la oscuridad. Sporasaur: patea los Sporbits contra los mobs con escudo.",
	["DELVE_CHAT_GULF_OF_MEMORY_TRASH"] = "Quédate en la luz en Descent. Patea los Sporbits pronto. Puedes moverte mientras canalizas la tormenta.",
	["DELVE_CHAT_PARHELION_PLAZA_BOSS"] = "Mata rápido a los 3 Voidcallers (corta Void Bolt). Si uno sobrevive a {SPELL:@devouring_nova}, Slaurna se potencia mucho. Esquiva {SPELL:@voidscar_raze} y pelea en el centro.",
	["DELVE_CHAT_PARHELION_PLAZA_OVERVIEW"] = "Oeste de la Isla de Quel'Danas (La Fuente del Sol), una Delve difícil. Bombing Run / Holding the Line / Brigade: jefe Gladius Slaurna. Caustic Crush: destruye el Ritual Pillar.",
	["DELVE_CHAT_PARHELION_PLAZA_ROUTE"] = "Bombing Run: dispositivo arcano para los portales (40 s llevándolo). Holding the Line: armas + barricadas. Brigade: centinelas contra pilones. Caustic Crush: mata Slimecallers y Wavecallers.",
	["DELVE_CHAT_PARHELION_PLAZA_TRASH"] = "Corta el Void Bolt de los Voidcaller. Elimina las oleadas de Devouring Host antes del jefe.",
	["DELVE_CHAT_SHADOWGUARD_POINT_BOSS"] = "Corta {SPELL:@void_bolt_patram}. Mata al Void Emissary antes de {SPELL:@submit_to_the_void} o el beneficio se lo queda Patram. Esquiva {SPELL:@discordant_hymn}.",
	["DELVE_CHAT_SHADOWGUARD_POINT_OVERVIEW"] = "Oeste de Voidstorm. Calamitous / Wildlife / Stolen Mana contra etéreos: jefe Chief-Arcanist Patram. Basilisk Blitz: jefe Disciple of Vashnik.",
	["DELVE_CHAT_SHADOWGUARD_POINT_ROUTE"] = "Calamitous: sobrecarga estabilizadores con Arcane Charges. Wildlife: libera mobs con cuidado. Mana: Galvanic Blast a contenedores hasta que caiga la Barrier. Basilisk Blitz: reconfigura generadores, mata 4 Energized Basilisks.",
	["DELVE_CHAT_SHADOWGUARD_POINT_TRASH"] = "Interrumpe a los etéreos. Planifica con cuidado por dónde llevas las cargas.",
	["DELVE_CHAT_SHADOW_ENCLAVE_BOSS"] = "Corta {SPELL:@shadow_bolt}. El teletransporte deja un charco: mantenlo en el centro. {SPELL:@shadowveil_annihilation}: mata 3 orbes (solo el que no tiene escudo). Burst a los orbes.",
	["DELVE_CHAT_SHADOW_ENCLAVE_OVERVIEW"] = "SO de Canción Eterna (Deatholme). Espejos, suministros, traidor: jefe Lord Antenorian. Infiltrate and Ameliorate: jefe Abominable Blunder.",
	["DELVE_CHAT_SHADOW_ENCLAVE_ROUTE"] = "Espejos: golpea los Shadow Nexuses para tener luz. Suministros: saquea los objetos de Twilight's Blade. Traidor: detén los rituales y persíguelo hasta el jefe.",
	["DELVE_CHAT_SHADOW_ENCLAVE_TRASH"] = "Luz de espejo = Dazzled (más críticos). Interrumpe a los lanzadores de sombras. No te apiles en terreno malo.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_BOSS"] = "Todos los Voidcallers muertos antes de {SPELL:@gorge} o acumula +daño. Corta {SPELL:@calling_bolt}. {SPELL:@coalescing_malediction} acaba en un Voidcaller. Esquiva {SPELL:@crushing_rift} (4 Voidcallers).",
	["DELVE_CHAT_SUNKILLER_SANCTUM_OVERVIEW"] = "Este de Voidstorm. Variantes Core / Not Expected / Gravity. Jefe: Esuritus (o 3 Umbraroot, sin jefe).",
	["DELVE_CHAT_SUNKILLER_SANCTUM_ROUTE"] = "Core: impide que los Domanaar roben orbes (velocidad + reducción de daño). Not Expected: 3 Corrupted Umbraroot. Gravity: las singularidades quitan escudos.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_TRASH"] = "Recoge orbes en Core. Not What I Expected: pullea a los 3 Corrupted Umbraroot de uno en uno.",
	["DELVE_CHAT_THE_DARKWAY_BOSS"] = "Corta a los Seekers. Esquiva {SPELL:@abyssal_burst}. {SPELL:@illusory_deceit}: aléjate de las ilusiones que explotan.",
	["DELVE_CHAT_THE_DARKWAY_OVERVIEW"] = "Arcway, norte de Lunargenta. Focusers, Leyline o 7 Aberrations: jefe Infiltrator Gulkat. Eggsplosive Growth: jefe Replicating Venomborne.",
	["DELVE_CHAT_THE_DARKWAY_ROUTE"] = "Focusers: devuelve los focalizadores ley al centro. Leyline: activa los conductos para 3 cristales. Ogre: mata 7 Unstable Aberrations en la zona central.",
	["DELVE_CHAT_THE_DARKWAY_TRASH"] = "Interrumpe a los Twilight Seekers y el Arcane Deluge. Saca los pulls de las esquinas estrechas.",
	["DELVE_CHAT_TORMENTS_RISE_BOSS"] = "Corta cada {SPELL:@devouring_essence}. {SPELL:@dread_portal}: AoE a los adds hasta que mueran. {SPELL:@oblivion_shell} = prueba de DPS. No dejes acumular {SPELL:@umbral_rage}.",
	["DELVE_CHAT_TORMENTS_RISE_OVERVIEW"] = "Nemesis Delve (Voidstorm). Reglas de Tier ? / ??. Jefe Nullaeus — Valeera de sanadora recomendada en ??.",
	["DELVE_CHAT_TORMENTS_RISE_ROUTE"] = "Portal propio (Shift-J / TomTom). No es una Delve del mundo rotativa.",
	["DELVE_CHAT_TORMENTS_RISE_TRASH"] = "Guarda los CD para Nullaeus — dentro no hay trash Pactsworn.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_BOSS"] = "Esquiva {SPELL:@shade_cleave} (a melé evitas {SPELL:@dark_pursuit}). Saca a Darza de {SPELL:@bask_in_the_twilight} (+30% de daño dentro).",
	["DELVE_CHAT_TWILIGHT_CRYPTS_OVERVIEW"] = "SO de Zul'Aman (Broken Throne). Loa / Party Crasher / Trapped: jefe Blademaster Darza. Why'd it have to be snakes?: jefe Replicating Venomborne.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_ROUTE"] = "Loa: no te cruces en el camino de Mot'amra. Party Crasher: escolta, trampas, palancas. Trapped: rehenes + palancas.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_TRASH"] = "Mot'amra = empujón fuerte si te pones en su camino. Interrumpe a los invocadores. Vigila las baldosas con trampa.",
	["DELVE_NAME_ATAL_AMAN"] = "Atal'Aman",
	["DELVE_NAME_COLLEGIATE_CALAMITY"] = "Collegiate Calamity",
	["DELVE_NAME_GRUDGE_PIT"] = "The Grudge Pit",
	["DELVE_NAME_GULF_OF_MEMORY"] = "The Gulf of Memory",
	["DELVE_NAME_PARHELION_PLAZA"] = "Parhelion Plaza",
	["DELVE_NAME_SHADOWGUARD_POINT"] = "Shadowguard Point",
	["DELVE_NAME_SHADOW_ENCLAVE"] = "The Shadow Enclave",
	["DELVE_NAME_SUNKILLER_SANCTUM"] = "Sunkiller Sanctum",
	["DELVE_NAME_THE_DARKWAY"] = "The Darkway",
	["DELVE_NAME_TORMENTS_RISE"] = "Torment's Rise",
	["DELVE_NAME_TWILIGHT_CRYPTS"] = "Twilight Crypts",
	["DELVE_TIP_ATAL_AMAN_BOSS"] = "• {SPELL:@flaying_knife} divide espíritus: cada espíritu que recojas te da +10% de daño (recógelos a propósito).|n• Esquiva {SPELL:@raging_spirits} en el suelo.|n• Antes de que acabe {SPELL:@claim_spirits}, recoge tus espíritus o Jin'Ma se quedará con su beneficio.|n• Disciple of Vashnik: interrumpe siempre {SPELL:@malignance}, una ráfaga de 4 segundos de glóbulos de veneno que acumulan daño y te ralentizan. Valeera no lo interrumpe todas las veces, así que hazlo tú.|n• Disciple of Vashnik: {SPELL:@toxic_froth} hace mucho daño de veneno durante 8 segundos, y esconderte detrás de una pared ya no sirve. Quita el veneno si tu clase puede, usa un defensivo o pon a Valeera de sanadora; después recoge los orbes de sanación.|n• Disciple of Vashnik: {SPELL:@living_venom} te empuja hacia atrás e invoca un limo. Sal de la zona que lo rodea y mata al limo antes de que te alcance. En Tier 11 muchos jugadores lo consideran el jefe más difícil de la temporada: baja un tier si no paras de morir.",
	["DELVE_TIP_ATAL_AMAN_OVERVIEW"] = "• Oeste de Zul'Aman (frontera con Canción Eterna).|n• Ritual Interrupted, Toadly Unbecoming y Totem Annihilation.|n• Ritual Interrupted, Toadly Unbecoming y Totem Annihilation acaban en Spiritflayer Jin'Ma.|n• Temporada 2, Venomous Vapors: jefe final Disciple of Vashnik (también en Shadowguard Point).",
	["DELVE_TIP_ATAL_AMAN_ROUTE"] = "• Ritual: rescata a los fúrbolgs Spiritpaw secuestrados por toda la Delve.|n• Toadly: disipa a los Amani hechizados con el Vilebranch Hex Stick mientras matas a los invasores.|n• Totem: destruye los tótems malditos para liberar a Akil'zon; usa las águilas para llegar por otras rutas.|n• Venomous Vapors: abre los 2 cofres de la primera sala y recoge las herramientas de Marla: {SPELL:@venomous_fireball}, que lanzas a una Toxic Cloud para hacerla explotar (apártate), y una herramienta que te hace saltar muy alto. Derrota a las 5 Venom Vipers; el Disciple of Vashnik te espera al final.",
	["DELVE_TIP_ATAL_AMAN_TRASH"] = "• Interrumpe los lanzamientos de los Vilebranch.|n• Variante Totem: prioriza los tótems que están en tu camino.|n• Aleja a las bestias de los PNJ hechizados que intentas salvar.|n• Venomous Vapors: las Venom Vipers forman parte del objetivo, así que mata a las 5.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_BOSS"] = "• Hydrangea (Glow): mata las raíces de {SPELL:@wildroot_weave} antes de {SPELL:@lightbloom_salvo}; esquiva las zonas de luz.|n• Garand (Faculty): esquiva {SPELL:@shadow_laceration} o usa una defensiva; sepárate para los saltos de {SPELL:@twilight_crash}.|n• Voidscorned Vagrant (Siege): apártate de {SPELL:@void_eruption}; interrumpe siempre {SPELL:@terrifying_power}.|n• Academic Antitoxin: no hay jefe final. El tesoro aparece cuando terminas el último paso.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_OVERVIEW"] = "• Noroeste de Lunargenta / Bosques de Canción Eterna (Thalassian University).|n• Academy Under Siege -> Voidscorned Vagrant.|n• Faculty of Fear -> Infiltrator Garand.|n• Invasive Glow -> Hydrangea.|n• Academic Antitoxin (en el mapa: An Elementary Antidote): sin jefe final. En su lugar aparece un tesoro.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_ROUTE"] = "• Under Siege: cierra los portales del Vacío y mata a los Devouring Host.|n• Faculty of Fear: Eye of Revelation — los estudiantes sospechosos brillan en amarillo a través de las paredes.|n• Invasive Glow: el Deweeder mata a los Lightbloom pequeños y daña a los grandes.|n• Limpia las zonas de Luminibulb del nivel principal.|n• Academic Antitoxin: habla con Sir Finley Mrrgglton y luego reúne 10 Research Tomes.|n• Academic Antitoxin: luego recoge ingredientes y dale el antídoto a 7 Envenomed Denizens. Las dos cosas cuentan a la vez.|n• Academic Antitoxin: la barra de ingredientes necesita 400. Los ingredientes pequeños dan 2, los medianos 20 y los grandes 35, así que coge los grandes.|n• Academic Antitoxin: {SPELL:@fungal_pharmacon} limpia los charcos de veneno y además golpea a los enemigos a 5 metros o menos de donde cae.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_TRASH"] = "• Under Siege: céntrate primero en cerrar los portales.|n• Faculty: revela a los estudiantes disfrazados y mátalos antes de que te embosquen.|n• Glow: canaliza el Deweeder mientras te mueves.|n• No te saltes las zonas de Luminibulb o la run se alargará mucho.",
	["DELVE_TIP_GRUDGE_PIT_BOSS"] = "• Brightthorn: apártate de {SPELL:@solar_charge} (deja zonas de Overbloom); interrumpe {SPELL:@bloom_thorn}; date la vuelta antes de {SPELL:@blinding_burst}.|n• Gyrospore: esquiva las zonas de {SPELL:@fungalstorm} y suelta el burst durante los 10 s que está mareado; aléjate de {SPELL:@fungsplosion}; apártate de {SPELL:@fungal_charge}.|n• Mycomight: deja los charcos de {SPELL:@rancid_rain} lejos de la zona de pelea; esquiva las ondas de choque de {SPELL:@fungis_fist}; apártate de {SPELL:@fling_chair}.|n• Replicating Venomborne: mata enseguida a los Lesser Venomborne de {SPELL:@serpentogenesis} — si siguen vivos en su siguiente lanzamiento, lo curan; sal de los charcos de {SPELL:@venom_splash_venomborne} (daño + ralentización); {SPELL:@hydra_strike} deja un DoT que se acumula.|n• Gyrospore: DBM y tu historial de Delves llaman a este combate Spinshroom, un nombre que Blizzard reutilizó de un jefe antiguo. Es el mismo combate.",
	["DELVE_TIP_GRUDGE_PIT_OVERVIEW"] = "• Sudeste de Harandar.|n• Lightbloom Invasion -> Brightthorn.|n• Arena Champion -> Gyrospore.|n• Dastardly Rotstalk -> Mycomight.|n• Fungal Pharmacon -> Replicating Venomborne.",
	["DELVE_TIP_GRUDGE_PIT_ROUTE"] = "• Arena Champion: dale una paliza a los luchadores, mata a Bogdamp, Moldrus y 5 Spewing Deathcaps, recoge 6 Mold Samples y planta tu estandarte. Luego llega Gyrospore.|n• Dastardly Rotstalk: haz de villano — patea a los fans y provoca al público (puedes moverte mientras provocas).|n• Lightbloom Invasion: oleadas, libera luchadores para volar los puntos de aparición y monta defensas.",
	["DELVE_TIP_GRUDGE_PIT_TRASH"] = "• Arena Champion: usa los Sporbits aliados. Hacen daño extra a los luchadores de la arena.|n• Lightbloom Invasion: elimina las oleadas antes del jefe.|n• Rotstalk: mantén controlado al público — los fans hacen daño si los ignoras.",
	["DELVE_TIP_GULF_OF_MEMORY_BOSS"] = "• Lumenia: mata al add de {SPELL:@radiant_command} antes de que te alcance (explota).|n• Esquiva las zonas de {SPELL:@searing_light}, salvo que las uses sobre el add.|n• Mul'tha'ul: interrumpe o disipa {SPELL:@hopeless_curse}.|n• Kitea lejos de los tentáculos de {SPELL:@tear_it_down}.|n• Mantén la distancia durante {SPELL:@unanswered_call} (mucho daño, avanza despacio).",
	["DELVE_TIP_GULF_OF_MEMORY_OVERVIEW"] = "• Oeste de Harandar (Den of Echoes / Har'alnor).|n• Tres variantes.|n• Jefes: Lumenia (Munchies / Sporasaur) y Mul'tha'ul (Descent of the Haranir).",
	["DELVE_TIP_GULF_OF_MEMORY_ROUTE"] = "• Alnmoth Munchies: usa el Alnmoth Storm de acción extra en movimiento — devora arbustos o úsalo contra los Rutaani.|n• Descent: enciende las velas gigantes; recibes más daño en las zonas oscuras.|n• Sporasaur: patea los Sporbits con retícula verde contra los Sporasaurs para quitarles el escudo.",
	["DELVE_TIP_GULF_OF_MEMORY_TRASH"] = "• Quédate en las zonas iluminadas durante Descent.|n• Patea a los Sporbits antes de que exploten.|n• Canaliza el Alnmoth Storm en movimiento — puedes moverte y lanzarlo a la vez.",
	["DELVE_TIP_PARHELION_PLAZA_BOSS"] = "• Gladius Slaurna: mata rápido a sus tres Sacrificial Voidcallers e interrumpe su Void Bolt.|n• Gladius Slaurna: cada Voidcaller que siga vivo cuando acabe {SPELL:@devouring_nova} hace que pegue más fuerte y reciba menos daño. En Tiers altos eso puede acabar en wipe.|n• Gladius Slaurna: sal de la línea de {SPELL:@voidscar_raze}. A menudo apunta a Valeera, así que no te pongas entre ellos.|n• Gladius Slaurna: pelea cerca del centro, para que {SPELL:@devouring_nova} no pueda tirarte de la plataforma.",
	["DELVE_TIP_PARHELION_PLAZA_OVERVIEW"] = "• Oeste de la Isla de Quel'Danas (zona de La Fuente del Sol).|n• Se desbloquea con March on Quel'Danas (finales de marzo de 2026).|n• Bombing Run, Holding the Line y March of the Arcane Brigade acaban en Gladius Slaurna.|n• Una de las Delves más difíciles de Midnight.|n• Caustic Crush (nueva en 12.1): los Slime Shamen of Ula'tek invocan limos y mandan olas de veneno. El último objetivo es un Ritual Pillar, no Gladius Slaurna.",
	["DELVE_TIP_PARHELION_PLAZA_ROUTE"] = "• Bombing Run: Improvised Arcane Device para los portales del Vacío (solo puedes llevarlo 40 s; se te cae en combate).|n• Holding the Line: armas de la Fortaleza de la Tempestad + reconstruye las barricadas.|n• March of the Arcane Brigade: despierta a las máquinas Sentinel; caminan hacia los pilones del Vacío. Destruye 3 pilones y mata a Devouring Host para llenar la barra.|n• Caustic Crush: habla con Vindicator Xayann. Luego mata a los limos, a 4 Shaman Slimecallers y a 6 Ula'tek Wavecallers.|n• Caustic Crush: coge {SPELL:@fungal_pharmacon} por el camino. Lánzalo sobre los Ula'tek Poison Pools para limpiarlos. También daña a los enemigos cerca de donde cae.|n• Caustic Crush: los objetivos también te piden usar una madriguera. El último objetivo de todos es destruir el Ritual Pillar.",
	["DELVE_TIP_PARHELION_PLAZA_TRASH"] = "• Bombing Run: nunca salgas de un portal antes de volarlo. Se cierra para siempre y ya no puedes terminar la run.|n• Elimina las oleadas de Devouring Host antes de Slaurna.|n• Caustic Crush: esquiva cada ola de veneno. Un golpe te aturde y hace mucho daño de naturaleza.",
	["DELVE_TIP_SHADOWGUARD_POINT_BOSS"] = "• Interrumpe {SPELL:@void_bolt_patram}.|n• Mata al Void Emissary antes de que acabe {SPELL:@submit_to_the_void} (te llevas Vers + CDR; si fallas, el beneficio se lo queda Patram).|n• Apártate de las zonas de Vacío de {SPELL:@discordant_hymn} (ralentiza y hace daño).|n• Disciple of Vashnik: interrumpe siempre {SPELL:@malignance}, una ráfaga de 4 segundos de glóbulos de veneno que acumulan daño y te ralentizan. Valeera no lo interrumpe todas las veces, así que hazlo tú.|n• Disciple of Vashnik: {SPELL:@toxic_froth} hace mucho daño de veneno durante 8 segundos, y esconderte detrás de una pared ya no sirve. Quita el veneno si tu clase puede, usa un defensivo o pon a Valeera de sanadora; después recoge los orbes de sanación.|n• Disciple of Vashnik: {SPELL:@living_venom} te empuja hacia atrás e invoca un limo. Sal de la zona que lo rodea y mata al limo antes de que te alcance. En Tier 11 muchos jugadores lo consideran el jefe más difícil de la temporada: baja un tier si no paras de morir.",
	["DELVE_TIP_SHADOWGUARD_POINT_OVERVIEW"] = "• Oeste de Voidstorm (al norte de Abundant Voidburrow).|n• Cuatro variantes. En tres luchas contra los Shadowguard Ethereals; en Basilisk Blitz les ayudas a recuperar el punto.|n• Jefe final en tres variantes: Chief-Arcanist Patram. Basilisk Blitz acaba en cambio en el Disciple of Vashnik.|n• Temporada 2, Basilisk Blitz: jefe final Disciple of Vashnik (también en Atal'Aman).",
	["DELVE_TIP_SHADOWGUARD_POINT_ROUTE"] = "• Calamitous: sobrecarga los Void Stabilizers con Arcane Charges (dan velocidad; las explosiones matan a los mobs, así que no te quedes dentro).|n• Captured Wildlife: libera a las criaturas del Vacío (su AoE también te alcanza a ti).|n• Stolen Mana: coge el rifle y usa Galvanic Blast en los contenedores de maná hasta que caiga la Arcane Barrier.|n• Basilisk Blitz: habla con el etéreo herido al principio. Luego reconfigura el Energy Distributor y mata al Ula'tek Basilisk.|n• Basilisk Blitz: usa el Waygate para avanzar. Luego reconfigura los 4 Power Generators y mata a los 4 Energized Basilisks.|n• Basilisk Blitz: el Disciple of Vashnik solo pasa a ser tu objetivo cuando han muerto los 4 Energized Basilisks.",
	["DELVE_TIP_SHADOWGUARD_POINT_TRASH"] = "• Calamitous: planifica bien dónde sobrecargas mientras llevas las Arcane Charges.|n• Grupos de etéreos: interrumpe sus lanzamientos.|n• Variante Wildlife: deja espacio a las criaturas liberadas.|n• Basilisk Blitz: mientras aguanta la barrera de un basilisco, te lanza descargas de veneno. Si entras en la barrera, te aturde unos segundos.",
	["DELVE_TIP_SHADOW_ENCLAVE_BOSS"] = "• Lord Antenorian: interrumpe {SPELL:@shadow_bolt} siempre que puedas.|n• Lord Antenorian: sus teletransportes dejan un charco que hace daño. Mantenlo cerca del centro.|n• Lord Antenorian: {SPELL:@shadowveil_annihilation} es una canalización letal. Destruye los 3 Shadow Orbs: solo el orbe sin escudo recibe daño, y cada muerte quita el siguiente escudo.|n• Lord Antenorian: con todos los orbes muertos se rompe su escudo, se corta la canalización y recibe daño extra durante unos segundos.|n• Lord Antenorian: guarda el burst para los orbes. Valeera ayuda a romperlos.|n• Abominable Blunder (Infiltrate and Ameliorate): Corrosive Bile es su ataque básico de veneno. Aguántalo con curación.|n• Abominable Blunder (Infiltrate and Ameliorate): {SPELL:@searing_spew} daña y ralentiza a todos a 14 metros o menos de él. Aléjate cuando lo lance.|n• Abominable Blunder (Infiltrate and Ameliorate): Acid Spray lanza olas de ácido durante unos segundos. Sigue esquivando de lado hasta que acabe.",
	["DELVE_TIP_SHADOW_ENCLAVE_OVERVIEW"] = "• Suroeste de los Bosques de Canción Eterna (Ruins of Deatholme).|n• Cuatro variantes: Mirror Shine, Shadowy Supplies, Traitor's Due e Infiltrate and Ameliorate (nueva en 12.1).|n• Traitor's Due: detén los rituales, los orbes del Vacío y los cultistas (mientras subes de nivel).|n• Mirror Shine, Shadowy Supplies y Traitor's Due acaban en Lord Antenorian. Infiltrate and Ameliorate acaba en Abominable Blunder.",
	["DELVE_TIP_SHADOW_ENCLAVE_ROUTE"] = "• Mirror Shine: lleva los espejos por los pasillos oscuros; golpea los Shadow Nexuses para extender la luz (así evitas a los grues).|n• Shadowy Supplies: saquea los objetos de valor de Twilight's Blade de los mobs o del suelo.|n• Traitor's Due: persigue a Antenorian por la Delve hasta la sala del jefe.|n• Infiltrate and Ameliorate: habla con Scout Lok'aemon y luego tira de una patada a 5 Ula'tek Summoners al abismo.|n• Infiltrate and Ameliorate: sabotea 4 calderos echándoles ingredientes raros. Algunos ingredientes están en lo alto: usa las setas saltarinas.|n• Infiltrate and Ameliorate: después, mata al Ula'tek Supreme Summoner y observa la invocación. Luego llega Abominable Blunder, el jefe final.|n• Infiltrate and Ameliorate: coge {SPELL:@fungal_pharmacon} y lánzalo sobre los charcos de veneno para limpiarlos. También daña a los enemigos cerca de donde cae.",
	["DELVE_TIP_SHADOW_ENCLAVE_TRASH"] = "• Con la luz del espejo, tanto tú como los enemigos quedáis Dazzled (más probabilidad de crítico).|n• Interrumpe a los lanzadores de sombras.|n• Elimina a los Twilight's Blade durante Shadowy Supplies.|n• No te apiles en terreno peligroso; haz los pulls con cuidado en los pasillos estrechos.",
	["DELVE_TIP_SUNKILLER_SANCTUM_BOSS"] = "• Mata a todos los Voidcallers antes de {SPELL:@gorge} o ganará +daño durante 30 s por cada uno que devore.|n• Interrumpe {SPELL:@calling_bolt}.|n• Cuando {SPELL:@coalescing_malediction} termina o se disipa, aparece un Voidcaller. Disípalo solo cuando estés listo para matar a ese add.|n• Esquiva {SPELL:@crushing_rift} (genera 4 Voidcallers).",
	["DELVE_TIP_SUNKILLER_SANCTUM_OVERVIEW"] = "• Este de Voidstorm (entrada de Voidspire).|n• Core of the Problem y The Gravitational Effect acaban en Esuritus. Not What I Expected no tiene jefe.|n• Not What I Expected: sin jefe — termina cuando matas 3 Corrupted Umbraroot.",
	["DELVE_TIP_SUNKILLER_SANCTUM_ROUTE"] = "• Core of the Problem: portales + impide que los Domanaar roben los Energized Orbs (el orbe da velocidad y reducción de daño).|n• Not What I Expected: pulsa 7 Lightbloom Crates, usa el Sanctum Security Panel y llena la barra de muertes (cuentan tanto los enemigos Lightbloom como los del Vacío). Luego mata a 3 Corrupted Umbraroot.|n• Gravitational Effect: usa las microsingularidades para moverte y para quitarle los escudos al jefe.|n• Not What I Expected: atraviesa un Displacement Portal. Después, una copia de ti pelea a tu lado durante unos 5 minutos.",
	["DELVE_TIP_SUNKILLER_SANCTUM_TRASH"] = "• Recoge orbes en la variante Core para aguantar mejor.|n• Not What I Expected: los 3 Corrupted Umbraroot son élites. Pulléalos de uno en uno.|n• Not What I Expected: interrumpe el Lightbloom Beam de los Corrupted Umbraroot, y esquiva Blooming Bile (un frontal que genera adds) y Rotting Charge (deja un charco).",
	["DELVE_TIP_THE_DARKWAY_BOSS"] = "• Interrumpe a los Twilight Seekers.|n• Esquiva {SPELL:@abyssal_burst} (cono frontal).|n• {SPELL:@illusory_deceit}: ilusiones que explotan — mantén la distancia mientras te ocupas de Gulkat.|n• Replicating Venomborne: mata enseguida a los Lesser Venomborne de {SPELL:@serpentogenesis} — si siguen vivos en su siguiente lanzamiento, lo curan; sal de los charcos de {SPELL:@venom_splash_venomborne} (daño + ralentización); {SPELL:@hydra_strike} deja un DoT que se acumula.",
	["DELVE_TIP_THE_DARKWAY_OVERVIEW"] = "• Norte de Lunargenta / Bosques de Canción Eterna (el Arcway).|n• Focusers Under Pressure, Leyline Technician y Ogre Powered (7 Unstable Aberrations).|n• Focusers, Leyline, Ogre Powered -> Infiltrator Gulkat.|n• Eggsplosive Growth (12.1) -> Replicating Venomborne.",
	["DELVE_TIP_THE_DARKWAY_ROUTE"] = "• Focusers: busca los focalizadores de líneas ley y llévalos al centro de la Delve.|n• Leyline: activa los conductos una vez por línea para potenciar tres cristales de enfoque.|n• Ogre Powered: mata a 7 Unstable Aberrations en la sección central antes de Gulkat.",
	["DELVE_TIP_THE_DARKWAY_TRASH"] = "• Interrumpe a los Twilight Seekers y el Arcane Deluge de las aberraciones.|n• Variante Leyline: mata a los Twilight's Blade mientras encauzas la energía.|n• Haz los pulls lejos de las esquinas en los pasillos estrechos del Arcway.",
	["DELVE_TIP_TORMENTS_RISE_BOSS"] = "• Interrumpe {SPELL:@devouring_essence} en cada lanzamiento (pone un DoT y alimenta las acumulaciones de {SPELL:@umbral_rage}).|n• {SPELL:@dread_portal}: 100% de reducción de daño hasta que mueran todos los adds — suelta todo el AoE en cuanto aparezcan.|n• La fase de {SPELL:@oblivion_shell} es una prueba de DPS.|n• {SPELL:@umbral_rage}: +10% de daño por acumulación si quedan adds o DoTs — mata los adds rápido.",
	["DELVE_TIP_TORMENTS_RISE_OVERVIEW"] = "• Voidstorm — Nemesis Delve de la Temporada 1 (el reto final).|n• Tier ? tras cualquier T7 acabado con 1 vida o más; Tier ?? tras cualquier T10 con 1 vida o más.|n• Jefe: Nullaeus.|n• Muy recomendable llevar a Valeera de sanadora en Tier ??.",
	["DELVE_TIP_TORMENTS_RISE_ROUTE"] = "• Tiene su propio portal de instancia (no es una Delve del mundo rotativa).|n• Usa la Guía de aventuras (Shift-J) o TomTom.|n• Recompensa semanal: Beacon of Hope puede sacar a Nullaeus a una Delve normal al 50%.",
	["DELVE_TIP_TORMENTS_RISE_TRASH"] = "• Los mobs Pactsworn están en las Delves normales, no dentro de Torment's Rise.|n• Dosifica los cooldowns: guarda defensivas e interrupciones para Nullaeus.",
	["DELVE_TIP_TWILIGHT_CRYPTS_BOSS"] = "• Blademaster Darza: apártate de {SPELL:@shade_cleave}. Pelear pegado a ella evita el acercamiento de {SPELL:@dark_pursuit}.|n• Blademaster Darza: {SPELL:@bask_in_the_twilight} deja una zona de Vacío en el suelo.|n• Saca a Darza de ahí o ganará +30% de daño mientras siga dentro.|n• Replicating Venomborne (Why'd it have to be snakes?): mata enseguida a los Lesser Venomborne de {SPELL:@serpentogenesis}. Si siguen vivos en su siguiente lanzamiento, lo curan.|n• Replicating Venomborne (Why'd it have to be snakes?): sal de los charcos de {SPELL:@venom_splash_venomborne}. Hacen daño y te ralentizan.|n• Replicating Venomborne (Why'd it have to be snakes?): {SPELL:@hydra_strike} te deja daño de veneno que se acumula. Vigila las acumulaciones y aguántalo con curación.",
	["DELVE_TIP_TWILIGHT_CRYPTS_OVERVIEW"] = "• Suroeste de Zul'Aman (Broken Throne).|n• Loosed Loa (evita a Mot'amra), Party Crasher, Trapped! y, nueva en 12.1: Why'd it have to be snakes?|n• Loosed Loa, Party Crasher y Trapped! acaban en Blademaster Darza. Why'd it have to be snakes? acaba en Replicating Venomborne.",
	["DELVE_TIP_TWILIGHT_CRYPTS_ROUTE"] = "• Loosed Loa: usa el Evasive Elixir para explorar; mata a los Skeleton Charmers y los tótems — vigila a Mot'amra y no te cruces en su camino.|n• Loosed Loa: desde la corrección del 10 de septiembre, en esta variante aparecen Explorer's League Supplies y una Abandoned Restoration Stone.|n• Party Crasher: mata a los 4 Twilight Summoners (salen en tu mapa) y acciona 7 Suspicious Levers. Los cepos te aturden unos 2 segundos.|n• Trapped: salva a los rehenes y busca las palancas por el laberinto.|n• Why'd it have to be snakes?: ayuda a Harrison Jones a encontrar las reliquias perdidas en las criptas.|n• Why'd it have to be snakes?: pisar las serpientes forma parte del objetivo, pero explotan cuando las pisas.|n• Why'd it have to be snakes?: coge {SPELL:@fungal_pharmacon} y lánzalo sobre las zonas de veneno para limpiarlas.",
	["DELVE_TIP_TWILIGHT_CRYPTS_TRASH"] = "• Mot'amra pega durísimo y te empuja si te metes en su camino.|n• Party Crasher: vigila las baldosas con trampa.|n• Interrumpe a los invocadores de Twilight's Blade.",
})

merge(ns._mhLocales and ns._mhLocales.ptBR, {
	["DELVE_CHAT_ATAL_AMAN_BOSS"] = "Os espíritos de {SPELL:@flaying_knife} = +10% de dano cada — recolha os seus. Desvie de {SPELL:@raging_spirits}. Antes de {SPELL:@claim_spirits}, recolha os espíritos ou Jin'Ma fica com o buff.",
	["DELVE_CHAT_ATAL_AMAN_OVERVIEW"] = "Oeste de Zul'Aman. Ritual / Toadly / Totem: chefe Spiritflayer Jin'Ma. Venomous Vapors: chefe Disciple of Vashnik.",
	["DELVE_CHAT_ATAL_AMAN_ROUTE"] = "Ritual: resgate os furbolgs. Toadly: Hex Stick nos Amani enfeitiçados. Totem: destrua os totens e liberte Akil'zon.",
	["DELVE_CHAT_ATAL_AMAN_TRASH"] = "Interrompa os Vilebranch. Na run de Totem: primeiro os totens do caminho.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_BOSS"] = "Hydrangea: mate {SPELL:@wildroot_weave} antes de {SPELL:@lightbloom_salvo}. Garand: desvie de {SPELL:@shadow_laceration}, espalhe-se em {SPELL:@twilight_crash}. Vagrant: kick em {SPELL:@terrifying_power}.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_OVERVIEW"] = "NO de Luaprata / Floresta do Canto Eterno (universidade). Siege, Faculty e Glow acabam cada uma num chefe. Academic Antitoxin não tem chefe, só um baú.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_ROUTE"] = "Siege: feche os portais do Caos. Faculty: Eye of Revelation, estudantes amarelos através das paredes. Glow: Deweeder + Luminibulb. Antitoxin: 10 tomos, ingredientes, cure 7.",
	["DELVE_CHAT_COLLEGIATE_CALAMITY_TRASH"] = "Siege: portais primeiro. Faculty: revele e depois mate os estudantes. Glow: canalize o Deweeder em movimento.",
	["DELVE_CHAT_GRUDGE_PIT_BOSS"] = "Brightthorn: desvie de {SPELL:@solar_charge}, interrompa Bloom Thorn, vire de costas para {SPELL:@blinding_burst}. Gyrospore: desvie de {SPELL:@fungalstorm}, mande burst quando ele estiver tonto. Mycomight: poças longe da luta.",
	["DELVE_CHAT_GRUDGE_PIT_OVERVIEW"] = "Delve de arena no SE de Harandar. Champion / Rotstalk / Invasion / Pharmacon. Chefes: Brightthorn, Gyrospore, Mycomight ou Replicating Venomborne.",
	["DELVE_CHAT_GRUDGE_PIT_ROUTE"] = "Champion: arena em ondas (os Sporbits ajudam). Rotstalk: chute os fãs, provoque a plateia. Invasion: liberte os lutadores, exploda os pontos de spawn.",
	["DELVE_CHAT_GRUDGE_PIT_TRASH"] = "Use os Sporbits na arena. Limpe as ondas da invasão. Não ignore os fãs no Rotstalk.",
	["DELVE_CHAT_GULF_OF_MEMORY_BOSS"] = "Lumenia: mate o add de {SPELL:@radiant_command} antes que ele te alcance. Mul'tha'ul: dissipe {SPELL:@hopeless_curse}, faça kite de {SPELL:@tear_it_down}, respeite {SPELL:@unanswered_call}.",
	["DELVE_CHAT_GULF_OF_MEMORY_OVERVIEW"] = "Oeste de Harandar. Munchies / Descent / Sporasaur. Chefes: Lumenia ou Mul'tha'ul.",
	["DELVE_CHAT_GULF_OF_MEMORY_ROUTE"] = "Munchies: Alnmoth Storm em movimento. Descent: acenda as velas, evite o escuro. Sporasaur: chute os Sporbits nos mobs com escudo.",
	["DELVE_CHAT_GULF_OF_MEMORY_TRASH"] = "Fique na luz no Descent. Chute os Sporbits cedo. Dá para andar enquanto canaliza o storm.",
	["DELVE_CHAT_PARHELION_PLAZA_BOSS"] = "Mate os 3 Voidcallers rápido (kick no Void Bolt). Se um sobreviver ao {SPELL:@devouring_nova}, Slaurna ganha um buff pesado. Desvie de {SPELL:@voidscar_raze} e lute no centro.",
	["DELVE_CHAT_PARHELION_PLAZA_OVERVIEW"] = "Oeste da Ilha de Quel'Danas (Nascente do Sol), um delve mais difícil. Bombing Run / Holding the Line / Brigade: chefe Gladius Slaurna. Caustic Crush: destrua o Ritual Pillar.",
	["DELVE_CHAT_PARHELION_PLAZA_ROUTE"] = "Bombing Run: dispositivo arcano para os portais (40s carregando). Holding the Line: armas + barricadas. Brigade: sentinelas contra os pilares. Caustic Crush: mate os Slimecallers e os Wavecallers.",
	["DELVE_CHAT_PARHELION_PLAZA_TRASH"] = "Kick no Void Bolt dos Voidcallers. Limpe as ondas de Devouring Host antes do chefe.",
	["DELVE_CHAT_SHADOWGUARD_POINT_BOSS"] = "Kick em {SPELL:@void_bolt_patram}. Mate o Void Emissary antes de {SPELL:@submit_to_the_void} ou o buff vai para Patram. Desvie de {SPELL:@discordant_hymn}.",
	["DELVE_CHAT_SHADOWGUARD_POINT_OVERVIEW"] = "Oeste da Tempestade do Caos. Calamitous / Wildlife / Stolen Mana contra os ethereals: chefe Chief-Arcanist Patram. Basilisk Blitz: chefe Disciple of Vashnik.",
	["DELVE_CHAT_SHADOWGUARD_POINT_ROUTE"] = "Calamitous: sobrecarregue os stabilizers com Arcane Charges. Wildlife: liberte os mobs com cuidado. Mana: Galvanic Blast nos recipientes até a Barrier cair. Basilisk Blitz: reconfigure os geradores, mate 4 Energized Basilisks.",
	["DELVE_CHAT_SHADOWGUARD_POINT_TRASH"] = "Interrompa os ethereals. Planeje com segurança o trajeto carregando as charges.",
	["DELVE_CHAT_SHADOW_ENCLAVE_BOSS"] = "Kick em {SPELL:@shadow_bolt}. O teleporte deixa uma poça — mantenha-o no centro. {SPELL:@shadowveil_annihilation}: mate os 3 Orbs (só o orbe sem escudo). Mande burst nos orbes.",
	["DELVE_CHAT_SHADOW_ENCLAVE_OVERVIEW"] = "SO da Floresta do Canto Eterno (Deatholme). Espelhos, suprimentos, traidor: chefe Lord Antenorian. Infiltrate and Ameliorate: chefe Abominable Blunder.",
	["DELVE_CHAT_SHADOW_ENCLAVE_ROUTE"] = "Espelhos: acerte os Shadow Nexuses para ter luz. Suprimentos: saqueie os itens de valor dos Twilight. Traidor: pare os rituais e persiga até o chefe.",
	["DELVE_CHAT_SHADOW_ENCLAVE_TRASH"] = "Luz do espelho = Dazzled (mais críticos). Interrompa os conjuradores de sombra. Não se amontoe em chão ruim.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_BOSS"] = "Todos os Voidcallers mortos antes de {SPELL:@gorge} ou ele acumula +dano. Kick em {SPELL:@calling_bolt}. {SPELL:@coalescing_malediction} termina num Voidcaller. Desvie de {SPELL:@crushing_rift} (4 callers).",
	["DELVE_CHAT_SUNKILLER_SANCTUM_OVERVIEW"] = "Leste da Tempestade do Caos. Variantes Core / Not Expected / Gravity. Chefe: Esuritus (ou 3 Umbraroot, sem chefe).",
	["DELVE_CHAT_SUNKILLER_SANCTUM_ROUTE"] = "Core: impeça os Domanaar de roubar os orbes (buff de velocidade + redução de dano). Not Expected: 3 Corrupted Umbraroot. Gravity: as singularidades derrubam os escudos.",
	["DELVE_CHAT_SUNKILLER_SANCTUM_TRASH"] = "Recolha os orbes no Core. Not What I Expected: puxe os 3 Corrupted Umbraroot um de cada vez.",
	["DELVE_CHAT_THE_DARKWAY_BOSS"] = "Kick nos Seekers. Desvie de {SPELL:@abyssal_burst}. {SPELL:@illusory_deceit}: fique longe das ilusões que explodem.",
	["DELVE_CHAT_THE_DARKWAY_OVERVIEW"] = "Arcway, norte de Luaprata. Focusers, Leyline ou 7 Aberrations: chefe Infiltrator Gulkat. Eggsplosive Growth: chefe Replicating Venomborne.",
	["DELVE_CHAT_THE_DARKWAY_ROUTE"] = "Focusers: leve os focusers de ley de volta ao centro. Leyline: ative os conduítes para os 3 cristais. Ogre: mate as 7 Unstable Aberrations no meio.",
	["DELVE_CHAT_THE_DARKWAY_TRASH"] = "Interrompa os Twilight Seekers e o Arcane Deluge. Puxe para fora dos cantos apertados.",
	["DELVE_CHAT_TORMENTS_RISE_BOSS"] = "Kick em todo {SPELL:@devouring_essence}. {SPELL:@dread_portal}: AoE nos adds até morrerem. {SPELL:@oblivion_shell} = teste de DPS. Não acumule {SPELL:@umbral_rage}.",
	["DELVE_CHAT_TORMENTS_RISE_OVERVIEW"] = "Delve Nemesis (Tempestade do Caos). Regras de Tier ? / ??. Chefe Nullaeus — Valira em Cura recomendada no ??.",
	["DELVE_CHAT_TORMENTS_RISE_ROUTE"] = "Portal dedicado (Shift-J / TomTom). Não é um delve de mundo rotativo.",
	["DELVE_CHAT_TORMENTS_RISE_TRASH"] = "Guarde os CDs para Nullaeus — não tem trash Pactsworn lá dentro.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_BOSS"] = "Desvie de {SPELL:@shade_cleave} (ficar em corpo a corpo impede {SPELL:@dark_pursuit}). Arraste Darza para fora de {SPELL:@bask_in_the_twilight} (+30% de dano lá dentro).",
	["DELVE_CHAT_TWILIGHT_CRYPTS_OVERVIEW"] = "SO de Zul'Aman (Trono Partido). Loa / Party Crasher / Trapped: chefe Blademaster Darza. Why'd it have to be snakes?: chefe Replicating Venomborne.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_ROUTE"] = "Loa: não cruze o caminho de Mot'amra. Party Crasher: escolta, armadilhas, alavancas. Trapped: reféns + alavancas.",
	["DELVE_CHAT_TWILIGHT_CRYPTS_TRASH"] = "Mot'amra = arremesso forte no caminho dele. Interrompa os invocadores. Preste atenção nas placas de armadilha.",
	["DELVE_NAME_ATAL_AMAN"] = "Atal'Aman",
	["DELVE_NAME_COLLEGIATE_CALAMITY"] = "Collegiate Calamity",
	["DELVE_NAME_GRUDGE_PIT"] = "The Grudge Pit",
	["DELVE_NAME_GULF_OF_MEMORY"] = "The Gulf of Memory",
	["DELVE_NAME_PARHELION_PLAZA"] = "Parhelion Plaza",
	["DELVE_NAME_SHADOWGUARD_POINT"] = "Shadowguard Point",
	["DELVE_NAME_SHADOW_ENCLAVE"] = "The Shadow Enclave",
	["DELVE_NAME_SUNKILLER_SANCTUM"] = "Sunkiller Sanctum",
	["DELVE_NAME_THE_DARKWAY"] = "The Darkway",
	["DELVE_NAME_TORMENTS_RISE"] = "Torment's Rise",
	["DELVE_NAME_TWILIGHT_CRYPTS"] = "Twilight Crypts",
	["DELVE_TIP_ATAL_AMAN_BOSS"] = "• {SPELL:@flaying_knife} divide espíritos — cada espírito que você recolhe dá +10% de dano (recolha-os de propósito).|n• Desvie de {SPELL:@raging_spirits} no chão.|n• Antes de {SPELL:@claim_spirits} terminar, recolha os seus espíritos ou Jin'Ma fica com o buff deles.|n• Disciple of Vashnik: sempre interrompa {SPELL:@malignance}, uma rajada de 4 segundos de glóbulos de veneno que acumulam dano e te deixam lento. A Valira não interrompe toda vez, então faça isso você mesmo.|n• Disciple of Vashnik: {SPELL:@toxic_froth} causa muito dano de veneno por 8 segundos, e se esconder atrás de uma parede não ajuda mais. Remova o veneno se a sua classe puder, use um defensivo ou coloque a Valira em Cura; depois pegue os orbes de cura.|n• Disciple of Vashnik: {SPELL:@living_venom} te empurra para trás e invoca uma gosma. Saia da área ao redor dele e mate a gosma antes que ela te alcance. No Tier 11, muitos jogadores o consideram o chefe mais difícil desta temporada: desça um tier se continuar morrendo.",
	["DELVE_TIP_ATAL_AMAN_OVERVIEW"] = "• Oeste de Zul'Aman (fronteira com a Floresta do Canto Eterno).|n• Ritual Interrupted, Toadly Unbecoming, Totem Annihilation.|n• Ritual Interrupted, Toadly Unbecoming e Totem Annihilation acabam em Spiritflayer Jin'Ma.|n• Temporada 2, Venomous Vapors: chefe final Disciple of Vashnik (também em Shadowguard Point).",
	["DELVE_TIP_ATAL_AMAN_ROUTE"] = "• Ritual: resgate os furbolgs Spiritpaw sequestrados espalhados pelo delve.|n• Toadly: use o Vilebranch Hex Stick para dissipar o feitiço dos Amani enquanto mata os invasores.|n• Totem: destrua os totens amaldiçoados para libertar Akil'zon; use as águias para chegar por outros caminhos.|n• Venomous Vapors: abra os 2 baús da primeira sala e pegue as ferramentas da Marla: {SPELL:@venomous_fireball}, que você joga numa Toxic Cloud para explodi-la (fique longe), e uma ferramenta que faz você pular muito alto. Derrote as 5 Venom Vipers; o Disciple of Vashnik espera no final.",
	["DELVE_TIP_ATAL_AMAN_TRASH"] = "• Interrompa as conjurações dos Vilebranch.|n• Variante Totem: priorize os totens que estão no caminho.|n• Puxe as feras para longe dos NPCs enfeitiçados que você quer salvar.|n• Venomous Vapors: as Venom Vipers fazem parte do objetivo, então mate as 5.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_BOSS"] = "• Hydrangea (Glow): mate as raízes de {SPELL:@wildroot_weave} antes de {SPELL:@lightbloom_salvo}; desvie das zonas de luz.|n• Garand (Faculty): desvie de {SPELL:@shadow_laceration} ou use um defensivo; espalhe-se para os saltos de {SPELL:@twilight_crash}.|n• Voidscorned Vagrant (Siege): saia da linha de {SPELL:@void_eruption}; interrompa {SPELL:@terrifying_power} sempre.|n• Academic Antitoxin: não há chefe final. O tesouro aparece quando a última etapa termina.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_OVERVIEW"] = "• Noroeste de Luaprata / Floresta do Canto Eterno (Universidade Talassiana).|n• Academy Under Siege -> Voidscorned Vagrant.|n• Faculty of Fear -> Infiltrator Garand.|n• Invasive Glow -> Hydrangea.|n• Academic Antitoxin (no mapa: An Elementary Antidote): sem chefe final. Em vez disso, aparece um tesouro.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_ROUTE"] = "• Under Siege: feche os portais do Caos e mate os Devouring Host.|n• Faculty of Fear: use o Eye of Revelation — os estudantes suspeitos brilham em amarelo através das paredes.|n• Invasive Glow: o Deweeder mata os Lightbloom pequenos e causa dano nos grandes.|n• Limpe os canteiros de Luminibulb no andar principal.|n• Academic Antitoxin: fale com Sir Finley Mrrgglton e depois junte 10 Research Tomes.|n• Academic Antitoxin: depois colete ingredientes e dê o antídoto a 7 Envenomed Denizens. As duas coisas contam ao mesmo tempo.|n• Academic Antitoxin: a barra de ingredientes precisa de 400. Os ingredientes pequenos dão 2, os médios 20 e os grandes 35, então pegue os grandes.|n• Academic Antitoxin: {SPELL:@fungal_pharmacon} limpa as poças de veneno e também acerta os inimigos num raio de 5 metros de onde cai.",
	["DELVE_TIP_COLLEGIATE_CALAMITY_TRASH"] = "• Under Siege: priorize os fechadores de portal.|n• Faculty: revele os estudantes disfarçados e mate-os antes que eles te emboscem.|n• Glow: canalize o Deweeder enquanto se move.|n• Não pule os canteiros de Luminibulb ou a run se arrasta.",
	["DELVE_TIP_GRUDGE_PIT_BOSS"] = "• Brightthorn: saia da linha de {SPELL:@solar_charge} (deixa zonas de Overbloom); interrompa {SPELL:@bloom_thorn}; vire de costas antes de {SPELL:@blinding_burst}.|n• Gyrospore: desvie das zonas de {SPELL:@fungalstorm} e mande burst durante os 10s de tontura; afaste-se de {SPELL:@fungsplosion}; saia da linha de {SPELL:@fungal_charge}.|n• Mycomight: solte as poças de {SPELL:@rancid_rain} longe da área de luta; desvie das ondas de choque de {SPELL:@fungis_fist}; saia da linha de {SPELL:@fling_chair}.|n• Replicating Venomborne: mate logo os Lesser Venomborne de {SPELL:@serpentogenesis} — vivos no próximo lançamento dele, eles o curam; saia das poças de {SPELL:@venom_splash_venomborne} (dano + lentidão); {SPELL:@hydra_strike} deixa um DoT que acumula.|n• Gyrospore: o DBM e o seu histórico de delves chamam esta luta de Spinshroom, um nome que a Blizzard reaproveitou de um chefe antigo. É a mesma luta.",
	["DELVE_TIP_GRUDGE_PIT_OVERVIEW"] = "• Sudeste de Harandar.|n• Lightbloom Invasion -> Brightthorn.|n• Arena Champion -> Gyrospore.|n• Dastardly Rotstalk -> Mycomight.|n• Fungal Pharmacon -> Replicating Venomborne.",
	["DELVE_TIP_GRUDGE_PIT_ROUTE"] = "• Arena Champion: derrote os lutadores, mate Bogdamp, Moldrus e 5 Spewing Deathcaps, colete 6 Mold Samples e finque o seu estandarte. Depois vem Gyrospore.|n• Dastardly Rotstalk: você faz o papel de vilão — chute os fãs, provoque a plateia (dá para andar enquanto provoca).|n• Lightbloom Invasion: ondas de inimigos, liberte lutadores para explodir os pontos de spawn, construa defesas.",
	["DELVE_TIP_GRUDGE_PIT_TRASH"] = "• Arena Champion: use os Sporbits aliados. Eles causam dano extra nos lutadores da arena.|n• Lightbloom Invasion: limpe as ondas antes do chefe.|n• Rotstalk: mantenha a plateia sob controle — os fãs machucam se você ignorar.",
	["DELVE_TIP_GULF_OF_MEMORY_BOSS"] = "• Lumenia: mate o add de {SPELL:@radiant_command} antes que ele te alcance (ele explode).|n• Desvie das manchas de {SPELL:@searing_light}, a não ser que você as use no add.|n• Mul'tha'ul: interrompa ou dissipe {SPELL:@hopeless_curse}.|n• Faça kite para longe dos tentáculos de {SPELL:@tear_it_down}.|n• Mantenha distância durante {SPELL:@unanswered_call} (dano alto, movimento lento).",
	["DELVE_TIP_GULF_OF_MEMORY_OVERVIEW"] = "• Oeste de Harandar (Covil dos Ecos / Har'alnor).|n• Três variantes.|n• Chefes: Lumenia (Munchies / Sporasaur) e Mul'tha'ul (Descent of the Haranir).",
	["DELVE_TIP_GULF_OF_MEMORY_ROUTE"] = "• Alnmoth Munchies: use o Alnmoth Storm do botão de ação extra enquanto anda — devore arbustos ou ajude contra os Rutaani.|n• Descent: acenda as velas gigantes; você recebe mais dano nas áreas escuras.|n• Sporasaur: chute os Sporbits de retículo verde nos Sporasaurs para tirar o escudo deles.",
	["DELVE_TIP_GULF_OF_MEMORY_TRASH"] = "• Fique nas áreas iluminadas durante o Descent.|n• Chute os Sporbits antes que eles explodam.|n• Canalize o Alnmoth Storm em movimento — dá para andar e conjurar ao mesmo tempo.",
	["DELVE_TIP_PARHELION_PLAZA_BOSS"] = "• Gladius Slaurna: mate rápido os três Sacrificial Voidcallers dele e interrompa o Void Bolt deles.|n• Gladius Slaurna: cada Voidcaller ainda vivo quando {SPELL:@devouring_nova} termina faz ele bater mais forte e receber menos dano. Nos tiers altos isso pode causar um wipe.|n• Gladius Slaurna: saia da linha de {SPELL:@voidscar_raze}. Ela costuma mirar na Valira, então não fique entre os dois.|n• Gladius Slaurna: lute perto do centro, para que {SPELL:@devouring_nova} não te derrube da plataforma.",
	["DELVE_TIP_PARHELION_PLAZA_OVERVIEW"] = "• Oeste da Ilha de Quel'Danas (área da Nascente do Sol).|n• Libera com o March on Quel'Danas (fim de março de 2026).|n• Bombing Run, Holding the Line e March of the Arcane Brigade acabam em Gladius Slaurna.|n• Um dos delves mais difíceis de Midnight.|n• Caustic Crush (nova na 12.1): os Slime Shamen of Ula'tek invocam gosmas e mandam ondas de veneno. O último objetivo é um Ritual Pillar, não Gladius Slaurna.",
	["DELVE_TIP_PARHELION_PLAZA_ROUTE"] = "• Bombing Run: use o Improvised Arcane Device nos portais do Caos (limite de 40s carregando; você o solta em combate).|n• Holding the Line: armas da Bastilha da Tormenta + reconstrua as barricadas.|n• March of the Arcane Brigade: acorde as máquinas Sentinel; elas andam até os pilares do Caos. Destrua 3 pilares e mate Devouring Host para encher a barra.|n• Caustic Crush: fale com Vindicator Xayann. Depois mate as gosmas, 4 Shaman Slimecallers e 6 Ula'tek Wavecallers.|n• Caustic Crush: pegue {SPELL:@fungal_pharmacon} no caminho. Jogue nas Ula'tek Poison Pools para limpá-las. Ele também causa dano nos inimigos perto de onde cai.|n• Caustic Crush: os objetivos também pedem que você use uma toca. O último objetivo de todos é destruir o Ritual Pillar.",
	["DELVE_TIP_PARHELION_PLAZA_TRASH"] = "• Bombing Run: nunca saia de perto de um portal antes de explodi-lo. Ele fecha de vez e você não consegue terminar a run.|n• Limpe as ondas de Devouring Host antes de Slaurna.|n• Caustic Crush: desvie de toda onda de veneno. Um acerto te atordoa e causa muito dano de Natureza.",
	["DELVE_TIP_SHADOWGUARD_POINT_BOSS"] = "• Interrompa {SPELL:@void_bolt_patram}.|n• Mate o Void Emissary antes de {SPELL:@submit_to_the_void} terminar (você ganha Vers + CDR; se falhar, o buff vai para Patram).|n• Saia da linha das zonas do Caos de {SPELL:@discordant_hymn} (lentidão + dano).|n• Disciple of Vashnik: sempre interrompa {SPELL:@malignance}, uma rajada de 4 segundos de glóbulos de veneno que acumulam dano e te deixam lento. A Valira não interrompe toda vez, então faça isso você mesmo.|n• Disciple of Vashnik: {SPELL:@toxic_froth} causa muito dano de veneno por 8 segundos, e se esconder atrás de uma parede não ajuda mais. Remova o veneno se a sua classe puder, use um defensivo ou coloque a Valira em Cura; depois pegue os orbes de cura.|n• Disciple of Vashnik: {SPELL:@living_venom} te empurra para trás e invoca uma gosma. Saia da área ao redor dele e mate a gosma antes que ela te alcance. No Tier 11, muitos jogadores o consideram o chefe mais difícil desta temporada: desça um tier se continuar morrendo.",
	["DELVE_TIP_SHADOWGUARD_POINT_OVERVIEW"] = "• Oeste da Tempestade do Caos (ao norte da Toca do Caos Abundante).|n• Quatro variantes. Em três você enfrenta os Shadowguard Ethereals; em Basilisk Blitz você os ajuda a retomar o ponto.|n• Chefe final em três variantes: Chief-Arcanist Patram. Basilisk Blitz acaba no Disciple of Vashnik.|n• Temporada 2, Basilisk Blitz: chefe final Disciple of Vashnik (também em Atal'Aman).",
	["DELVE_TIP_SHADOWGUARD_POINT_ROUTE"] = "• Calamitous: sobrecarregue os Void Stabilizers com as Arcane Charges (dá buff de velocidade; as explosões matam os mobs — não fique dentro delas).|n• Captured Wildlife: liberte as criaturas do Caos (a área de efeito delas ainda te acerta).|n• Stolen Mana: pegue o rifle e use Galvanic Blast nos recipientes de mana até a Arcane Barrier cair.|n• Basilisk Blitz: fale com o ethereal ferido no início. Depois reconfigure o Energy Distributor e mate o Ula'tek Basilisk.|n• Basilisk Blitz: use o Waygate para seguir em frente. Depois reconfigure os 4 Power Generators e mate os 4 Energized Basilisks.|n• Basilisk Blitz: o Disciple of Vashnik só vira seu objetivo depois que os 4 Energized Basilisks estiverem mortos.",
	["DELVE_TIP_SHADOWGUARD_POINT_TRASH"] = "• Calamitous: planeje as sobrecargas com segurança enquanto carrega as Arcane Charges.|n• Packs de ethereals: interrompa as conjurações.|n• Variante Wildlife: dê espaço às criaturas libertadas.|n• Basilisk Blitz: enquanto a barreira de um basilisco aguenta, ele joga raios de veneno em você. Entrar na barreira te atordoa por alguns segundos.",
	["DELVE_TIP_SHADOW_ENCLAVE_BOSS"] = "• Lord Antenorian: interrompa {SPELL:@shadow_bolt} sempre que puder.|n• Lord Antenorian: os teleportes dele deixam uma poça que causa dano. Mantenha-o perto do centro.|n• Lord Antenorian: {SPELL:@shadowveil_annihilation} é uma canalização letal. Destrua os 3 Shadow Orbs: só o orbe sem escudo recebe dano, e cada morte tira o escudo do seguinte.|n• Lord Antenorian: com todos os orbes mortos, o escudo dele quebra, a canalização para e ele recebe dano extra por alguns segundos.|n• Lord Antenorian: guarde seu burst para os orbes. A Valira ajuda a quebrá-los.|n• Abominable Blunder (Infiltrate and Ameliorate): Corrosive Bile é o ataque básico de veneno dele. Aguente curando.|n• Abominable Blunder (Infiltrate and Ameliorate): {SPELL:@searing_spew} causa dano e deixa lento todo mundo num raio de 14 metros dele. Afaste-se quando ele conjurar.|n• Abominable Blunder (Infiltrate and Ameliorate): Acid Spray manda ondas de ácido por alguns segundos. Continue desviando para os lados até acabar.",
	["DELVE_TIP_SHADOW_ENCLAVE_OVERVIEW"] = "• Sudoeste da Floresta do Canto Eterno (Ruins of Deatholme).|n• Quatro variantes: Mirror Shine, Shadowy Supplies, Traitor's Due e Infiltrate and Ameliorate (nova na 12.1).|n• Traitor's Due: pare os rituais, os orbes do Caos e os cultistas (nivelamento).|n• Mirror Shine, Shadowy Supplies e Traitor's Due acabam em Lord Antenorian. Infiltrate and Ameliorate acaba em Abominable Blunder.",
	["DELVE_TIP_SHADOW_ENCLAVE_ROUTE"] = "• Mirror Shine: carregue os espelhos pelos corredores escuros; acerte os Shadow Nexuses para espalhar a luz (evita os Grues).|n• Shadowy Supplies: saqueie os itens de valor dos Twilight's Blade nos mobs ou no chão.|n• Traitor's Due: persiga Antenorian pelo delve até a sala do chefe.|n• Infiltrate and Ameliorate: fale com Scout Lok'aemon e depois chute 5 Ula'tek Summoners no abismo.|n• Infiltrate and Ameliorate: sabote 4 caldeirões colocando ingredientes estranhos. Alguns ingredientes ficam no alto: use os cogumelos de pulo.|n• Infiltrate and Ameliorate: em seguida, mate o Ula'tek Supreme Summoner e assista à invocação. Depois vem Abominable Blunder, o chefe final.|n• Infiltrate and Ameliorate: pegue {SPELL:@fungal_pharmacon} e jogue nas poças de veneno para limpá-las. Ele também causa dano nos inimigos perto de onde cai.",
	["DELVE_TIP_SHADOW_ENCLAVE_TRASH"] = "• Na luz do espelho, você e os inimigos ficam com Dazzled (mais chance de crítico).|n• Interrompa os conjuradores de sombra.|n• Limpe os Twilight's Blade durante Shadowy Supplies.|n• Não se amontoe em chão perigoso; puxe com cuidado nos corredores estreitos.",
	["DELVE_TIP_SUNKILLER_SANCTUM_BOSS"] = "• Mate todos os Voidcallers antes de {SPELL:@gorge} ou ele ganha +dano por 30s a cada um que devorar.|n• Interrompa {SPELL:@calling_bolt}.|n• Quando {SPELL:@coalescing_malediction} termina ou é dissipada, surge um Voidcaller. Só dissipe quando estiver pronto para matar esse add.|n• Desvie de {SPELL:@crushing_rift} (gera 4 Voidcallers).",
	["DELVE_TIP_SUNKILLER_SANCTUM_OVERVIEW"] = "• Leste da Tempestade do Caos (entrada da Torre do Caos).|n• Core of the Problem e The Gravitational Effect acabam em Esuritus. Not What I Expected não tem chefe.|n• Not What I Expected: sem chefe — acaba depois de você matar 3 Corrupted Umbraroot.",
	["DELVE_TIP_SUNKILLER_SANCTUM_ROUTE"] = "• Core of the Problem: portais + impeça os Domanaar de roubar os Energized Orbs (o buff do orbe dá velocidade + redução de dano).|n• Not What I Expected: clique em 7 Lightbloom Crates, use o Sanctum Security Panel e encha a barra de mortes (inimigos Lightbloom e do Caos contam). Depois mate 3 Corrupted Umbraroot.|n• Gravitational Effect: use as microssingularidades para se locomover e derrubar os escudos do chefe.|n• Not What I Expected: passe por um Displacement Portal. Uma cópia sua então luta ao seu lado por uns 5 minutos.",
	["DELVE_TIP_SUNKILLER_SANCTUM_TRASH"] = "• Na variante Core, recolha os orbes para aguentar mais.|n• Not What I Expected: os 3 Corrupted Umbraroot são elites. Puxe um de cada vez.|n• Not What I Expected: interrompa o Lightbloom Beam dos Corrupted Umbraroot e desvie de Blooming Bile (um frontal que gera adds) e de Rotting Charge (deixa uma poça).",
	["DELVE_TIP_THE_DARKWAY_BOSS"] = "• Interrompa os Twilight Seekers.|n• Desvie de {SPELL:@abyssal_burst} (cone frontal).|n• {SPELL:@illusory_deceit}: ilusões que explodem — mantenha distância enquanto cuida de Gulkat.|n• Replicating Venomborne: mate logo os Lesser Venomborne de {SPELL:@serpentogenesis} — vivos no próximo lançamento dele, eles o curam; saia das poças de {SPELL:@venom_splash_venomborne} (dano + lentidão); {SPELL:@hydra_strike} deixa um DoT que acumula.",
	["DELVE_TIP_THE_DARKWAY_OVERVIEW"] = "• Norte de Luaprata / Floresta do Canto Eterno (o Arcway).|n• Focusers Under Pressure, Leyline Technician, Ogre Powered (7 Unstable Aberrations).|n• Focusers, Leyline, Ogre Powered -> Infiltrator Gulkat.|n• Eggsplosive Growth (12.1) -> Replicating Venomborne.",
	["DELVE_TIP_THE_DARKWAY_ROUTE"] = "• Focusers: ache os Ley Line Focusers e leve-os de volta ao centro do delve.|n• Leyline: ative os conduítes uma vez por linha para carregar os três cristais de foco.|n• Ogre Powered: mate as 7 Unstable Aberrations na seção do meio antes de Gulkat.",
	["DELVE_TIP_THE_DARKWAY_TRASH"] = "• Interrompa os Twilight Seekers e o Arcane Deluge das aberrações.|n• Variante Leyline: mate os Twilight's Blade enquanto direciona a energia.|n• Puxe para longe dos cantos nos corredores estreitos do Arcway.",
	["DELVE_TIP_TORMENTS_RISE_BOSS"] = "• Interrompa {SPELL:@devouring_essence} em toda conjuração (é DoT + alimenta os stacks de {SPELL:@umbral_rage}).|n• {SPELL:@dread_portal}: 100% de redução de dano até todos os adds morrerem — mande burst de AoE assim que eles aparecerem.|n• A fase de {SPELL:@oblivion_shell} é um teste de DPS.|n• {SPELL:@umbral_rage}: +10% de dano por stack se os adds ou os DoTs ficarem de pé — mate os adds rápido.",
	["DELVE_TIP_TORMENTS_RISE_OVERVIEW"] = "• Tempestade do Caos — o Delve Nemesis da Série 1 (o desafio que fecha a temporada).|n• Tier ? depois de qualquer T7 com 1+ vida; Tier ?? depois de qualquer T10 com 1+ vida.|n• Chefe: Nullaeus.|n• Valira em Cura é fortemente recomendada no Tier ??.",
	["DELVE_TIP_TORMENTS_RISE_ROUTE"] = "• Portal de instância dedicado (não é um delve de mundo rotativo).|n• Use o Adventure Guide (Shift-J) ou o TomTom.|n• Recompensa semanal: em vez disso, a Beacon of Hope pode puxar Nullaeus para dentro de um delve normal a 50%.",
	["DELVE_TIP_TORMENTS_RISE_TRASH"] = "• Os mobs Pactsworn ficam nos delves normais, não dentro de Torment's Rise.|n• Administre suas recargas — guarde os defensivos e as interrupções para Nullaeus.",
	["DELVE_TIP_TWILIGHT_CRYPTS_BOSS"] = "• Blademaster Darza: desvie de {SPELL:@shade_cleave}. Lutar colado nela impede o avanço de {SPELL:@dark_pursuit}.|n• Blademaster Darza: {SPELL:@bask_in_the_twilight} deixa uma zona do Caos no chão.|n• Arraste Darza para fora dela ou ela ganha +30% de dano enquanto estiver lá dentro.|n• Replicating Venomborne (Why'd it have to be snakes?): mate na hora os Lesser Venomborne de {SPELL:@serpentogenesis}. Se ainda estiverem vivos no próximo lançamento dele, eles o curam.|n• Replicating Venomborne (Why'd it have to be snakes?): saia das poças de {SPELL:@venom_splash_venomborne}. Elas causam dano e te deixam lento.|n• Replicating Venomborne (Why'd it have to be snakes?): {SPELL:@hydra_strike} deixa em você um dano de veneno que acumula. Fique de olho nos stacks e aguente curando.",
	["DELVE_TIP_TWILIGHT_CRYPTS_OVERVIEW"] = "• Sudoeste de Zul'Aman (Trono Partido).|n• Loosed Loa (evite Mot'amra), Party Crasher, Trapped! e, nova na 12.1: Why'd it have to be snakes?|n• Loosed Loa, Party Crasher e Trapped! acabam em Blademaster Darza. Why'd it have to be snakes? acaba em Replicating Venomborne.",
	["DELVE_TIP_TWILIGHT_CRYPTS_ROUTE"] = "• Loosed Loa: use o Evasive Elixir para explorar; mate os Skeleton Charmers e os totens — acompanhe Mot'amra e não cruze o caminho dele.|n• Loosed Loa: desde o hotfix de 10 de setembro, esta variante tem Explorer's League Supplies e uma Abandoned Restoration Stone.|n• Party Crasher: mate os 4 Twilight Summoners (eles aparecem no seu mapa) e acione 7 Suspicious Levers. As armadilhas de urso te atordoam por uns 2 segundos.|n• Trapped: salve os reféns e ache as alavancas pelo labirinto.|n• Why'd it have to be snakes?: ajude Harrison Jones a achar as relíquias perdidas nas criptas.|n• Why'd it have to be snakes?: pisar nas cobras faz parte do objetivo, mas elas explodem quando você pisa nelas.|n• Why'd it have to be snakes?: pegue {SPELL:@fungal_pharmacon} e jogue nas manchas de veneno para limpá-las.",
	["DELVE_TIP_TWILIGHT_CRYPTS_TRASH"] = "• Mot'amra bate forte e te arremessa longe se você andar em cima dele.|n• Party Crasher: preste atenção nas placas de armadilha no chão.|n• Interrompa os invocadores dos Twilight's Blade.",
})
